          }
        }.map {x => (x._1, implicitly[Numeric[E]].plus(dis, x._2))}
      }
      ret ++= updated
      for (x <- updated) {
        if (vis.get(x._1) == None) {
          pq.enqueue((x._2, x._1))
          vis += Tuple2(x._1, true)
        }
      }
    }
    ret
  }

  def buildGraph(edges : List[(N, N, E)]) : Map[N, List[(N, E)]]  = {
    edges.groupBy(_._1).map {
      case (k, v) => (k, v.map {x => (x._2, x._3)})
