import scala.collection.mutable
import scala.collection.mutable.ArrayBuffer
import scala.math.Ordering.Implicits._

class Graph[T : Numeric] {

  def dijkstra(graph : ArrayBuffer[ArrayBuffer[(Int, T)]], source : Int) : ArrayBuffer[T] = {
    val pq = new mutable.PriorityQueue[(T, Int)]()
    val ret = new ArrayBuffer[T]() ++ Range(0, graph.size).map(x => Int.MaxValue.asInstanceOf[T])

    ret.update(source, 0.asInstanceOf[T])
    pq.enqueue((0.asInstanceOf[T], source))

    while (! (pq.isEmpty)) {
      val (dis, node) = pq.dequeue()
      for ((n, e) <- graph(node)) {
        val ndis = implicitly[Numeric[T]].plus(dis, e)
        if (ndis < ret(n)) {
          ret.update(n, ndis)
          pq.enqueue((ndis, n))
        }
      }
    }
    ret
  }
}

object Main {
  def main(args: Array[String]) {
    val in = io.Source.createBufferedSource(System.in)
    //val in = io.Source.fromFile("src/main/resources/test.in")

    val data = in.getLines().toList
    val info = data.head.split("\\s+").map(_.toInt).toList
    val edges = data.drop(1).map {x => x.split("\\s+").map(_.toInt)}
    val graph = new ArrayBuffer[ArrayBuffer[(Int, Int)]]()
    for (_ <- Range(0, info.head)) graph += new ArrayBuffer[(Int, Int)]()

    for (e <- edges) {
      val tmp = e.toList
      graph(tmp.head) += Tuple2(tmp.tail.head, tmp.last)
    }
    val g = new Graph[Int]
    val ret = g.dijkstra(graph, info.last)
    for (n <- Range(0, info.head)) {
      if (ret(n) == Int.MaxValue) {
        println("INF")
      } else {
        println(ret(n))
      }
    }
  }
}

