import scala.collection.mutable
import scala.math.Ordering.Implicits._
import scala.collection.mutable.HashMap

class Graph[N : Ordering, E : Numeric] {

  def dijkstra(graph : Map[N, List[(N, E)]], source : N): HashMap[N, E] = {
    val pq = new mutable.PriorityQueue[(E, N)]()
    val ret = new HashMap[N, E]()
    val vis = new HashMap[N, Boolean]()
    ret += Tuple2(source, 0.asInstanceOf[E])
    pq.enqueue((0.asInstanceOf[E], source))
    vis += Tuple2(source, true)

    while (! (pq.isEmpty)) {
      val (dis, node) = pq.dequeue()
      val updated = graph.get(node) match {
        case None => List()
        case Some(xs) => xs.filter {
          case (n, e) => {
            ret.get(n) == None || ( implicitly[Numeric[E]].plus(dis, e) < ret.get(n).get)
          }
        }.map {x => (x._1, implicitly[Numeric[E]].plus(dis, x._2))}
      }
      ret ++= updated
      for (x <- updated) {
        if (vis.get(x._1) == None) {
          pq.enqueue((x._2, x._1))
          vis += Tuple2(x._1, true)
        }
      }
    }
    ret
  }

  def buildGraph(edges : List[(N, N, E)]) : Map[N, List[(N, E)]]  = {
    edges.groupBy(_._1).map {
      case (k, v) => (k, v.map {x => (x._2, x._3)})
    }
  }
}


