import scala.collection.mutable
import scala.collection.mutable.ArrayBuffer
import scala.math.Ordering.Implicits._

class Graph[T : Numeric] {

  def dijkstra(graph : ArrayBuffer[ArrayBuffer[(Int, T)]], source : Int) : ArrayBuffer[Option[T]] = {
    val pq = new mutable.PriorityQueue[(T, Int)]()
    val ret = new ArrayBuffer[Option[T]]() ++ Range(0, graph.size).map(x => None)

    ret.update(source, Some(0.asInstanceOf[T]))
    pq.enqueue((0.asInstanceOf[T], source))

    while (! (pq.isEmpty)) {
      val (dis, node) = pq.dequeue()
      for ((n, e) <- graph(node)) {
        val ndis = implicitly[Numeric[T]].plus(dis, e)
        ret(n) match {
          case None => ret.update(n, Some(ndis)); pq.enqueue((ndis, n))
          case Some(x) => if (x > ndis) { ret.update(n, Some(ndis)); pq.enqueue((ndis, n))}
        }
      }
    }
    ret
  }
}

