    def makeEArray() = for (f::t::w::_ <- edges) earry.update(f, (t, w)::earry(f))
    def nexts(n:Int):List[(Int,Int)] = earry(n)
    def dijkstra():Array[Option[Long]] = {
      def iter():Unit = {
        if (!queue.isEmpty) {
          val number = queue.deque.get
          // println(s"Dequed:$number")
          varry(number.vid) match {
            case Some(x) => if (x > number.cost) varry.update(number.vid, Some(number.cost))
            case None => varry.update(number.vid, Some(number.cost))
          }
          for ((n ,c) <- nexts(number.vid)) {
            val cost = number.cost + c
            varry(n) match {
              case Some(x) if x > cost => queue.enque(Number(n, cost))                   
              case None => queue.enque(Number(n, cost))
              case _ =>
            }
          }
          iter()
        }
      }
      makeEArray()
      queue.enque(Number(start,0))
      iter()
      varry
    }
  }

