#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using Cost = ll;

const Cost INF = 1e12;

struct Edge {
	int from, to;
	Cost cost;
	Edge() {}
	Edge(int f, int t, Cost c) : from(f), to(t), cost(c) {}
	bool operator<(const Edge& e) const {
		return cost < e.cost;
	}
	bool operator>(const Edge& e) const {
		return cost > e.cost;
	}
};

using Edges = vector<Edge>;
using Graph = vector<Edges>;

vector<Cost> Dijkstra(const Graph& G, int s) {
	int n = G.size();
	vector<Cost> d(n, INF);
	priority_queue<Edge, vector<Edge>, greater<Edge>> pq;
	pq.emplace(s, s, 0);
	d[s] = 0;
	while (!pq.empty()) {
		auto p = pq.top(); pq.pop();
		int v = p.to;
		Cost cost = d[p.from] + p.cost;
		if (cost > d[v]) continue;
		for (auto e : G[v]) if (d[e.to] > cost + e.cost) {
			pq.push(e);
			d[e.to] = cost + e.cost;
		}
	}
	return d;
}

int main()
{
	ios::sync_with_stdio(false), cin.tie(0);
	int V, E, r;
	cin >> V >> E >> r;
	Graph G(V);
	for (int i = 0, s, t, d; i < E; i++) {
		cin >> s >> t >> d;
		G[s].emplace_back(s, t, d);
	}
	auto res = Dijkstra(G, r);
	for (auto ans : res) {
		if (ans == INF) puts("INF");
		else printf("%d\n", (int)ans);
	}
	return 0;
}

