void dijkstra(const GraphE& g, vector<ll>& dist, int begin, ll inf = 5e15) {
    dist.resize(g.n);
    fill(dist.begin(), dist.end(), inf);

    vector<int> visited(g.n);

    dist[begin] = 0;
    for (int v = begin; v != -1; ) {
        visited[v] = true;
        for (int ei : g.vertex_to[v]) {
            auto e = g.edges[ei];
            dist[e.to(v)] = min(dist[e.to(v)], dist[v] + e.value);
        }
        v = -1;
        for (int i = 0; i < g.n; ++i)
            if (!visited[i] && (v == -1 || dist[i] < dist[v]))
                v = i;
    }
}





