	scanf("%d%d%d", &V, &E, &r);
	for (int i = 0; i < E; i++) {
		int s, t, w;
		scanf("%d%d%d", &s, &t, &w);
		graph[s].push_back({ t, w });
	}
}

void dij_sp() {
	dist[r] = 0;
	std::set< std::pair<long long, int> > setds;
	setds.insert(std::make_pair(dist[r], r));
	while (!setds.empty()) {
		std::pair<long long, int> fir = *(setds.begin());
		setds.erase(setds.begin());
		//
		int u = fir.second;
		if (dist[u] == INF) { return; }
		for (std::vector<Edge>::iterator it = graph[u].begin(); it != graph[u].end(); it++) {
			int v = it->vx;
			if (visit[v]) { continue; }
			if (dist[v] > dist[u] + it->w) {
				if (dist[v] != INF) {
					setds.erase(setds.find(std::make_pair(dist[v], v)));
				}
				//update the set
				dist[v] = dist[u] + it->w;
				setds.insert(std::make_pair(dist[v], v));
			}
		}
		//mark visited
		visit[u] = 1;
	}
}

