void solve1(void) {
    vll dist(n, INF);
    priority_queue<P, vector<P>, greater<P> > q;
    q.push(P(0, st)); dist[st] = 0;
    while (q.size()) { 
        // q = {(d, v)} : 未確定な頂点vに距離dで到達可能である（dは最適とは限らない）
