typedef pair<ll, ll> P; //first: ???????????¢???second: ??????????????? 

struct edge{
    ll to;
    ll cost;
};

ll V=0;
vector<edge > G[MAX_V];
ll d[MAX_V];

void dijkstra(ll s){
  priority_queue<P, vector<P>, greater<P> > qu;
  fill(d, d + V, INF);
  d[s] = 0;
  qu.push(P(0,s));
  while(!qu.empty()){
    P p = qu.top(); qu.pop();
    ll v = p.second;    
    if(d[v] < p.first) continue;
    for(ll i = 0; i < G[v].size(); i++){
      edge e = G[v][i];
      if(d[e.to] > d[v] + e.cost){
	d[e.to] = d[v] + e.cost;
	qu.push(P( d[e.to], e.to ));
      }
    }
  }
}


