//typedef complex<double> P;
typedef pair<int, int> P;
const int MAX_V = 100010;
const int INF = 1e9 + 7;

int cost[MAX_V][MAX_V];

int dijkstra(const int cost[MAX_V][MAX_V], int s, int t, int V){
  priority_queue<P, vector<P>, greater<P> > open;
  open.push(P(s, 0));
  int closed[MAX_V];
  REP(i, V) closed[i] = INF;
  while(!open.empty()){
    P now = open.top(); open.pop();
    if(closed[now.first] <= now.second) continue;
    closed[now.first] = now.second;
    REP(i, V){
      if(cost[now.first][i] == INF || cost[now.first][i] + now.second >= closed[i]) continue;
      closed[now.first] = now.second;
      open.push(P(i, cost[now.first][i] + now.second));
    }
  }
  //memcpy(ans, closed, sizeof(closed));
  REP(i, V){
    if(closed[i] == INF) cout <<"INF" <<endl;
    else cout <<closed[i] <<endl;
  }
  return closed[t];
}

