	node[r].cost=0;
	node[r].visited=true;
	pq.push(node[r]);
	while(!pq.empty()){
		nodes node_now=pq.top();
		pq.pop();
		for(int lp=0;lp<(int)node_now.path.size();lp++){
			int nextcost=node_now.path[lp].second+node_now.cost;
