    VISIT[d] = 1;
    if (d == s) return 0;
    int i, min = SUPER_LARGE;
    for(i = 0; i < V; i++){
        if (A[i][d] != -1){
            int cnd = A[i][d] + DP(s, i);
            if (cnd < min) min = cnd;
        }
    }
    MEMO[d] = min;
    return min;
}
void input(void){
    scanf("%d%d%d", &V, &E, &R);
    initA();
    int i, a, b, w;
    for (i = 0; i < E; i++){
        scanf("%d%d%d", &a, &b, &w);
        A[a][b] = w;
    }
}
void initA(void){
    int i, j;
    for(i = 0; i < V; i++)
        for(j = 0; j < V; j++) A[i][j] = -1;
}
void init(void){
    int i;
    for(i = 0; i < V; i++){
        MEMO[i] = 0;
        VISIT[i] = 0;
    }
}

