vector<int> dijkstra(vector<vector<edge> >& G,int s)
{
    int N=G.size();
    vector<int> dist(N,INF); dist[s]=0;
    priority_queue<pii,vector<pii>,greater<pii> > Q;
    Q.push(pii(0,s));

    while(!Q.empty())
    {
	int d=Q.top().first;
