struct Dijkstra
{
	//距離の型を決めよう！！！！！！！！！！！！！
	typedef ll dType;
	dType inf = 1e18;

	typedef pair<dType, int> P;
	struct edge{int to; dType cost;};

	//始点からの距離
	vector <dType> dis;
	//隣接リスト
	vector <vector <edge>> adj;

	Dijkstra(int N) : dis(N, INFL), adj(N){}

	void add_edge(int s, int t, dType cost, bool isdirected = 0)
	{
		adj[s].pb((edge{t, cost}));
		if (!isdirected)
		{
			adj[t].pb((edge{s, cost}));
		}
	}

	void calc(int s)
	{
		fill(all(dis), inf);
		dis[s] = 0;
		priority_queue<P, vector<P>, greater<P>> q;

		q.push(P(0, s));

		while(!q.empty())
		{
			P p = q.top(); q.pop();
			int now = p.snd;
			if (dis[now] < p.fst)
			{
				continue;
			}
			for (edge e : adj[now])
			{
				if (dis[e.to] > dis[now] + e.cost)
				{
					dis[e.to] = dis[now] + e.cost;
					q.push(P(dis[e.to], e.to));
				}
			}
		}
	}

};



