  for (int i = 0; i < vn; i++) {
      V[i] = new int[vn];
  }
  for (int i = 0; i < vn; i++) {
    for (int j = 0; j < vn; j++)
      V[i][j] = 1000000000;
  }
  for (int i = 0; i < en; i++) {
    int s, t, d; cin >> s >> t >> d;
    V[s][t] = d;
  }
  for (int g = 0; g < vn; g++) {
    for (int i = 0; i < vn; i++)
      C[i] = V[r][i];
    set<int> U;
    for (int i = 0; i < vn; i++)
      if (i != r)
        U.insert(i);
    int w = r;
    int cmin;
    while (!U.empty() && w != g) {
      /*for (int i = 0; i < vn; i++)
        cout << C[i] << " ";
      cout << endl;*/
      cmin = 1000000000;
      for (auto it = U.begin(); it != U.end(); ++it) {
        if (C[*it] < cmin) {
          cmin = C[*it];
          w = *it;
        }
      }
      if (cmin == 1000000000)
        break;
      //cout << "w:" << w << endl;
      U.erase(w);
      for (auto it = U.begin(); it != U.end(); ++it)
        C[*it] = min(C[*it], C[w]+V[w][*it]);
    }
    if (g == r)
      cout << 0 << endl;
    else if (cmin == 1000000000)
      cout << "INF" << endl;
    else
      cout << C[g] << endl;
  }
