template<typename T>
using MaxHeap = priority_queue<T, vector<T>, less<T>>;
template<typename T>
using MinHeap = priority_queue<T, vector<T>, greater<T>>;

template<typename T, typename C, typename Comp>
T POP(priority_queue<T,C,Comp>& que) {
    T x = que.top(); que.pop();
    return x;
}

pair<vector<i64>,vector<i64>> graph_dijkstra(const vector<vector<pair<i64,i64>>>& g, i64 start) {
    i64 n = SIZE(g);
    vector<i64> d(n, INF);
    vector<i64> parent(n, -1);

    MinHeap<pair<i64,i64>> que;

    d[start] = 0;
    que.emplace(0, start);

    i64 n_remain = n;
    while(!que.empty()) {
        i64 dmin,vmin; tie(dmin,vmin) = POP(que);

        if(d[vmin] < dmin) continue;

        if(--n_remain == 0) break;

        for(const auto& p : g[vmin]) {
            i64 to,cost; tie(to,cost) = p;

            i64 d_new = dmin + cost;
            if(d_new < d[to]) {
                d[to] = d_new;
                parent[to] = vmin;
                que.emplace(d_new, to);
            }
        }
    }

    return { d, parent };
}

void solve() {
    i64 N; RD(N);
    i64 M; RD(M);
    i64 S; RD(S);

    vector<vector<pair<i64,i64>>> G(N);
    REP(_, M) {
        i64 from,to; RD(from); RD(to);
        i64 cost; RD(cost);
        G[from].emplace_back(to,cost);
    }

    vector<i64> d;
    vector<i64> parent;
    tie(d,parent) = graph_dijkstra(G, S);

    REP(i, N) {
        if(d[i] == INF)
            PRINTLN("INF");
        else
            PRINTLN(d[i]);
    }
}

signed main() {


    solve();

    EXIT();
}

