void dijkstra(const Graph &G, vector<ll> &D, int s){
    D[s] = 0;
    priority_queue<P, vector<P>, greater<P>> pq;
    pq.emplace(0, s);
    while(!pq.empty()){
        auto p = pq.top();
        pq.pop();
        int v = p.second;
        if(D[v] < p.first) continue;
        else{
            for(Edge e : G[v]){
                if(D[e.to] > D[v] + e.dis){
                    D[e.to] = D[v] + e.dis;
                    pq.emplace(D[v] + e.dis, e.to);
                }
            }
        }
    }
}

