#include<cstdio>
#include<queue>
#include<vector>
#include<utility>

const int INF=99999999;

typedef std::pair<int,int> path_t;//first->node second->cost

struct nodes{
		int cost,num;
		std::vector<path_t> path;

};
bool operator>(const nodes node_a,const nodes node_b){
		return node_a.cost>node_b.cost;
	}
std::priority_queue<nodes,std::vector<nodes>,std::greater<nodes> > pq;

int v,e,r;
nodes node[100000];

void initialize(void){
	for(int lp=0;lp<100000;lp++){
		node[lp].cost=INF;
		node[lp].num=lp;
	}
}

void input(void){
	int s,t,d;
	scanf("%d%d%d",&v,&e,&r);
	for(int lp=0;lp<e;lp++){
		scanf("%d%d%d",&s,&t,&d);
		node[s].path.push_back(std::make_pair(t,d));
	}
}

void solve(void){
	node[r].cost=0;
	pq.push(node[r]);
	while(!pq.empty()){
		nodes node_now=pq.top();
		pq.pop();
		for(auto x:node_now.path){
			int nextcost=x.first+node_now.cost;
			int nextnode=x.second;
			if(nextcost<node[nextnode].cost){
				node[nextnode].cost=nextcost;
				pq.push(node[nextnode]);
			}
		}
	}
}

void output(void){
	for(auto x:node){
		if(x.cost==INF){
			printf("INF\n");
		}else{
			printf("%d\n",x.cost);
		}
	}
}

int main(void){
	initialize();
	input();
	solve();
	output();
	return 0;
}

