    public:
        priorityQueue(){
            head.l = head.r = head.p = head.s = NULL;
            for(int i=0; i<200; i++) degrees[i] = NULL;
        }
        void del(Node *p){
            if(p->p!=NULL && p->p->s==p){//p is it's father's left son
