                p->l->r = p->r;
            }
            if(p->r!=NULL) p->r->l = p->l;
        }
        void insert(Node *p1, Node *p2){
            if(head.r!=NULL) head.r->l = p2;
            p2->r = head.r;
            p1->l = &head;
            head.r = p1;
        }
        void father(Node *f, Node *s){
            s->p = f;
            s->l = NULL;
            s->r = f->s;
            if(f->s!=NULL) f->s->l = s;
            f->s = s;
            f->degree++;
        }
        void unionTree(){
            Node *p = head.r;
            while(p!=NULL){
                if(degrees[p->degree]==NULL) {
                    degrees[p->degree] = p;
                    p = p->r;
                }else{
                    Node *x = degrees[p->degree];
                    degrees[p->degree] = NULL;
                    del(x);
                    if(x->key > p->key){
                        father(p, x);
                    }else{
                        p->l->r = x;
                        x->l = p->l;
                        if(p->r!=NULL) p->r->l = x;
                        x->r = p->r;
                        father(x, p);
                        p = x;
                    }
                }
            }
            p = head.r;
            while(p!=NULL){
                degrees[p->degree] = NULL;
                p = p->r;
            }
        }
        void push(int id, int key){
            Node *t = (Node *)malloc(sizeof(Node));
            t->id = id;
            t->key = key;
            t->degree = 0;
            t->flag = false;
            t->p = t->s = NULL;
            insert(t, t);
            ids[id] = t;
        }
        bool empty(){
            return head.r==NULL;
        }
        int extractMin(){
            Node *cur = head.r;
            Node *t = cur;
            while(cur!=NULL){
                if(cur->key < t->key)
                    t = cur;
                cur = cur->r;
            }
            int ans = t->id;
            Node *p1 = t->s;
            if(t->r!=NULL) t->r->l = t->l;
            t->l->r = t->r;
            if(p1!=NULL){
                Node *p2 = p1;
                p2->p = NULL;
                while(p2->r!=NULL) {p2 = p2->r; p2->p = NULL;}
                insert(p1, p2);
            }
            unionTree();
            return ans;
        }
        void cut(Node *p){
            del(p);
            p->flag = false;
            p->p = NULL;
            insert(p, p);
        }
        void decreaseKey(int id, int key){
            Node *p = ids[id];
            p->key = key;
            if(p->p!=NULL && p->p->key > p->key){
                Node *t = p->p;
                cut(p);
                while(t->p!=NULL && t->flag){
                    Node *tmp = t->p;
                    cut(t);
                    t = tmp;
                }
                if(t->p!=NULL) t->flag = true;
            }
        }
};


