    nodes[len].w = w;
    nodes[len].nt = heads[u];
    heads[u] = len++;
}

void getGraph(int n, int m){
    len = 0;
    for(int i=0; i<n; i++) heads[i] = -1;
    //build graph
    int u,v,w;
    while(m--){
        scanf("%d%d%d",&u,&v,&w);
        insertEdge(u,v,w);
        //insertEdge(v,u,w);
    }
}
int dist[N];
void dijkstra(int n,int s){
    //initialize
    priorityQueue q;
    for(int i=0; i<n; i++) dist[i] = INF;
    dist[s] = 0;
    path[s] = s;
    q.push(s, 0);
    //work
    while(!q.empty()){
        int x = q.extractMin();
        int p = heads[x];
        while(p!=-1){
            Node y = nodes[p];
            if(dist[x]+y.w<dist[y.v]){
                if(dist[y.v]==INF) q.push(y.v, dist[x]+y.w);
                else q.decreaseKey(y.v, dist[x]+y.w);
                dist[y.v] = dist[x]+y.w;
                path[y.v] = x;
            }
            p = y.nt;
        }
    }
}

