template<typename T>
struct Maybe {
   T x;
   bool valid;
   Maybe() : valid(false) {}
   Maybe(T x_) : x(x_), valid(true) {}
   operator T() const {
      assert( valid );
      return x;
   }
};

template<typename W_>
struct Solver5 {
   using W = W_;
   struct Edge {
      Edge(Int src_, Int dest_, W cost_)
         : src(src_), dest(dest_), cost(cost_) {}
      Int src, dest;
      W cost;
   };
   Int n;
   std::vector<std::vector<Edge>> fss;
   Solver5(Int n_)
      : n(n_+1), fss(n) {}
   void addEdge(Int src, Int dest, W cost) {
      fss[src].emplace_back(src, dest, cost);
   }
   const std::vector<Edge>& forwardEdges(Int v) const {
      return fss[v];
   }
};

struct Solver4 {
   template<typename T> std::vector<Maybe<typename T::W>> solve(const T& graph, Int begin) const {
      using W = typename T::W;
      using WI = std::tuple<W, Int>;
      Int n = graph.n;
      std::vector<Maybe<W>> xs(n);
      std::priority_queue<WI, std::vector<WI>, std::greater<WI>> q;
      q.emplace(0, begin);
      xs[begin] = 0;
      while( not q.empty() ) {
         W d; Int i; std::tie(d, i) = q.top(); q.pop();
         for(auto kc : graph.forwardEdges(i)) {
            Int k = kc.dest; W c = kc.cost;
            W nd = d + c;
            Maybe<W> t = xs[k];
            if( not t.valid or nd < t ) {
               xs[k] = nd;
               q.emplace(nd, k);
            }
         }
      }
      return xs;
   }
};

struct Solver {
   Solver() { fprintf(stderr, "--------Solver begin--------\n"); }
   ~Solver() { fprintf(stderr, "--------Solver end--------\n"); }
   void solve() {
      Int v, e, r; scan(v, e, r);
      Solver5<Int> graph(v);
      for(Int i = 0; i < e; ++i) {
         Int a, b, c; scan(a, b, c);
         graph.addEdge(a, b, c);
      }
      Solver4 dijkstra;
      auto xs = dijkstra.solve(graph, r);
      for(Int i = 0; i < v; ++i) {
         Maybe<Int> w = xs[i];
         if( not w.valid ) {
            puts("INF");
         }
         else {
            std::cout << w << std::endl;
         }
      }
   }
};

int main() {
   loop std::unique_ptr<Solver>(new Solver())->solve();
}

