lli dist[100005];//距離を持つ

int main(void){
	scanf("%d%d%d",&n,&m,&st);
	rep(i,m){
		int a,b;
		lli c;
		scanf("%d%d%lld",&a,&b,&c);
		vs[a].push_back( mp(c,b) );
	}

	memset(dist,-1,sizeof(dist));//最初は、無限大で初期化

	priority_queue<mp,vector<mp>,greater<mp> > que;

	que.push(mp(0,st));//stには0で行ける

	while(!que.empty()){//queが空になるまでやる

		mp pa = que.top();
		que.pop();
		//queの先頭要素(一番軽いの)を取り出す。

		int no = pa.second;//今の頂点
		lli co = pa.first;//今の距離

		if(dist[no]!=-1)continue; //もし、すでに確定していたら、飛ばす

		dist[no] = co;//確定させる

		rep(i,vs[no].size()){//今の地点から出ているすべての辺の先について、キューに突っ込んでいく
			int to = vs[no][i].second;//次の頂点
			lli tc = co + vs[no][i].first;//次の距離

			if(dist[to]!=-1)continue; //もし、すでに確定していたら、飛ばす
			que.push( mp(tc,to) ); //queに追加
		}
	}
	//これで、全ての頂点について、stからの距離が求まった

	rep(i,n){
		if(dist[i]==-1)printf("INF\n");//もし-1なら、その頂点には到達不可のう
		else printf("%lld\n",dist[i]);//そうでなければ、距離を出力
	}

	return 0;
}

/*
ちなみに、上の
「もし-1なら、その頂点には到達不可のう」
のコメントの、
「のう」の字を「能」にしたところ、
まともに動かなくなったことを、ここに付記しておきます。
*/

#include <iostream>  

using namespace std;  

#define MAX 500000

#define LEN 100 

int map[LEN][LEN]; 

int dist[LEN];            

int mark[LEN];  



void init(){  

       int i,j;  

       for(i=0;i<LEN;i++){  

              for(j=0;j<LEN;j++){  

                     map[i][j]=MAX;  

              }  

       }  



}  



void myDijstra(int n,int start){  

       int i,j,min,k;  

       for(i=0;i<n;i++){  

              mark[i]=0;

              dist[i]=map[start][i]; 



       }  

       mark[start]=1; 

       dist[start]=0;  

       for(i=0;i<n;i++){  

              min=MAX;  

              for(j=0;j<n;j++){  

                     if(!mark[j] && dist[j]<min){    

                            min=dist[j];  

                            k=j;

                     }  

              }  

              if(min==MAX)  

                     break;  

              mark[k]=1;


              for(j=0;j<n;j++){  

                     if(!mark[j] && dist[j]>dist[k]+map[k][j]){  

                            dist[j]=dist[k]+map[k][j];  

                     }  

              }  

       }  

}  



int main(){  

       int i,j,n,line,source;  

       int a,b,d;  

       cin>>n>>line>>source;   

       init();  

       for(i=0;i<line;i++){  

              cin>>a>>b>>d; 

              if(map[a][b]>d){  

                     map[a][b]=d;  

              }  

       }  

       myDijstra(n,source);


       for (i=0;i<n;i++) {
		if(dist[i] == MAX){
			cout<<"INF"<<endl;
		}else{
			cout<<dist[i]<<endl;
		}

} 

       return 0;  

}

