	Dijkstra(vector<vector<P>> data, int Start) {
		n = data.size();
		start = Start;
		result.resize(n);
		nodes.resize(n);
		Loop(i, n) {
			nodes[i] = { false, {}, {}, i, -1, INFLL };
			Loop(j, data[i].size()) {
				nodes[i].to.push_back(data[i][j].first);
				nodes[i].cost.push_back(data[i][j].second);
			}
		}
