  int s;

  scanf("%d %d %d", &v, &e0, &s);

  std::vector<std::vector<Edge> > vec(v);

  DirectedGraph g = DirectedGraph(v);

  int from, to, cost;

  for (int i = 0; i <  e0; i++) {
    scanf("%d %d %d", &from, &to, &cost);
    g.push(from, to, cost);
  }

  g.dijkstra(s);
  std::vector<long long> dist = g.get_dist();
  for (int a: dist) {
    if (a == g.inf) printf("INF\n");
    else printf("%d\n", a);
  }
}

