  int n, m, src;
  cin >> n >> m >> src;
  Graph g(n, m);
  int s, t, w;
  for (int i = 0; i < m; i++) {
    cin >> s >> t >> w;
    g.addEdge(s, t, w);
  }
  g.dijkstra(src);
  return 0;
}

