vector<int> dijkstra(vector< vector< pair<int,int> > > &G, int s){
  vector<int> ret(G.size(),INF);
  priority_queue< pair<int,int> > wait;
  wait.emplace(0,s);
  while(!wait.empty()){
    int c = -wait.top().first, v = wait.top().second;
