int V;//頂点の数
int E;//辺の数

struct edge {
	int from, to, cost;
};
edge es[MAX_E];
int d[MAX_V];


bool find_negative_loop(int s) {
	d[s] = 0;

	int count = 0;
	while (true) {
		bool update = false;
		count++;

		for (int i = 0; i < E; i++) {
			if (count == V) {
				return true;
			}
			if (d[es[i].from] != INF && d[es[i].to] > d[es[i].from] + es[i].cost) {
				d[es[i].to] = d[es[i].from] + es[i].cost;
				update = true;
			}
		}
		if (update == false) {
			return false;
		}
	}
}

