const long long int INF = 1000000000000000;
const long long int MAX_V = 1000000;

int V;
vector <pair<long long int,long long int> >  G[MAX_V];
int d[MAX_V];

void dijkstra(int s) {
	typedef pair<long long int,long long int> pii;
	priority_queue<pii, vector<pii>, greater<pii> > que;
	for (int i = 0; i < V; i++) {
		d[i] = INF;

	}
	d[s] = 0;
	que.push(pii(0, s));
	while (!que.empty()) {
		pii p = que.top();
		que.pop();
		long long int v = p.second;
		if (d[v] < p.first)continue;
		for (int i = 0; i < G[v].size(); i++) {
			pair<int, int> e = G[v][i];

			if (d[e.first] > d[v] + e.second) {
				d[e.first] = d[v] + e.second;
				que.push(pii(d[e.first], e.first));

			}
		}
	}
}
