int main() {

	int V,E,r;
	int **matrix;

	cin>>V>>E>>r;
	matrix = new int*[V];

	for(int i=0;i<V;i++){
		matrix[i] = new int[V];
		for(int j=0;j<V;++j){
			matrix[i][j] = -1;
		}
	}

	for(int i=0;i<E;i++){
		int s,t,d;
		cin>>s>>t>>d;

		matrix[s][t] = d;
	}

	for(int i=0;i<V;++i){
		int *mark = new int[V];
		int min = -1;

		if(i==r){cout<<0<<endl;continue;}

		std::function<void(int,int)> func = [&](int cur, int sum){
			mark[cur] = 1;

			if(matrix[cur][i] != -1){
				if(min == -1){
					min = sum + matrix[cur][i];
				}
				else if(sum + matrix[cur][i] <= min){
					min = sum + matrix[cur][i];
				}
			}
			for(int j=0;j<V;++j){
				if(j!=i){
					if(matrix[cur][j] != -1){
						if(mark[j]==0){
							func(j,sum+matrix[cur][j]);
						}

					}
