bool find_negative_loop(int s) {
	d[s] = 0;
	int count = 0;
	while (true) {
		bool update = false;
		count++;

		for (int i = 0; i < E; i++) {
			if (d[es[i].from] != INF && d[es[i].from] + es[i].cost) {
				if (count == V) {
					return true;//ループが回った回数がV回以上なので負閉路が存在する
				}
				d[es[i].to] = d[es[i].from] + es[i].cost;
				update = true;
			}
		}
		if (update == false) {
			break;
		}
	}
	return false;
}

