struct node {
	int id;
	bool done;
	vi ed, dist;
	int from;
	ll d;
	bool operator<(const node & another) const {
		return !(d != another.d ? d < another.d : id < another.id);
	}
};


void dijkstra(vector<node> nodes, int n, int start) {
	priority_queue<node> pq;
	nodes[start].d = 0;
	pq.push(nodes[start]);
	while (pq.size()) {
		node focus = pq.top(); pq.pop();
		if (nodes[focus.id].done) continue;
		Loop(i, focus.ed.size()) {
			if (focus.d + focus.dist[i] < nodes[focus.ed[i]].d) {
				nodes[focus.ed[i]].d = focus.d + focus.dist[i];
			}
			pq.push(nodes[focus.ed[i]]);
			nodes[focus.id].done = true;
		}
	}
	Loop(i, n) {
		if (nodes[i].d == INFLL) cout << "INF" << endl;
		else cout << nodes[i].d << endl;
	}
	return;
}

