	}

	Dijkstra ds(G, V);

	ds.calc_shortest_path(s);
	for (int i = 0; i < V; i++) {
		ll d = ds.get_shortest_path(i);
		cout << (i ? " " : "") << (d >= (1LL << 55) ? "INF" : to_string(d));
	}
	cout << endl;

	//end = clock();
	//printf("%d msec.\n", end - start);

	return 0;
}

