	Edge(int src = 0, int dst = 0) : src(src), dst(dst) {}
};

template <typename Cost>
struct WeightedEdge : Edge {
	Cost cost;
	WeightedEdge(int src, int dst, Cost cost) : Edge(src, dst), cost(cost) {}
	bool operator < (const WeightedEdge<Cost> &rhs) const {
		return cost > rhs.cost;
	}
};

template <class Edge>
class Graph {
public:
	Graph(){}
	Graph(int n) : graph_(n) {}
	int size() const {
		return graph_.size();
	}
	void addEdge(const Edge &e){
		graph_[e.src].push_back(e);
	}
	std::vector<Edge>& operator [] (int i){
		return graph_[i];
	}
	const std::vector<Edge>& operator [] (int i) const {
		return graph_[i];
	}
private:
	std::vector<std::vector<Edge> > graph_;
};


template <typename Cost, Cost INF = 1e9>
class Dijkstra : Graph<WeightedEdge<Cost> >{
public:
	typedef WeightedEdge<Cost> EdgeType;
	typedef Graph<EdgeType> GraphType;
	using GraphType::size;
	using GraphType::addEdge;

	Dijkstra(){}
	Dijkstra(int n) : Graph<EdgeType>(n) {}
	void addEdge(int src, int dst, Cost cost){
		addEdge(EdgeType(src, dst, cost));
	}
	void solve(int s){
		int n = size();
		dist_.assign(size(), INF);
		prev_.assign(size(), -1);
		std::priority_queue<EdgeType> pq;
		dist_[s] = 0;
		pq.push(EdgeType(-1, s, 0));
		while (!pq.empty()){
			EdgeType c = pq.top(); pq.pop();
			if (dist_[c.dst] < c.cost) continue;
			prev_[c.dst] = c.src;
			for (int i = 0; i < (*this)[c.dst].size(); i++){
				EdgeType &e = (*this)[c.dst][i];
				if (dist_[e.dst] > c.cost + e.cost){
					dist_[e.dst] = c.cost + e.cost;
					pq.push(EdgeType(e.src, e.dst, c.cost + e.cost));
				}
			}
		}
	}
	Cost getDist(int t){
		return dist_[t];
	}
	std::vector<int> getPath(int t){
		std::vector<int> path;
		for (int v = t; v != -1; v = prev_[v]){
			path.push_back(v);
		}
		std::reverse(path.begin(), path.end());
		return path;
	}
private:
	std::vector<Cost> dist_;
	std::vector<int> prev_;
};


