	while (!pq.empty()) {
		pair<ll, int> p = pq.top();
		pq.pop();
		if (dist[p.second] == -1) {
			dist[p.second] = p.first;
			for (int i = 0;i < children[p.second].size();i++) {
				pq.push(make_pair(p.first + children[p.second][i].first, children[p.second][i].second));
			}
		}
	}
	for (int i = 0;i < v;i++) {
		if (dist[i] == -1) {
			cout << "INF\n";
		}
		else {
			cout << dist[i] << endl;
		}
	}
}

