}

bool Vertex::is_alive() const {
    return !_is_removed;
}

void Vertex::add_edge(const spEdge &e) {
    e->next = head;
    head = e;
    if (e->next) {
        e->prev = head;
    }
    head->prev.reset();
    ++_deg;
}

int Vertex::deg() const {
    return _deg;
}

int Vertex::deg() {
    return _deg;
}

