Edge::Edge() : Edge(-1, -1, -1, -1) {
}

Edge::Edge(int s, int t, int c, int id)
        : s(s), t(t), c(c), id(id), reverse(), next() {
}

void Edge::remove() {
    if (prev.lock()) {
        prev.lock()->next = next;
    }
    if (next) {
        next->prev.lock()->prev = prev;
    }
    reverse.lock()->remove();
}


