void dijkstra(const Graph &g, int start) {
    using ll = long long;
    const ll INF = static_cast<ll>(1e18);
    int n = g.size();
    priority_queue<pair<ll, int>> q;
    vector<ll> dist(n, INF);
    dist[start] = 0;
    q.emplace(0, start);
    while (q.size() > 0) {
        ll d;
        int u;
        tie(d, u) = q.top();
        d = -d;
        q.pop();
        if (dist[u] < d) continue;
        for (spEdge e = g[u]->head; e; e = e->next) {
            if (dist[e->t] > dist[u] + e->c) {
                dist[e->t] = dist[u] + e->c;
                q.emplace(-dist[e->t], e->t);
            }
        }
    }
