	for (int i = 0; i < M; i++) {
		long long S, T, C;
		cin >> S >> T >> C;
		V[S].push_back({ T, C });
	}
	vector<long long> ANS = Dijkstra<long long>(V, R);
	for (int i = 0; i < N; i++) {
		if (ANS[i] == LLONG_MAX) cout << "INF" << endl;
		else cout << ANS[i] << endl;
	}
}

