using namespace std;

template<typename Edge> class Graph {
protected:
  vector<vector<Edge>> edges;

public:
  Graph(int n = 0) : edges(n) {}

  void addEdge(const Edge& edge) {
    if (int(edges.size()) <= max(edge.from, edge.to)) edges.resize(max(edge.from, edge.to) + 1);
    edges[edge.from].emplace_back(edge);
  }
};

template<typename Edge> class ShortestPath : public Graph<Edge> {
private:
  typedef __typeof(Edge::cost) Cost;

  struct State {
    int pos;
    Cost cost;
    bool operator<(const State& state) const {return cost > state.cost;}
  };

public:
  const Cost INF;

  vector<Cost> dist;

  ShortestPath(const Graph<Edge>& graph) : Graph<Edge>(graph), INF(numeric_limits<Cost>::max()) {}

  void run (int from) {
    priority_queue<State> que;
    que.push((State){from, 0});
    dist.resize(this->edges.size(), INF);

    while (!que.empty()) {
      State now = que.top();
      que.pop();
      if (dist[now.pos] <= now.cost) continue;
      dist[now.pos] = now.cost;
      for (const Edge& edge : this->edges[now.pos]) {
        if (dist[edge.to] < now.cost + edge.cost) continue;
        que.push((State){edge.to, now.cost + edge.cost});
      }
    }
  }
};

struct Edge {
  int from, to, cost;
};

int main() {
  int v, e, r;
  cin >> v >> e >> r;
  Graph<Edge> graph(v);
  for (int i = 0; i < e; ++i) {
    int s, t, d;
    cin >> s >> t >> d;
    graph.addEdge((Edge){s, t, d});
  }
  ShortestPath<Edge> shortestPath = graph;
  shortestPath.run(r);
  for (int c : shortestPath.dist) {
    if (c != shortestPath.INF) cout << c << endl;
    else cout << "INF" << endl;
  }
}

