Graph::Graph() : Graph(0) {

}

Graph::Graph(int n) : _size(0), next_vertex_id(0), next_edge_id(0) {
    for (int i = 0; i < n; ++i) {
        add_vertex();
    }
}

int Graph::add_vertex() {
    int id = next_vertex_id++;
    vertices.emplace_back(new Vertex(id));
    return id;
}

std::pair<spEdge, spEdge> Graph::add_biedge(int s, int t, int c) {
    spVertex vs = vertices[s];
    spVertex vt = vertices[t];
    assert(vs->is_alive());
    assert(vt->is_alive());

    spEdge st = add_uniedge(s, t, c, next_edge_id);
    spEdge ts = add_uniedge(t, s, c, next_edge_id);
    st->reverse = ts;
    ts->reverse = st;

    return {st, ts};
}

spEdge Graph::add_uniedge(int s, int t, int c, int id) {
    spEdge st = add_uniedge(s, t, c);
    st->id = id;
    return st;
}

spEdge Graph::add_uniedge(int s, int t, int c) {
    spVertex vs = vertices[s];
    spVertex vt = vertices[t];
    assert(vs->is_alive());
    assert(vs->is_alive());

    spEdge st = make_shared<Edge>(s, t, c, next_edge_id++);
    vs->add_edge(st);

    return st;
}

void Graph::simplify() {
    vector<int> stack;
    for (auto &u : vertices) {
        if (u->is_alive()) {
            if (u->deg() == 1) {
                stack.emplace_back(u->id);
            } else if (u->deg() == 2) {
                stack.emplace_back(u->id);
            }
        }
    }

    while (stack.size() > 0) {
        int u = stack.back();
        stack.pop_back();
        if (vertices[u]->is_removed()) {
            continue;
        }

    }
}

int Graph::size() const {
    // TODO: alert that this takes O(n)
    int res = 0;
    for (const auto &u : vertices) {
        if (u->is_alive()) ++res;
    }
    return res;
}

spVertex Graph::operator[](size_t vid) const {
    return vertices[vid];
}

spVertex Graph::operator[](size_t vid) {
    return vertices[vid];
}

int Graph::size() {
    return const_cast<Graph*>(this)->size();
}

void Graph::show() const {
    for (const spVertex &v : vertices) {
        if (v->is_alive()) {
            for (spEdge e = v->head; e; e = e->next) {
                cout << e->s << "->" << e->t << endl;
            }
        }
    }
}

Vertex::Vertex(int id) : id(id), head(), _is_removed(false) {
}

bool Vertex::is_alive() const {
    return !_is_removed;
}

void Vertex::add_edge(const spEdge &e) {
    e->next = head;
    head = e;
    if (e->next) {
        e->prev = head;
    }
    head->prev.reset();
    ++_deg;
}

int Vertex::deg() const {
    return _deg;
}

int Vertex::deg() {
    return _deg;
}

bool Vertex::is_removed() const {
    return !is_alive();
}

void Vertex::remove() {
    while (head) {
        head->remove();
    }
}

Edge::Edge() : Edge(-1, -1, -1, -1) {
}

Edge::Edge(int s, int t, int c, int id)
        : s(s), t(t), c(c), id(id), reverse(), next() {
}

void Edge::remove() {
    if (prev.lock()) {
        prev.lock()->next = next;
    }
    if (next) {
        next->prev.lock()->prev = prev;
    }
    reverse.lock()->remove();
}


