	edge Extract_min(){
		edge ret=heap[0];
		swap(position[heap[0].node],position[heap.back().node]);
		// cout<<"before\n";
		// cout<<heap[0].node<<" "<<heap.back().node<<endl;
		swap(heap[0],heap.back());
		// cout<<"after\n";
		// cout<<heap[0].node<<" "<<heap.back().node<<endl;
		heap.pop_back();
		int now=0;
		while(1){
			if(now*2>=heap.size()){
				break;
			}
			int tmp;
			if(now*2+1<heap.size()){
				if(heap[now*2].cost<heap[now*2+1].cost){
					tmp=now*2;
				}
				else{
					tmp=now*2+1;
				}
			}
			else{
				tmp=now*2;
			}
			if(heap[tmp].cost<heap[now].cost){
				swap(position[heap[tmp].node],position[heap[now].node]);
				swap(heap[tmp],heap[now]);
				now=tmp;
			}
			else{
				break;
			}
		}
		return ret;
	}
