		if(heap[now].cost<k) return;
		else heap[now].cost=k;
		while(1){
			if(now==0){
				break;
			}
			if(heap[now>>1].cost>heap[now].cost){
				swap(position[heap[now>>1].node],position[heap[now].node]);
				swap(heap[now>>1],heap[now]);
				now>>=1;
			}
			else{
				break;
			}
		}
	}
	void insert(int x){
		return Decrease_min(x,0);
	}
