{
	Heap<P> que;
	d[s] = 0;
	que.push(P(0,s));
	while(que.root){
		P p = que.top();
		que.pop();
		int v = p.second;
		if(d[v] < p.first) continue;
		for(auto w : G[v]){
			if(d[w.to] > d[v] + w.cost){
				d[w.to] = d[v] + w.cost;
				que.push(P(d[w.to],w.to));
			}
		}
	}
}

