bool find_negative_loop(int s) {
	d[s] = 0;

	int count = 0;
	while (true) {
		bool update = false;
		count++;

		for (int i = 0; i < E; i++) {
			if (count == V) {
				return true;
			}
			if (d[es[i].from] != INF && d[es[i].to] > d[es[i].from] + es[i].cost) {
				d[es[i].to] = d[es[i].from] + es[i].cost;
				update = true;
			}
		}
		if (update == false) {
			return false;
		}
	}
}

