			{
				dis[t.first] = dis[top] + t.second;
				if (!vis[t.first])vis.set(t.first), que.push(t.first);
			}
	}

	for (auto i : dis)
	{
		if (i < inf)cout << i << endl;
		else cout << "INF" << endl;
	}

