struct Edge
{
	int vx;
	long long w;

	bool operator < (const Edge& e) {
		return w < e.w;
	}
};

struct NodeInfo {
	int vx;
	long long *d;

	bool operator < (const NodeInfo& node) {
		return (*d) < *(node.d);
	}
};

std::vector<Edge> graph[MAXN];
long long dist[MAXN];
int pre_vx[MAXN];
int visit[MAXN];
