using namespace std;

#define MAX_VERTEX 100000
#define INF 1000000

int vertex_num, edge_num, r;
int cost[MAX_VERTEX][MAX_VERTEX];
int d[MAX_VERTEX];
bool used[MAX_VERTEX];

void Dijkstra() {
  d[r] = 0;

  while(true) {
    int vertex = -1;
    for(int u = 0; u < vertex_num; u++) {
      if(!used[u] && (vertex == -1 || d[u] < d[vertex])) {
        vertex = u;
      }
    }

    if (vertex == -1) break;

    used[vertex] = true;

    for(int u = 0; u < vertex_num; u++) {
      d[u] = min(d[u], d[vertex] + cost[vertex][u]);
    }
  }
}

int main() {
  cin >> vertex_num >> edge_num >> r;

  for(int i = 0; i < vertex_num; i++) {
    d[i] = INF;
    used[i] = false;

    for(int j = 0; j < vertex_num; j++) {
      cost[i][j] = INF;
    }
  }

  for (int i = 0; i < edge_num; i++) {
    int start, terminus, c;
    cin >> start >> terminus >> c;
    cost[start][terminus] = c;
  }

  Dijkstra();

  for(int i = 0; i < vertex_num; i++) {
    if (d[i] == INF) cout << "INF" << endl;
    else cout << d[i] << endl;
  }

  return 0;
}

