using namespace std;

struct Node;

struct Edge {
  int node;
  int cost;
};

struct Node {
  bool done = false;
  int cost = -1;
  std::vector<Edge> edges;
};

int main() {
  int nv, ne, r;
  cin >> nv >> ne >> r;
  vector<Node> V(nv);
  for (int i = 0; i < ne; ++i) {
    int begin, end, cost;
    cin >> begin >> end >> cost;
    Edge edge;
    edge.cost = cost;
    edge.node = end;
    V[begin].edges.push_back(edge);
  }
  V[r].cost = 0;

  while (true) {
    // find closest node
    int closest = -1;
    for (int i = 0; i < nv; ++i) {
      if (V[i].done) {
        continue;
      }
      if (closest < 0) {
        closest = i;
        continue;
      }
      if (V[i].cost >= 0 && V[i].cost < V[closest].cost) {
        closest = i;
      }
    }
    if (closest < 0) {
      break; // done
    }
    V[closest].done = true;

    for (auto& edge : V[closest].edges) {
      // set distances
      int newCost = V[closest].cost + edge.cost;
      if (V[edge.node].cost == -1 || newCost < V[edge.node].cost) {
        V[edge.node].cost = newCost;
      }
    }
  }

  for (auto& v : V) {
    if (v.cost == -1) {
      cout << "INF" << endl;
    } else {
      cout << v.cost << endl;
    }
  }
}

