void dijkstra(int s) {
    priority_queue< P, vector<P>, greater<P> > q;
    d[s] = 0;
    q.push(P(0, s));
    while (!q.empty()) {
        P p = q.top(); q.pop();
        int u = p.second;
        if (d[u] < p.first) continue; //すでに最短経路が更新されていたらcontinue
        REP(i, (int)es[u].size()) {
            int v = es[u][i].to;
            if (d[v] > d[u]+es[u][i].cost) {
                d[v] = d[u]+es[u][i].cost;
                q.push(P(d[v], v));
            }
        }
    }
}

void solve(int r, int N) {
    dijkstra(r);
    REP(i, N) {
        if (d[i] != INF) {
            cout << d[i] << endl;
        }
        else cout << "INF" << endl;
    }
}

