int main() {

    int V, E, r;
    cin >> V >> E >> r;

    vector<edge> G[V];
    ULL cost[V];

    for (int i = 0; i < E; i++) {
        int s, t, d;
        cin >> s >> t >> d;
        G[s].push_back(edge{t, (ULL) d});
    }

    fill(cost, cost + V, INF);
