        if (p.first > cost[p.second]) continue;

        for (edge e : G[p.second]) {
            if (p.first + e.cost < cost[e.to]) {
                cost[e.to] = p.first + e.cost;
                pq.push(P(cost[e.to], e.to));
            }
        }
    }

    for (int i = 0; i < V; i++) {
        if (cost[i] != INF) {
            cout << cost[i] << endl;
