typedef long long ll;
typedef vector<int> vint;
typedef vector<ll> vll;
typedef pair<int, int> pint;
typedef pair<ll, ll> pll;
#define range(i, a, b) for (int i = a; i < b; ++i)
#define rep(i, n) range(i, 0, n)
const ll INF = 1e10;
#define pb push_back

struct edge {
    int cost, to;
};

int main() {
    int n, m, r;
    cin >> n >> m >> r;
    vector<vector<edge>> G(n);
    vll d(n, INF);
    rep(i, m) {
        int s;
        edge e;
        cin >> s >> e.to >> e.cost;
        G[s].pb(e);
    }

    priority_queue<pint, vector<pint>, greater<pint>> Q;  //距離,点
    d[r] = 0;
    Q.push(pint(0, r));

    while (!Q.empty()) {
        pint p = Q.top();
        Q.pop();
        int v = p.second;
        if (d[v] < p.first)
            continue;
        rep(i, G[v].size()) {
            edge e = G[v][i];
            if (d[e.to] > d[v] + e.cost) {
                d[e.to] = d[v] + e.cost;
                Q.push(pint(d[e.to], e.to));
            }
        }
    }

    rep(i, n) {
        if (d[i] == INF) {
            cout << "INF" << endl;
        } else {
            cout << d[i] << endl;
        }
    }
}

#include<iostream>
#include<vector>
using namespace std;



int main(){
	typedef pair<int, int>vd;	//(頂点,距離)
	const int max = 1000000;
	int V,E,r;
	cin >> V >> E >> r;

	vector<int> dist(V,max);	// r からの距離

	vector< vector<vd>> adj(V);	// 隣接する点のリスト(頂点ごと)

	for (int e = 0; e < E; e++){
		int s, t, d;
		cin >> s >> t >> d;
		adj[s].push_back(vd(t, d));
	}//辺情報読み込み


	vector<bool> Defined(V,false);
	vector<bool> Reach(V, false);

	dist[r] = 0;
	Reach[r] = true;
	Defined[r] = true;

	for (int i = 0; i < adj[r].size(); ++i){
		dist[adj[r][i].first] = adj[r][i].second;
		Reach[adj[r][i].first] = true;
	}

	int num = 0;
	while (num >= 0){
		num = -1;
		int min = max;
		for (int i = 0; i < V; ++i){
			if (!Defined[i] && Reach[i] && dist[i] < min){
				min = dist[i];
				num = i;
			}
		}
		if (num >= 0){
			for (int i = 0; i < adj[num].size(); ++i){
				if (!Defined[adj[num][i].first] && dist[num] + adj[num][i].second < dist[adj[num][i].first]){
					dist[adj[num][i].first] = dist[num] + adj[num][i].second;
					Reach[adj[num][i].first] = true;
				}
			}
			Defined[num] = true;
		}

	}

	for (int i = 0; i < V; i++){
		if (Reach[i]){
			cout << dist[i] << endl;
		}
		else{
			cout << "INF" << endl;
		}
	}
	return 0;
}

