template<class T>
struct Dijkstra {
  struct Edge {
    int to;
    T cost;
    Edge(int to, T cost) : to(to), cost(cost) {};
    bool operator<(const Edge& o) const { return cost > o.cost; }
  };
  vector<vector<Edge>> G;
  Dijkstra(int n) : G(n) {}
  void add_edge(int u, int v, T c) { G[u].emplace_back(v,c); }
  vector<T> build(int s) {
    vector<T> dist(G.size(), numeric_limits<T>::max());
    dist[s] = 0;
    priority_queue<Edge> pq;
    pq.emplace(s, dist[s]);
    while (!pq.empty()) {
      Edge p = pq.top(); pq.pop();
      int v = p.to;
      if (dist[v] < p.cost) continue;
      for (const auto& e : G[v]) {
        if (dist[e.to] > dist[v] + e.cost) {
          dist[e.to] = dist[v] + e.cost;
          pq.emplace(e.to, dist[e.to]);
        }
      }
    }
    return dist;
  }
};

int main() {
  int n, m, r;
  cin >> n >> m >> r;
  Dijkstra<ll> G(n);
  rep(_,0,m) {
    int s, t, d;
    cin >> s >> t >> d;
    G.add_edge(s,t,d);
  }
  vl d = G.build(r);
  rep(i,0,n) {
    if (d[i] == numeric_limits<ll>::max()) cout << "INF" << endl;
    else cout << d[i] << endl;
  }
}

