	NODOS = N;

	limpia();
	for( int i = 0; i < M; i++ ){
		cin >> x >> y >> c;
		AgregarArista( x, y, c );
	}
	Dijkstra( S );

	for( int i = 0; i < NODOS; i++ ){
		if( dist[i] == INF ){
			cout << "INF\n";
		}
		else
			cout << dist[i] << '\n';
	}

	return 0;
}

