    cin >> s >> t >> d;

    G.add_edge(s, t, d);
  }

  G.build(r);

  for (int i = 0; i < V; ++i) {
    if (G[i] == G.inf) {
      cout << "INF" << endl;
    } else {
      cout << G[i] << endl;
    }
  }
}

