  for(int i = 0; i < E; i++){
    int s, t, d;
    cin >> s >> t >> d;
    es[i] = edge(s, t, d);
  }
  bellman_ford(r);
  for(int i = 0; i < V; i++){
    if(dist[i] == INF) cout << "INF" << endl;
    else cout << dist[i] << endl;
