class AdjList {
  vector<vector<int>> g;

public:
  AdjList(const int &n, const vector<int> &src) : g(n) {
    int m = src.size();
    rep(i, m) g[src[i]].emplace_back(i);
  }

  int size() const { return g.size(); }
  const vector<int> &operator[](const int &i) const { return g[i]; }
  auto begin() { return g.begin(); }
  auto begin() const { return g.begin(); }
  auto end() { return g.end(); }
  auto end() const { return g.end(); }
};

template<typename Weight> class Dijkstra {
  using Edges = tuple<vector<int>, vector<int>, vector<int>>; // src, dst, weight
  int s;
  vector<int> src, dst;
  vector<Weight> weight;

  AdjList g;
  vector<Weight> dist;
  vector<int> prev;

public:
  Dijkstra(const int &n, const Edges &edges, const int &s, const Weight &inf = numeric_limits<Weight>::max() / 8) //
      : src(get<0>(edges)), dst(get<1>(edges)), weight(get<2>(edges)), g(n, src), s(s), dist(n, inf), prev(n) {
    using state = pair<Weight, int>;
    priority_queue<state, vector<state>, greater<state>> q;
    dist[s] = 0;
    q.emplace(0, s);
    while (q.size()) {
      Weight d;
      int v;
      tie(d, v) = q.top();
      q.pop();
      if (dist[v] < d) continue;
      for (auto &e : g[v]) {
        if (cmin(dist[dst[e]], dist[v] + weight[e])) {
          prev[dst[e]] = v;
          q.emplace(dist[dst[e]], dst[e]);
        }
      }
    }
  }

  Weight shortestDist(const int &v) { return dist[v]; }
};

main {
  int n, m, s;
  cin >> n >> m >> s;
  vector<int> a(m), b(m), c(m);
  rep(i, m) cin >> a[i] >> b[i] >> c[i];

  Dijkstra<int> dij(n, make_tuple(a, b, c), s, INF);
  rep(i, n) {
    int d = dij.shortestDist(i);
    if (d == INF) {
      cout << "INF" << endl;
    } else {
      cout << d << endl;
    }
  }
}

#include <iostream>
#include <vector>
using namespace std;
const int INF = 10001;

int main()
{
	int V = 0; //num of vertices
	int E = 0; //num of edges
	int r = 0; //source node
	//input V, E, r
	cin >> V >> E >> r;

	int **G = new int*[V];//2 dim array to memorize distances
	for (int i = 0; i < V; i++){
		G[i] = new int[V];
	}
	//initiate G
	for (int i = 0; i < V; i++){
		for (int j = 0; j < V; j++){
			G[i][j] = INF;
		}
	}
	for (int i = 0; i < V; i++){
		G[i][i] = 0;
	}

	//input G
	int src = 0; 
	int tar = 0;
	int dis = 0;
	for (int i = 0; i < E; i++){
		cin >> src >> tar >> dis;
		G[src][tar] = dis;
	}

	//start dijkstra
	vector<int> *U = new vector<int>();
	U->push_back(r);
	bool *valid = new bool[V];
	for (int i = 0; i < V; i++){
		valid[i] = true;
	}
	valid[r] = false;

	int min = INF;//record the min-distance
	int ver = V;//record the min-distance-vertice
	while (U->size() < V){
		min = INF;
		ver = V;
		for (int i = 0; i < V; i++){
			if (G[r][i] < min && valid[i]){
				min = G[r][i];
				ver = i;
			}
		}
		if (V == ver){
			break;
		}

		U->push_back(ver);
		valid[ver] = false;
		for (int i = 0; i < V; i++){
			if (i != r && G[r][ver] + G[ver][i] < G[r][i]){
				G[r][i] = G[r][ver] + G[ver][i];
			}
		}
	}

	//output
	for (int i = 0; i < V; i++){
		if (INF == G[r][i]){
			cout << "INF" << endl;
		}
		else{
			cout << G[r][i] << endl;
		}
	}

	//delete
	for (int i = 0; i < V; i++){
		delete[] G[i];
	}
	delete[] G;
	delete[] valid;

	return 0;
}

