			}
		}
		if (v == -1) break;
		visited[v] = true;
		for (int i = 0; i < int (G[v].size()); i ++) {
			P e = G[v][i];
			int e_next = e.first;
			int e_cost = e.second;
			if (d[v] != -1) d[e_next] = min(d[e_next], d[v] + e_cost);
		}
	}
}
int main() {
	int V, E, r;
	scanf("%d %d %d", &V, &E, &r);
	G.resize(V);
	for (int i = 0; i < E; i ++) {
		int a, b, c;
		scanf("%d %d %d", &a, &b, &c);
		G[a].push_back(make_pair(b, c));
	}
