struct my_priority_queue{
private:
	vector<int> position;
	vector<edge> heap;
public:
	my_priority_queue(int n){
		position.clear();
		for(int i=0;i<n;i++){
			position.push_back(i);
			heap.push_back(edge(i,INF));
		}
	}
	edge Extract_min(){
		edge ret=heap[0];
		swap(position[heap[0].node],position[heap.back().node]);
		// cout<<"before\n";
		// cout<<heap[0].node<<" "<<heap.back().node<<endl;
		swap(heap[0],heap.back());
		// cout<<"after\n";
		// cout<<heap[0].node<<" "<<heap.back().node<<endl;
		heap.pop_back();
		int now=0;
		while(1){
			if(now*2+1<heap.size()){	
				int tmp;
				if(now*2+2<heap.size()){
					if(heap[now*2+1].cost<heap[now*2+2].cost){
						tmp=now*2+1;
					}
					else{
						tmp=now*2+2;
					}
				}
				else{
					tmp=now*2+1;
				}
				if(heap[tmp].cost<heap[now].cost){
					swap(position[heap[tmp].node],position[heap[now].node]);
					swap(heap[tmp],heap[now]);
					now=tmp;
				}
				else{
					break;
				}
			}
			else{
				break;
			}
		}
		return ret;
	}
	int Minimum(){
		return heap[0].cost;
	}
	void Decrease_min(int x,int k){
		int now=position[x];
		if(heap[now].cost<k) return;
		else heap[now].cost=k;
		while(1){
			if(now==0){
				break;
			}
			if(heap[(now-1)>>1].cost>heap[now].cost){
				swap(position[heap[(now-1)>>1].node],position[heap[now].node]);
				swap(heap[(now-1)>>1],heap[now]);
				now=(now-1)>>1;
			}
			else{
				break;
			}
		}
	}
	void insert(int x){
		return Decrease_min(x,0);
	}
	// void show(){
		// cout<<"position\n";
		// for(int i=0;i<position.size();i++){
			// cout<<position[i]<<" ";
		// }
		// cout<<endl;
		// cout<<"node\n";
		// for(int i=0;i<heap.size();i++){
			// cout<<heap[i].node<<" ";
		// }
		// cout<<endl;
		// cout<<"cost\n";
		// for(int i=0;i<heap.size();i++){
			// cout<<heap[i].cost<<" ";
		// }
		// cout<<endl;
	// }
};


