struct DistanceCompare {
  vector<int> &d;
  bool operator()(int x, int y) { return d[x] > d[y]; }
  DistanceCompare(vector<int> &d) : d{d} {};
};

int main() {
  int n, m, source;
  cin >> n >> m >> source;
  vector<map<int, int>> adj(100000);

  vector<int> d(100000, 1000000001);
  bool visited[100000];
  int n_visited = 0;

  for (int u, v, len; cin >> u >> v >> len;) {
    adj[u][v] = len;
  }

  priority_queue<int, vector<int>, DistanceCompare> q(DistanceCompare{d});

  d[source] = 0;
  q.push(source);
  while (!q.empty() and n_visited < n) {
    auto u = q.top();
    q.pop();
    if (visited[u])
      continue;
    ++n_visited;
    visited[u] = true;
    for (auto &kv : adj[u]) {
      d[kv.first] = min(d[kv.first], d[u] + kv.second);
      q.push(kv.first);
    }
  }

  for (int i = 0; i < n; ++i) {
    if (visited[i])
      cout << d[i];
    else
      cout << "INF";
    cout << endl;
  }
}

