    Weight weight;

    WeightedEdge() = default;
    WeightedEdge(int src, int dst, Weight weight) : Edge(src, dst), weight(weight) {}

    bool operator< (const WeightedEdge& e) const {
        return weight < e.weight;
    }

    bool operator> (const WeightedEdge& e) const {
        return weight > e.weight;
    }
};

template<class EdgeType = Edge>
