#include <bits/stdc++.h>

using namespace std;

template<typename Edge> class Graph {
public:
  virtual int size() const {return 0;};
  virtual vector<Edge> edges(int v) const {(void)v; return vector<Edge>();}
  virtual void addEdge(const Edge& edge) {(void)edge;};
  virtual vector<Edge> getEdges(int from, int to) const {(void)from; (void)to; return vector<Edge>();};
};

template<typename Edge> class AdjacencyList : public Graph<Edge> {
protected:
  vector<vector<Edge>> graph;

public:
  AdjacencyList(int n = 0) : graph(n) {}

  int size() {
    return graph.size();
  }

  vector<Edge> edges(int v) {
    return graph[v];
  }

  void addEdge(const Edge& edge) {
    if (int(graph.size()) <= max(edge.from, edge.to)) graph.resize(max(edge.from, edge.to) + 1);
    graph[edge.from].emplace_back(edge);
  }

  vector<Edge> getEdges(int from, int to) {
    vector<Edge> res;
    for (const auto& edge : edges(from)) {
      if (edge.to == to) res.emplace_back(edge);
    }
    return res;
  }
};

template<template<typename Edge> class Graph, typename Edge> class ShortestPath {
private:
  typedef __typeof(Edge::cost) Cost;

  struct State {
    int pos;
    Cost cost;
    bool operator<(const State& state) const {return cost > state.cost;}
  };

  Graph<Edge> graph;

public:
  const Cost INF;

  vector<Cost> dist;

  ShortestPath(const Graph<Edge>& graph) : graph(graph), INF(numeric_limits<Cost>::max()) {}

  void run (int from) {
    priority_queue<State> que;
    que.push((State){from, 0});
    dist.resize(graph.size(), INF);
    while (!que.empty()) {
      State now = que.top();
      que.pop();
      if (dist[now.pos] <= now.cost) continue;
      dist[now.pos] = now.cost;
      for (const Edge& edge : graph.edges(now.pos)) {
        if (dist[edge.to] < now.cost + edge.cost) continue;
        que.push((State){edge.to, now.cost + edge.cost});
      }
    }
  }
};

struct Edge {
  int from, to, cost;
};

int main() {
  int v, e, r;
  cin >> v >> e >> r;
  AdjacencyList<Edge> graph(v);
  for (int i = 0; i < e; ++i) {
    int s, t, d;
    cin >> s >> t >> d;
    graph.addEdge((Edge){s, t, d});
  }
  ShortestPath<AdjacencyList, Edge> shortestPath = graph;
  shortestPath.run(r);
  for (int c : shortestPath.dist) {
    if (c != shortestPath.INF) cout << c << endl;
    else cout << "INF" << endl;
  }
}

