struct Edge {
    int src, dst, cost;
    Edge(int src, int dst, int cost) :src(src), dst(dst), cost(cost){}
};

struct State{
    int v, cost;
    State(int v, int cost) :v(v), cost(cost) {}
    bool operator<(State const& s)const{
        return cost>s.cost;
    }
};

typedef vector<vector<Edge>> Graph;
int const inf = 1 << 29;
void dijk(Graph const& g, int r, vi& d){
    priority_queue<State> q;
    d.assign(g.size(), inf);
    d[r] = 0;
    q.push(State(r, 0));
    while (q.size()){
        State s = q.top();
        q.pop();
        if (d[s.v] < s.cost) continue;
        for (auto & e : g[s.v]){
            int cost = e.cost + s.cost;
            if (d[e.dst] > cost){
                d[e.dst] = cost;
                q.push(State(e.dst, cost));
            }
        }
    }
}

