    cin >> x >> y >> z;
    g.add_edge(x, y, z);
  }
  auto cost = dijkstra(g, S);
  for(int i = 0; i < V; i++) {
    if(cost[i] == numeric_limits< int >::max()) cout << "INF" << endl;
    else cout << cost[i] << endl;
  }
}

