void solve(){
    for(int i = 0; i < V; ++i){//距離リストの初期化
        C[i] = INF;
    }

    C[r] = 0;

    for(int i = 1; i < V; ++i){
        bool update = false;
        for(int j = 0; j < E; ++j){
            int u = S[j], v = T[j];
            if(C[v] > (C[u] + D[j])) {
                C[v] = C[u] + D[j];
                update = true;
            }
        }
        if (!update) break; //一巡して更新が無くなるまで続ける
    }

    for(int i = 0; i < V; ++i){//距離リストの出力
        if(C[i] == INF) 
            cout << "INF" << endl;
        else
            cout << C[i] << endl;
