struct Edge {
  ll to;
  ll cost;
};

using Graph = vector<vector<Edge>>;
using P = pair<ll, int>;

/* dijkstra(G,s,dis)
    入力：グラフ G, 開始点 s, 距離を格納する dis
    計算量：O(|E|log|V|)
    副作用：dis が書き換えられる
*/
void dijkstra(const Graph &G, int s, vector<ll> &dis) {
  int N = G.size();
  dis.resize(N, INF);
  priority_queue<P, vector<P>, greater<P>> pq;  // 「仮の最短距離, 頂点」が小さい順に並ぶ
  dis[s] = 0;
  pq.emplace(dis[s], s);
  while (!pq.empty()) {
    P p = pq.top();
    pq.pop();
    int v = p.second;
    if (dis[v] < p.first) {  // 最短距離で無ければ無視
      continue;
    }
    for (auto &e : G[v]) {
      if (dis[e.to] > dis[v] + e.cost) {  // 最短距離候補なら priority_queue に追加
        dis[e.to] = dis[v] + e.cost;
        pq.emplace(dis[e.to], e.to);
      }
    }
  }
}

int main() {
  ll V, E, r;
  cin >> V >> E >> r;

  Graph g;
  g.assign(V, vector<Edge>());  // numV点分の空要素を作成

  for (int i = 0; i < E; ++i) {
    ll s, t, d;
    cin >> s >> t >> d;
    Edge e = {t, d};
    g[s].emplace_back(e);
  }

  vector<ll> dis;

  dijkstra(g, r, dis);

