  REP(i,e)
  {
    int s,t,w; cin>>s>>t>>w;
    g.direct(s,t,w);
  }
  auto ans = g.bellmanFord(r);
  for(auto x : ans)
  {
    if(x==INF) cout << "INF" << endl;
    else cout << x << endl;
  }
  return 0;
}

