        for (int ei : g.vertex_to[v]) {
            auto e = g.edges[ei];
            dist[e.to(v)] = min(dist[e.to(v)], dist[v] + e.value);
        }
        v = -1;
        for (int i = 0; i < g.n; ++i)
            if (!visited[i] && (v == -1 || dist[i] < dist[v]))
                v = i;
    }
}





