	while (!PQ.empty()) {

		f = PQ.top().first;//first is the distance 
		s = PQ.top().second;//second is the target node
		PQ.pop();

		for (int i = 0; i < G[s].size(); i++) {
			E e = G[s][i];
			if (d[e.rel] > e.cost - f) {
				d[e.rel] = e.cost - f;
				PQ.push(make_pair(-d[e.rel], e.rel));
			}
		}

	}

	for (int i = 0; i < v; i++) {
		if (d[i] == INF){ 
			cout << "INF" << endl; 
		}else{ 
			cout << d[i] << endl; 
		}

	}

	return 0;
}

