    for (int i = 0; i < E; ++i) {
        std::cin >> s >> t >> d;
        dk.addEdge(s, t, d);
    }

    const std::vector<int> paths = dk.shortestPath(r);
    for (int p : paths) {
        if (p == INT32_MAX) {
            std::cout << "INF" << std::endl;
        } else {
            std::cout << p << std::endl;
        }
    }

    return 0;
}

