template<class VP,class EP>
class directed_graph : public graph<VP,EP> {
public:
  using vertex_prop = VP;
  using edge_prop = EP;
  using vertex_type = vertex<VP,EP>;
  using edge_type = edge<VP,EP>;
  using vertex_iterator = typename std::list<vertex_type>::iterator;
public:
  directed_graph() : graph<VP,EP>() {}
  directed_graph(int sz) : graph<VP,EP>() {
    for(int i = 0;i < sz;i++) { 
      this->add_vertex(vertex_prop());
    }
  }
  vertex_iterator add_vertex(const vertex_prop& vp) {
    this->vps.push_back(vp);
    this->vs.push_back(vertex_type(this->g_id,this->V, --this->vps.end()));
    this->ivs.push_back(--this->vs.end());
    this->V++;
    return --this->vs.end();
  }
  void add_edge(vertex_iterator& ifrom, vertex_iterator& ito, const edge_prop& ep) {
    if(ifrom->g_id != this->g_id || ifrom->g_id != ito->g_id) return;
    this->eps.push_back(ep);
    this->es.push_back(edge_type(this->g_id,this->E,ifrom,ito,--this->eps.end()));
    ifrom->delta().push_back(--this->es.end());
    this->E++;
  }
};

