template<class VP, class EP, class WW>
std::vector<weighted<WW>> dijkstra(const directed_graph<VP,EP>& g,typename directed_graph<VP,EP>::vertex_iterator s, std::function<weighted<WW>(const EP&)> f) {
    using W = weighted<WW>;
    using V = typename directed_graph<VP,EP>::vertex_iterator;
    using P = std::pair<W,int>;
    int n = g.vertices_cnt();
    std::priority_queue<P,std::vector<P>,std::greater<P>> que;
    std::vector<W> dist(n,-1);
    dist[s->id] = W::zero();
    que.push({dist[s->id], s->id});
    while(!que.empty()) {
        V v = g[que.top().second];
        W d = que.top().first;
        que.pop();
        if(dist[v->id] < d) continue;
        for(auto e : v->delta()) {
            if(dist[e->to()->id] == -1 || dist[e->to()->id] > d + f(e->prop())) {
                dist[e->to()->id] = d + f(e->prop());
                que.push({dist[e->to()->id], e->to()->id});
            }
        }
    }

    return dist;
}

