int main()
{
	int v, e, r;
	std::cin >> v >> e >> r;

	std::vector<Node> nodes(v);
	nodes[r].cost = 0;

	for (int i = 0; i < e; i++) {
		int s, t, d;
		std::cin >> s >> t >> d;
		nodes[s].edges.push_back({ t, d });
	}

	auto less_node = [&](int x, int y) { return nodes[x].cost < nodes[y].cost; };
	std::vector<int> queue;
	queue.push_back(r);

	while (!queue.empty()) {
		auto min = std::min_element(queue.begin(), queue.end(), less_node);
		Node& node = nodes[*min];
