class Node{
public:
	vector<int> to;
	vector<int> ecost;
	int cost;
	bool done;
};

void find(Node *node, int nodes, int start);

int main(){
	int v, e, r;
	cin >> v >> e >> r;

	int s[e], t[e], d[e];
	int i;
	for(i=0 ; i<e; i++){
		cin >> s[i] >> t[i] >> d[i];
	}

	Node node[v];
	for(i=0; i<e; i++){
		node[s[i]].to.push_back(t[i]);
		node[s[i]].ecost.push_back(d[i]);
	}

	find(node, v, r);
	for(i=0; i<v; i++){
		if(node[i].cost==-1){ cout << "INF" << endl;}
		else{ cout << node[i].cost << endl; }
	}

	return 0;
}

void find(Node *node, int nodes, int start){
	int i, j;
	for(i=0; i<nodes; i++){
		node[i].done=0;
		node[i].cost=-1;
	}
	node[start].cost=0;
	node[start].done=1;

	for(i=0; i<node[start].to.size(); i++){
		node[node[start].to[i]].cost = node[start].ecost[i];
	}

	bool dflag;
	while(1) {
		j=1;
	    for(i=0; i<nodes; i++){ j *= node[i].done; }
	    if(j) break;

		for(i=0; i<nodes; i++){
			dflag=1;
			if(node[i].done) continue;
			if(node[i].cost==-1) continue;

			for(j=0; j<node[i].to.size(); i++){
				if(node[j].cost == -1){
					node[node[i].to[j]].cost = node[i].cost+node[i].ecost[j];
					dflag=0;
					continue;
				}
				if(node[i].cost+node[i].ecost[j] < node[node[i].to[j]].cost){
					node[node[i].to[j]].cost = node[i].cost+node[i].ecost[j];
					dflag=0;
					continue;
				}
			}
			if(dflag) node[i].done=1;
		}
	}
}

