template<typename T>
class Deque{
public:
  T *val;
  int sz;
  int length;
  int head, tail;

  Deque(){sz = 0, length = 0;}
  Deque(int size, T init = T()){
    length = 1;
    while(length < size) length *= 2;
    val = new T[length];
    sz = size;
    head = 0;
    tail = 0;
    for(int i=0;i<size;i++) val[tail++] = init;
  }

  T& operator [] (int i){assert(0 <= i && i < sz);return val[(head + i)%length];}
  int size(){return sz;}

  void increaseMemory(){
    int length_ = length;

    length = length * 2;
    if(length == 0) length = 1;
    T *val2 = new T[length];
    for(int i=0;i<sz;i++) val2[i] = val[(head + i)%length_];
    head = 0;
    tail = sz;
    delete [] val;
    val = val2;
  };

  void push_back(T v){
    if(sz == length) increaseMemory();
    sz++;
    val[tail++] = v;
    if(tail == length) tail = 0;
  }

  void push_front(int v){
    if(sz == length) increaseMemory();
    sz++;
    head--;
    if(head == -1) head = length - 1;
    val[head] = v;
  }

  void pop_back(int v){
    tail--;
    if(tail == -1) tail = 0;
  }

  void pop_front(int v){
    head++;
    if(head == length) head = 0;
  }
};
