template<typename T>
class Priority_queue{
public:
  T *A;
  int H;
  int sz;
  T MIN;

  constexpr Priority_queue(){H = 0, sz = 0;}
  constexpr Priority_queue(int size, T mn){
    MIN = mn;
    A = new T[size];
    H = 0;
    sz = 0;
  }

  int size(){return sz;}
  int empty(){return sz == 0;}

  void swap(T &a, T & b){
    T tmp = a;
    a = b;
    b = tmp;
  }

  void maxHeapify(int i){
    int l=i * 2;
    int r=i * 2 + 1;
    int largest;
    if(l <= H && A[l] > A[i]) largest = l;
    else largest = i;

    if(r <=H && A[r] > A[largest]) largest = r;

    if(largest != i) {
      swap(A[i], A[largest]);
      maxHeapify(largest);
    }
  }

  void heapIncreaseKey(int i, T key){
    A[i] = key;
    while(i > 1 && A[i/2] < A[i]){
      swap(A[i], A[i/2]);
      i /= 2;
    }
  }

  void push(T k){
    sz++;
    H++;
    A[H] = MIN;
    heapIncreaseKey(H, k);  
  }

  T top(){return A[1];}

  T pop(){
    sz--;
    T res = A[1];
    A[1] = A[H];
    H--;
    maxHeapify(1);
    return res;
  }
};

template <typename T, typename D>
class Pair{
public:
  T first;
  D second;
  Pair(){first = second = 0;}
  Pair(const T first, const D second):first(first), second(second){}

  bool operator < (const Pair t)const{
    return first != t.first? (first < t.first):(second < t.second);
  }
  bool operator > (const Pair t)const{
    return first != t.first? (first > t.first):(second > t.second);
  }
};


