struct Node {
  int to;
  int cost;

  bool operator> (const Node &other) const {
    return cost > other.cost;
  }
};

int main() {
  int v, e;
  int r;
  cin >> v >> e >> r;

  V<V<Node>> graph(v);

  rep(i, e) {
    int s, t, d;
    cin >> s >> t >> d;
    graph[s].push_back({t, d});
  }

  int inf = 1e9;
  V<bool> seen(v, false);
  priority_queue<Node, V<Node>, greater<Node>> todo;
  V<int> dist(v, inf);
  todo.push({r, 0});
