int V, E, start;

void bellman(int s)
{
    rep(i, V) dist[i] = iINF;
    dist[s] = 0;
    while (true)
    {
        bool update = false;
        rep(i, E)
        {
            for (auto e : graph[i])
            {
                if (dist[i] != llINF && dist[e.to] > dist[i] + e.cost)
                {
                    dist[e.to] = dist[i] + e.cost;
                    update = true;
                }
            }
        }

        if (!update)
            break;
    }
}

