void dijkstra(){
  for(int i=0;i<V;i++) mindist[i] = IINF;
  mindist[r] = 0;
  priority_queue<int> Q;
  Q.push(r);
  while( !Q.empty() ){
    int cur = Q.top(); Q.pop();
    for(int i=0;i<(int)G[cur].size();i++){
      int next   = G[cur][i];
      int weight = W[cur][i];
      if( mindist[next] > mindist[cur] + weight )  {
	mindist[next] = mindist[cur] + weight;
	Q.push(next);
      }
    }
  }
}

