using P = pair<int, int>;

void dijkstra(int s)
{
  // コストが小さいものがtop()にくる
  priority_queue<P, vector<P>, greater<P>> q;
  memset(costs, 0x3f, sizeof(costs));
  costs[s] = 0;
  q.push(P(0, s));

  while (!q.empty())
  {
    P p = q.top();
    q.pop();

    int v = p.second;
    if (costs[v] < p.first)
      continue;

    rep(i, g[v].size())
    {
      Edge e = g[v][i];
      if (costs[e.to] > costs[v] + e.cost)
      {
        costs[e.to] = costs[v] + e.cost;
        q.push(P(costs[e.to], e.to));
      }
    }
  }
}

