int main() {

  ll s, t, d;

  cin >> V >> E >> r;

  for(int i=0; i<E; ++i) {
    cin >> s >> t >> d;
    es[i].from = s;
    es[i].to = t;
    es[i].cost = d;
  }

  shortest_path(r);

  return 0;
