void shortest_path(int s) {

  for(int i=0; i<V; ++i) l[i] = INF;

  l[s] = 0;

  while(true) {
    bool update = false;

    for(int i=0; i<E; ++i) {
      edge e = es[i];

      if(l[e.from] != INF && l[e.to] > l[e.from] + e.cost) {
        l[e.to] = l[e.from] + e.cost;
        update = true;
      }
    }
    if(!update) break;
  }

  for(int i=0; i<V; ++i) {
    if(l[i]==INF) cout << "INF" << endl;
    else cout << l[i] << endl;
  }
}

