namespace SOLVE {
	struct edge {
		ll from, to, weight;
	};

	struct vertex {
		ll distance = 1e15, no;
	};

	struct compareVertex {
		bool operator() (vertex const& p1, vertex const& p2) {
			return p1.distance > p2.distance;
		}
	};



	void main() {
		ll V, E, s, t1, t2, t3;
		cin >> V >> E >> s;

		vector<vector<edge> > edges(V + 5);
		REP(i, 0, E) {
			cin >> t1 >> t2 >> t3;
			edge e;
			e.from = t1;
			e.to = t2;
			e.weight = t3;
			edges[t1].push_back(e);
		}

		VLL ans(V + 5, 1e15);
		VLL finalised(V + 5, 0);

		priority_queue<vertex, vector<vertex>, compareVertex> pq;
		vertex start;
		start.distance = 0;
		start.no = s;
		pq.push(start);


		while (sz(pq)) {
			vertex top = pq.top();
			//cout << top.no << endl;
			pq.pop();

			if (finalised[top.no] == 1) {
				continue;
			}
			ans[top.no] = top.distance;
			finalised[top.no] = 1;

			for (edge e : edges[top.no]) {
				if (top.distance + e.weight < ans[e.to]) {
					vertex v;
					v.distance = top.distance + e.weight;
					v.no = e.to;
					pq.push(v);
				}
			}
		}

		REP(i, 0, V) {
			if (ans[i] == 1e15) {
				cout << "INF\n";
			}
			else {
				cout << ans[i] << endl;
			}
		}




	}
}


