template<typename T>
void dijkstra(int s, vector<vector<edge>>& path, vector<T>& d) {
	priority_queue<P, vector<P>, greater<P>> q;
	q.push(P(0, s));
	d[s] = 0;
	while (!q.empty()) {
		P p = q.top();
		q.pop();
		int v = p.second;
		if (d[v] < p.first)continue;
		REP(i, path[v].size()) {
			edge e = path[v][i];
			if (d[e.to] > d[v] + e.cost) {
				d[e.to] = d[v] + e.cost;
				q.push(P(d[e.to], e.to));
			}
		}
	}
	return;
}

