      for(Int i = 0; i < e; ++i) {
         Int a, b, c; scan(a, b, c);
         graph.addEdge(a, b, c);
      }
      Solver4 dijkstra;
      auto xs = dijkstra.solve(graph, r);
      for(Int i = 0; i < v; ++i) {
         Maybe<Int> w = xs[i];
         if( not w.valid ) {
            puts("INF");
         }
         else {
            std::cout << w << std::endl;
         }
      }
   }
};

int main() {
   loop std::unique_ptr<Solver>(new Solver())->solve();
}

