vector <int> BellmanFord(WeightedGraph g, int s){
    int n = g.size();
    vector <int> d(n, INF);
    d[s] = 0;
    bool update = true;
    vector <int> tonum(n);
    rep(i,n) tonum[i] = g[i].size();
    int limit = n;
    while(update){
        update = false;
        limit--;
        if(!limit) {d.push_back(-96); return d;}
        rep(i,n){
            rep(j, tonum[i]){
                if(chmin(d[g[i][j].F], d[i] + g[i][j].S)) update = true;
            }
        }
    }
    return d;
} //d.size() == n+1なら負の閉路あり 

