	for (ll i = 0; i < E; i++) {
		ll s, t, cost;
		cin >> s >> t >> cost;
		G[s].push_back(edge{ t, cost });
	}

	dijkstra(r);

	for (ll i = 0; i < V; i++) {
		if(d[i]==INF) cout << "INF" << endl;
		else cout << d[i] << endl;
	}
}

