void calcShortestPath(std::map<int, std::map<int, int> > &path,
			std::vector<long long> &shortestPath, int V, int E, int r)
{
	for (int mid = 0; V > mid; ++mid) {
		for (int start = 0; V > start; ++start) {
			for (int goal = 0; V > goal; ++goal) {
				if (((path.end() != path.find(start)) && (path[start].end() != path[start].find(mid))) && 
					((path.end() != path.find(mid)) && (path[mid].end() != path[mid].find(goal)))) {
					int tmp = path[start][mid] + path[mid][goal];
					if((r == start) && (shortestPath[goal] > tmp)) {
						shortestPath[goal] = tmp;
					}
					if((path.end() != path.find(start)) && (path[start].end() != path[start].find(goal))) {
						if(path[start][goal] > tmp) {
							path[start][goal] = tmp;
						}
					}
					else {
						path[start][goal] = tmp;
					}
				}
			}
		}
	}
}

