void Graph::Dijkstra(int r) {
	d[r] = 0;
	for (int i = 0; i < N; i++)
		Q.push(make_pair(0, r));
	while (!Q.empty()) {
		int u = Q.top().second;
		Q.pop();
		if (S.find(u) != S.end())
			continue;
		S.insert(u);
		for (auto i = List[u].begin(); i != List[u].end(); ++i) {
			int v = (*i).first;
			if (S.find(v) != S.end())
				continue;
			else {
				int w = (*i).second;
				if (d[v] > d[u] + w) {
					d[v] = d[u] + w;
					Q.push(make_pair(d[v], v));
				}
			}
		}
	}
	for (int i = 0; i < N; i++) {
		if (d[i] == INF)
			cout << "INF" << endl;
		else
			cout << d[i] << endl;
	}
}

