typedef pair<int, int> i_i;
struct edge { int v, w; };

vector<int> dijkstra(int N, vector<vector<edge> >& G, int s) {
	vector<int> d(N, INT_MAX);
	d[s] = 0;
	priority_queue<i_i, vector<i_i>, greater<i_i> > pq;
	pq.push(i_i(0, s));
	while (pq.size()) {
		i_i p = pq.top(); pq.pop();
		int u = p.second;
		if (p.first > d[u]) continue;
		for (edge e: G[u])
			if (d[e.v] > d[u] + e.w) {
				d[e.v] = d[u] + e.w;
				pq.push(i_i(d[e.v], e.v));
			}
	}
	return d;
}


