#define FAC 1000010
ll fac[FAC],ivf[FAC],inv[FAC];
void initfac(){
	fac[0]=ivf[0]=inv[1]=1;
	for(ll i=1;i<FAC;i++){
		if(i>1)inv[i]=(mod-mod/i*inv[mod%i]%mod)%mod;
		ivf[i]=ivf[i-1]*inv[i]%mod;
		fac[i]=fac[i-1]*i%mod;
	}
}
ll Pmod(ll n,ll k){
	if(n<k)return 0;
	if(k<0)return 0;
	return fac[n]*ivf[n-k]%mod;
}
ll Cmod(ll n,ll k){
	if(n<k)return 0;
	if(k<0)return 0;
	return fac[n]*ivf[n-k]%mod*ivf[k]%mod;
}
