class UnionFind{
	public:
	int n,*dat;
	int comp;
	void init(int N){
		n=N;
		dat=new int[n];
		rep(i,n)dat[i]=-1;
		comp=n;
	}
	int par(int x){
		if(dat[x]<0)return x;
		return par(dat[x]);
	}
	void unite(int a,int b){
		a=par(a),b=par(b);
		if(a==b)return;
		if(-dat[a]<-dat[b])swap(a,b);
		dat[a]+=dat[b];
		dat[b]=a;
		comp--;
	}
	bool same(int a,int b){
		a=par(a),b=par(b);
		return a==b;
	}
	int size(int a){
		a=par(a);
		return -dat[a];
	}
};
class Dijkstra{
	public:
	int n;
	ll *dist,*pre;
	vector<int> *to;
	vector<ll> *len;
	void init(int N){
		n=N;
		dist=new ll[n];
		pre=new ll[n];
		to=new vector<int>[n];
		len=new vector<ll>[n];
	}
	void aed(int a,int b,ll c){
		to[a].push_back(b);
		len[a].push_back(c);
	}
	void aeud(int a,int b,ll c){
		aed(a,b,c);
		aed(b,a,c);
	}
	void work(int s){
		rep(i,n)dist[i]=inf;
		priority_queue<plll,vector<plll>,greater<plll> > Q;
		Q.push(mplll(0,s,-1));
		while(!Q.empty()){
			ll cost=Q.top().first;
			ll x=Q.top().second.first;
			ll from=Q.top().second.second;
			Q.pop();
			if(dist[x]<=cost)continue;
			dist[x]=cost;
			pre[x]=from;
			rep(i,to[x].size()){
				Q.push(mplll(cost+len[x][i],to[x][i],x));
			}
		}
	}
};

