class Edge{
public:
    int u, v, cost;
    Edge(int u, int v, int cost):
        u(u), v(v), cost(cost) {}
    bool operator < (const Edge& e) const {
        return cost != e.cost ? cost < e.cost :
            u != e.u ? u < e.u : v < e.v;
    }
};
using Edges = vector<Edge>;
using Graph = vector<Edges>;

/* Dijkstra Algorithm */
void dijkstra(Graph& G, vector<int>& d, vector<int>& p, int s)
{
    int V = G.size();
    priority_queue<Edge> Q;

    d[s] = 0;
    Q.push(Edge(s,s,0)); // Edge.cost as d
    while(!Q.empty()) {
        Edge e = Q.top(); Q.pop();
        if(d[e.v] == INF) continue;
        if(p[e.u] == -1) continue;
        for(auto& f:G[e.v]) if(d[f.v] > d[f.u] + f.cost) {
                d[f.v] = d[f.u] + f.cost;
                Q.push(Edge(f.u, f.v, d[f.u] + f.cost));
            }
    }
}

