void prim(int u)
{
    fill(Min,Min+100007,1e11);
    Min[u]=0;
    node nd;
    nd.id=u;
    nd.dp=0;

    priority_queue <node> q;
    q.push(nd);

    while(q.size()>0)
    {
        nd=q.top();
        q.pop();
        if(mark[nd.id])
            continue;
        mark[nd.id]=1;
        int u=nd.id;

        for(int i=0;i<adj[u].size();i++)
        {
            int v=adj[u][i].des;
            int val=adj[u][i].w;

            if(Min[v]<=val+nd.dp)
                continue;
            Min[v]=val+nd.dp;
            node nn;
            nn.id=v;
            nn.dp=val+nd.dp;
            q.push(nn);
        }
    }
}

