using namespace std;

const int maxnum = 1000;
const int maxint = 9999999;

int V;                               //V -- V nodes
int E;                               //E -- the number of lines
int r;                               //r -- the source node
int dist[maxnum];                    //dist[] -- the distance from the ith node to the source node
int previ[maxnum];                   //previ[] -- the previous node of the ith node
int c[maxnum][maxnum];               //c[][] -- every two nodes' distance

void Dijkstra(int V, int r, int *dist,int *previ,int c[maxnum][maxnum])
{
    bool s[maxnum];                  //judge if the node is in the set s
    for(int i = 0;i < V; i++)
    {
        dist[i] = c[r][i];
        s[i] = false;
    }
    dist[r] = 0;
    s[r] = 1;

    //put the node which is not in the set s and whose value of set dist[] is minimum into set s in turn until s includes all the vertices in V

    for(int i = 1; i < V; i++)
    {
        int tmp = maxint;
        int u = r;
        for(int j = 0; j < V; j++)
        {
            if((s[j] == false) && dist[j] < tmp)
            {
                u = j;
                tmp = dist[j];
            }
        }
        s[u]=1;  //u is in the set s

        //update the dist
        for(int j = 0;j < V; j++)
        {
            if((s[j] == false) && c[u][j] != maxint)
            {
                int dist2 = dist[u] + c[u][j];
                if(dist2 < dist[j])
                {
                    dist[j] = dist2;
                    previ[j] = u;
                }

            }

        }

    }
}

