    {
        cin>>m>>n>>len;
        c[m][n] = len;
    }

    for(int i = 0;i <= V-1;i++)
    {
        dist[i] = maxint ;
    }
    Dijkstra(V,r,dist,previ,c);
    for(int i=0;i <= V-1;i++)
    {
        if(dist[i] < maxint)
            cout<<dist[i]<<endl;
        else
            cout<<"INF"<<endl;
    }
}

