        G[a].push_back(e);
    }

    vector<long long> d(MAX_V, INF);

    Dijkstra(r, d);

    for (int i = 0; i < V; i++){

        if (d[i] == INF) cout << "INF" << endl;
        else cout << d[i] << endl;

    }

    return 0;
}

