    cin >> from >> to >> cost;
    G[from].emplace_back(to, cost);
  }

  auto dist = dijkstra(G, r);

  for (auto d : dist) {
    if (d == numeric_limits<int>::max()) {
      cout << "INF\n";
    } else {
      cout << d << endl;
    }
  }

  return 0;
}

