    bool operator<(const State& s)const{
        return d>s.d;
    }
};

void dijkstra(Graph const &g, int s, vector<Weight> &dist) {
    priority_queue<State> q;
    dist.assign(g.size(), inf); dist[s] = 0;
    q.push(State(s, 0));
