  fill_n(visited, Vnum, false);
  d[r] = 0;

  for (int i = 0; i < Vnum; i++) {
    int u = 0;
    for (; visited[u]; u++);

    for (int j = 0; j < Vnum; j++) {
      if (visited[j]) continue;
      if (d[j] < d[u]) {
        u = j;
      }
    }
    visited[u] = true;
    for (Edge v : edges[u]) {
      if (d[v.to] > d[u] + v.cost)
        d[v.to] = d[u] + v.cost;
    }
  }
  for (int i = 0; i < Vnum; i++) {
    if (d[i] == Dmax) {
      cout << "INF" << endl;
    } else {
      cout << d[i] << endl;
    }
  }
  return 0;
}

