void dijkstra() {
    nodeptr tmp;

    while (!q.empty()) {
        pii u = q.top(); q.pop();
        int x = u.second;
        if (S[x]) {continue;}
        S[x] = 1;

        tmp = adjacencyList[x]->head;
        while (1) {
            if (tmp != NULL) {
                if (tmp->dist + d[x] < d[tmp->id]) {
                    d[tmp->id] = tmp->dist + d[x];
                    q.push(make_pair(d[tmp->id], tmp->id));
                }
                tmp = tmp->next;
            } else {
                break;
            }
        }
    }
}

