        if(ds[v] < c)continue;
        for(const Edge<Cost>& e:g[v]){
            Cost nxtc= c + e.cost;
            if(nxtc<ds[e.to]){
                ds[e.to]=nxtc;
                que.push({nxtc,e.to});
            }
        }
    }
    return ds;
}


