        EDGE e1 = {b,c};
        G[a].pb(e1);/*頂点aから頂点bへのコストがc*/
    }
    /*辺の張り終わり*/

    vector<ll> d = dijkstra(n,G,r);/*経由点から各頂点への最短距離を格納した配列*/

    REP(i,n){
        if(d[i] == INF){
            cout << "INF" << endl;
        }else{
            cout << d[i] << endl;
        }
    }

    return 0;
}

