int main() {
    cin >> V >> E;
    int r; cin >> r;
    G.clear(); G.resize(V);
    for (int i = 0; i < E; i++) {
        int s, t, d; cin >> s >> t >> d;
        G[s].push_back(Edge(t, d));
    }

    vector<int> D(V, INF);
    D[r] = 0;
    priority_queue<S> PQ;
    PQ.push(S(r, 0));
    while (!PQ.empty()) {
        S c = PQ.top(); PQ.pop();
        for (int i = 0; i < G[c.v].size(); i++) {
            Edge& e = G[c.v][i];
            int ncost = D[c.v] + e.cost;
            if (D[e.to] > ncost) {
                D[e.to] = ncost;
                PQ.push(S(e.to, ncost));
            }
        }
