template <typename T, bool P = false> class PairingHeap {
	static constexpr std::uint_fast64_t ALLOCSIZE = (std::uint_fast64_t)1 << 10;

public:
	struct node_t {
		T data;
		node_t *left, *right, *per;
	};

private:
	node_t *root;
	std::uint_fast32_t size_;
	static node_t *merge(node_t *x, node_t *y) {
		if (P ^ (x->data < y->data))
			std::swap(x, y);
		if (x->right = y->left)
			y->left->per = x;
		y->left = x;
		x->per = y;
		return y;
	}

public:
	PairingHeap() : root(nullptr), size_(0) {}
	const T &top() const {
		assert(root);
		return root->data;
	}
	const T &pop() {
		assert(root);
		--size_;
		const T &ret = root->data;
		node_t *n = nullptr, *x = root->left, *y;
		while (x) {
			y = x;
			if (x->right) {
				x = x->right->right;
				y = merge(y, y->right);
			}
			else {
				x = nullptr;
			}
			y->right = n;
			n = y;
		}
		if (!n) {
			root = nullptr;
			return ret;
		}
		root = n;
		n = n->right;
		while (n) {
			x = n;
			n = n->right;
			root = merge(root, x);
		}
		root->per = nullptr;
		root->right = nullptr;
		return ret;
	}
	node_t *push(const T &data) {
		static node_t *pool = nullptr;
		static std::uint_fast64_t it = ALLOCSIZE;
		if (it == ALLOCSIZE) {
			pool = (node_t *)malloc(ALLOCSIZE * sizeof(node_t));
			it = 0;
		}
		node_t *top = &pool[it++];
		top->data = data;
		top->left = top->right = top->per = nullptr;
		root = root ? merge(root, top) : top;
		++size_;
		return top;
	}
	bool empty() { return !root; }
	std::uint_fast32_t size() { return size_; }
	void meld(PairingHeap<T, P> &other) {
		size_ += other.size_;
		other.size_ = 0;
		if (other.root) {
			root = root ? merge(root, other.root) : other.root;
			other.root = nullptr;
		}
	}
	void decrease(node_t *const x, const T &data) {
		assert(x);
		assert(!(P ^ (x->data < data)));
		x->data = data;
		if (!x->per)return;
		if (x->right)
			x->right->per = x->per;
		if (x->per->right != x)
			x->per->left = x->right;
		else
			x->per->right = x->right;
		x->per = nullptr;
		x->right = nullptr;
		root = merge(root, x);
	}
};
