	long ans_val = dijekstra(start,end);

	if (ans_val == -1) cerr << "Not connected" << endl; //連結でなかった場合。
	else {
		#ifdef TRACE_ROUTE
			REP(i,trace.size()) cout << trace[i] << endl; //経路復元
		#endif
		cout << ans_val << endl; 	//最短距離の表示
	}

 	return 0;
 }

