  }
  bool operator<(const vertex b) const
  {
    return (b.d-d>0);
  }
};
class edge
{
public:
  int vt;
  int d;
  edge()
  {
    vt=-1;
    d=0;
  }
  edge(int v,int dis)
  {
    vt=v;
    d=dis;
  }
};
vector<edge> E[100001];
priority_queue<vertex> Q;
long long int dist[100001];

void dijkstra(int s)
{
  for(int i=0;i<nofv;i++)
    dist[i]=INF;
  dist[s]=0;
  Q.push(vertex(s,0));
  while(!Q.empty())
  {
    vertex now=Q.top();
    Q.pop();
    int nowv=now.n;
    if (now.d>dist[nowv]) continue;
    for(vector<edge>::iterator it=E[nowv].begin();it!=E[nowv].end();++it)
    {
      int vt=(*it).vt;int d=(*it).d;
      if (dist[vt]>dist[nowv]+d)
      {
        dist[vt]=dist[nowv]+d;
        Q.push(vertex(vt,dist[vt]));
      }
    }
  }
}
