void check(Node *node, int nodes, int start){
	int i ,j;
	for(i=0; i<node[start].to.size(); i++){
		node[node[start].to[i]].avail=1;
	}
	int loop=1;
	while(loop){
		loop=0;
		for(i=0; i<nodes; i++){
			for(j=0; j<node[i].to.size(); j++){
				if(node[node[i].to[j]].avail==0){
					node[node[i].to[j]].avail=1;
					loop=1;
				}
			}
		}
	}
	for(i=0; i<nodes; i++){
		if(node[i].avail==0){
			node[i].done=1;
		}
	}
}

void find(Node *node, int nodes, int start){
	int i, j;
	if(node[start].done) return;

	node[start].cost=0;
	node[start].done=1;

	for(i=0; i<node[start].to.size(); i++){
		node[node[start].to[i]].cost = node[start].ecost[i];
	}


	bool dflag;
	while(1) {
		j=1;
	    for(i=0; i<nodes; i++){ j *= node[i].done; }
	    if(j) break;

		for(i=0; i<nodes; i++){
			dflag=1;
			if(node[i].to.size()==0) node[i].done=1;
			if(node[i].done) continue;
			if(node[i].cost==-1) continue;

			for(j=0; j<node[i].to.size(); j++){
				if(node[node[i].to[j]].cost == -1){
					node[node[i].to[j]].cost = node[i].cost + node[i].ecost[j];
					dflag=0;
					continue;
				}
				if(node[node[i].to[j]].cost > node[i].cost + node[i].ecost[j]){
					node[node[i].to[j]].cost = node[i].cost + node[i].ecost[j];
					dflag=0;
					continue;
				}
			}
			if(dflag) node[i].done=1;
		}
	}
}

