typedef pair<int,int> P;

int h;
P A[H];

void maxHeapify(int x){
  int l=x*2,r=x*2+1,lag;
  if(l<=h&&A[l].first>A[x].first)lag=l;
  else lag=x;
  if(r<=h&&A[r]>A[lag])lag=r;
  if(lag!=x){
    swap(A[x],A[lag]);
    maxHeapify(lag);
  }
}

void heapIncreaseKey(int x,P key){
  A[x]=key;
  while(x>1&&A[x/2]<A[x]){
    swap(A[x],A[x/2]);
    x=x/2;
  }
}

void insert(P key){
  A[++h].first=-1;
  heapIncreaseKey(h,key);
}

P extractMax(){
  P res=A[1];
  A[1]=A[h--];
  maxHeapify(1);
  return res;
}

