template<typename T> bool chmin(T a, T &b) { return a < b ? b = a, true : false; }
template<typename T> bool chmax(T a, T &b) { return a > b ? b = a, true : false; }
template<typename T> T rpow(T a, ll n) {
    if (n == 0) return 1;
    T k = 1;
    for (; n > 1; n >>= 1) {
        if (n & 1) k *= a;
        a *= a;
    }
    return k * a;
}

