void dijkstra() {
  fill_n(d, Vnum + 1, Dmax);
  fill_n(visited, Vnum, false);
  d[r] = 0;
  for (int i = 0; i < Vnum; i++) {
    int u = Vnum;
    for (int j = 0; j < Vnum; j++) {
      if (!visited[j] && d[j] < d[u]) {
        u = j;
      }
    }
    if (u == Vnum) {
      break;
    }
    visited[u] = true;
    for (int j = 0; j < edges[u].size(); j++) {
      auto v = edges[u][j];
      d[v.to] = min(d[v.to], d[u] + v.cost);
    }
  }
