    q.push(P(0,r));
  }

  while(!q.empty()){
    auto p = q.top();q.pop();
    int v = p.second;
    llong w = p.first;
    if(dist[v]!=INF) continue;
    dist[v] = w;
    for(auto &next_p:graph[v]){
      int next_v = next_p.second;
      if(dist[next_v]!=INF) continue;
      q.push(P(w+next_p.first,next_v));
    }
  }

  for(int i=0;i<n;++i){
    if(dist[i]!=INF){
      cout << dist[i] << endl;
    }else{
      cout << "INF" << endl;
    }
  }

}

