template<typename T>
struct Q002 {
   Int v;
   std::vector<std::vector<std::tuple<Int, T>>> graph;
   Q002(Int v_) : v(v_), graph(v) {}
   void set(Int a, Int b, T c) {
      graph[a].emplace_back(b, c);
   }
   const std::vector<std::tuple<Int, T>>& nexts(Int a) const {
      return graph[a];
   }
};

template<typename T>
struct F002 {
   std::vector<std::tuple<bool, T>> operator()(const Q002<T>& graph, Int begin) const {
      Int v = graph.v;
      std::vector<std::tuple<bool, T>> xs(v, std::make_tuple(false, 0));
      std::priority_queue<std::tuple<T, Int>, std::vector<std::tuple<T, Int>>, std::greater<std::tuple<T, Int>>> q;
      q.push(std::make_tuple(0, begin));
      xs[begin] = std::make_tuple(true, 0);
      while( not q.empty() ) {
         T d; Int i; std::tie(d, i) = q.top(); q.pop();
         for(auto kc : graph.nexts(i)) {
            Int k; T c; std::tie(k, c) = kc;
            T nd = d + c;
            bool b; T td; std::tie(b, td) = xs[k];
            if( not b or nd < td ) {
               xs[k] = std::make_tuple(true, nd);
               q.push(std::make_tuple(nd, k));
            }
         }
      }
      return xs;
   }
};

