using P = pair<int ,int>;
const int INF = 1e9;
const int MOD = 1e9+7;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int v, e, r; cin >> v >> e >> r;
    vector<vector<P>> G(v);
    rep(i, e) {
        int s, t, d; cin >> s >> t >> d;
        G[s].push_back(P(d, t)); // {距離, to頂点}の順で保持
    }

    // Pを保持する昇順の優先度付きキューを作成
    // 始点からつながる頂点に対し、距離が短い辺から順に走査していく
    // ∵ すでに最短経路が確定している頂点vについて、vからの距離が
    //    最短の頂点nvについて考えると、vを経由するよりも短い経路が
    //    存在しないので、最短経路（s=>..=>v=>nv）が確定できる
    priority_queue<P, vector<P>, greater<P>> que;
    vector<int> d(v, INF);
    que.push(P(0, r));
    d[r] = 0;

    while (!que.empty()) {
        // P p として queの先頭の{距離, 頂点}を取得
        P p = que.top(); que.pop();
        int v = p.second;
        // 頂点vからつながるnvについて走査
        for (const auto& nv: G[v]) {
            // 始点=>vまでの距離 + v=>nvの距離 と、d[nv] の大きさを比較する
            // もしd[nv]のほうが小さければ、別により短い経路があるので探索打ち切り
            if (d[v] + nv.first > d[nv.second]) continue;
            else {
                d[nv.second] = d[v] + nv.first;
                que.push(nv);
            }
        }
    }

    rep(i, v) {
        if (d[i]!=INF) cout << d[i] << endl;
        else cout << "INF" << endl;
    }
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
static const ll INF = 100000000000000;
struct Node {
  int id;
  ll cost;
  Node() {}
  Node(int id, ll cost) : id(id), cost(cost){}
  bool operator< (const Node& node) const {
    return node.cost < cost;
  } 
};

// N: 頂点数, E: 辺の数, d: 距離 を格納する配列, 
// t: 始点, flag: true なら　無向辺, false なら 有向辺
void dijkstra(int N, int E, ll d[], int t, int from[], int to[], ll cost[], bool flag) {
  static const int WHITE = 0;
  static const int GRAY = 1;
  static const int BLACK = 2;

  int color[N];
  vector<Node> adj[N];
  for (int i = 0; i < N; i++) {
    d[i] = INF;
    color[i] = WHITE;
  }
  // 隣接リストの作成
  for (int i = 0; i < E; i++) {
    adj[from[i]].push_back(Node(to[i], cost[i]));
    if (flag) adj[to[i]].push_back(Node(from[i], cost[i]));
  }
  priority_queue<Node> pq;
  d[t] = 0;
  pq.push(Node(t, 0));
  while (!pq.empty()) {
    Node f = pq.top();
    pq.pop();
    int u = f.id;
    color[u] = BLACK;
    if (d[u] < f.cost) continue;
    for (int j = 0; j < adj[u].size(); j++) {
      int v = adj[u][j].id;
      if (color[v] == BLACK) continue;
      if (d[v] > d[u] + adj[u][j].cost) {
        d[v] = d[u] + adj[u][j].cost;
        pq.push(Node(v, d[v]));
        color[v] = GRAY;
      }
    }
  }
}
int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  int V, E, r;
  cin >> V >> E >> r;
  int s[E], t[E];
  ll d[E];
  for (int i = 0; i < E; i++) {
    cin >> s[i] >> t[i] >> d[i];
  }
  ll ans[V];
  dijkstra(V, E, ans, r, s, t, d, false);
  for (ll i : ans) {
    if (i == INF) {
      cout << "INF\n";
    } else {
      cout << i << "\n";
    }
  }
  return 0;
}

