	}
	for (int i = 0;i < n;i++) {
		for (int k = 0;k < n;k++) {
			for (int j = 0;j <= w;j++) {
				if (j - ww[k] < 0) {
					W[i + 1][j] = W[i][j];
				}
				if (j - ww[i] >= 0) {
					W[i + 1][j] = max(W[i][j], W[i][j - ww[k]] + v[k]);

				}
			}
		}
	}
	return W[n][w];
}
int knapsack2(int w, int n, int* v, int* ww) {
	int W[101];
	for (int j = 0;j <= w;j++) {
		W[j] = 0;
	}
	for (int i = 0;i < n;i++) {
		for (int j = 0;j <= w;j++) {
			if (j - ww[i] >= 0) {
				W[j] = max(W[j], W[j - ww[i]] + v[i]);
			}
		}
	}
	return W[w];
}
