int showmin(vector<int>& D,int* cur)
{
  int minD = D[0];
  *cur = 0;
  for(int i = 0;i < D.size();++i){
    *cur = minD > D[i]? i:*cur;
    minD = min(minD,D[i]);
  }
  return minD;
}
bool finishjudge(vector<int>& finish,vector<int>& check)
{
  for(int i = 0;i < finish.size();++i)
    if(finish[i] == 0 && check[i] == 1)
      return true;
  return false;
}
int main()
{
  int V,E,r,cur,curD,dij,dijD;
  cin >> V >> E >> r;
  vector<int> s(E),t(E),d(E),answer(V),check(V,0);
  vector< vector< pair<int,int> > > v(V);
  for(int i = 0;i < E;++i){
    cin >> s[i] >> t[i] >> d[i];
    v[s[i]].push_back(make_pair(d[i],t[i]));
  }
  check[r] = 1;
  queue<int> q;
  q.push(r);
  while(!q.empty()){
    for(int i = 0;i < v[q.front()].size();++i)
      if(check[v[q.front()][i].second] == 0){
	check[v[q.front()][i].second] = 1;
	q.push(v[q.front()][i].second);
      }
    q.pop();
  }
  vector<int> D(V,1000000000),finish(V,0);
  D[r] = 0;
  while(finishjudge(finish,check)){
    curD = showmin(D,&cur);
    finish[cur] = 1;
    answer[cur] = curD;
    D[cur] = 1000000000;
    for(int i = 0;i < v[cur].size();++i){
      dijD = v[cur][i].first;
      dij = v[cur][i].second;
      if(finish[dij] == 0) D[dij] = min(curD + dijD,D[dij]); 
    }
  }
  for(int i = 0;i < V;++i){
    if(check[i] == 0) cout << "INF" <<endl;
    else cout << answer[i] << endl;
  }
}

