// グラフクラス
class Graph {
public:
	// エッジ
	struct Edge {
		// 接続先のノード番号
		int node;
		// 移動コスト
		int cost;
	};
	// ノード
	struct Node {
		std::vector<Edge> edges;     // 近隣のエッジ
	};
	// コンストラクタ
	Graph(std::istream& in) {
		// ノード数の読み込み
		int n;
		in >> n;
		// ノード用の配列を初期化
		nodes_.resize(n);
		// エッジ数の読み込み
		int e;
		in >> e;
		// 始点の読み込み
		in >> start_;
		for (int i = 0; i < e; ++i) {
			int s, t, u;
			in >> s >> t >> u;
			Edge edge;
			edge.node = t; edge.cost = u;
			nodes_[s].edges.push_back(edge);
		}

	}
	// ノードを取得
	const Node& operator[] (int index) const {
		return nodes_[index];
	}
	// ノード数を取得
	std::size_t node_count() const {
		return nodes_.size();
	}
	// 始点を取得
	int get_start() const {
		return start_;
	}

private:
	// ノード用配列
	std::vector<Node> nodes_;
	// 始点
	int start_;
};

// パス検索クラス
class PathFinder {
	// 距離とノード番号のペア
	using dist_node = std::pair<float, int>;
public:
	// パス検索
	static std::vector<int> find_path(const Graph& graph, int end) {
		// 最大値
		const auto inf = std::numeric_limits<float>::max();
		// 経路情報
		std::vector<dist_node> dist_nodes(graph.node_count(), { inf, -1 });
		// プライオリティキュー
		std::priority_queue<dist_node, std::vector<dist_node>, std::greater<dist_node>> queue;
		// 開始ノードをキューに登録
		int start = graph.get_start();
		dist_nodes[start] = { 0.0f, -1 };
		queue.push({ 0.0f, start });
		// キューにデータがあるか？
		while (!queue.empty()) {
			// 先頭のノードをキューから取り出す
			const auto front = queue.top(); queue.pop();
			const auto front_g = front.first;
			const auto front_node = front.second;
			// ゴールに着いたか？
			if (front_node == end) {
				// コストの作成
				return create_cost(dist_nodes, end);
			}
			// キュー内のデータよりも経路情報の合計距離が小さい？
			if (dist_nodes[front_node].first < front_g) continue; //キュー内のデータは最短距離ではないので無視
																  // 周辺のノードを取得
			for (const auto& node : graph[front_node].edges) {
				// コストを格納
				const auto g = node.cost;
				// 合計距離が小さい場合は最短経路としてキューに登録
				if (dist_nodes[node.node].first > g) {
					// 経路情報を保存
					dist_nodes[node.node] = { g, front_node };
					// キューに登録
					queue.push({ g, node.node });
				}
			}
		}
		// 経路が見つからない場合は空のパスを返す
		return std::vector<int>();
	}
private:
	// コストの計算
	static std::vector<int> create_cost(const std::vector<dist_node>& dist_nodes, int end) {
		std::vector<int> cost;
		for (int node = end; node != -1; node = dist_nodes[node].second) {
			cost.push_back(dist_nodes[node].first);
		}
		return cost;
	}
};

int main() {
	Graph graph(std::cin);
	for (int i = 0; i < graph.node_count(); ++i) {
		auto path = PathFinder::find_path(graph, i);
		int cost = 0;
		if (path.empty()) {
			std::cout << "INF" << std::endl; 
			continue;
		}
		// コストの合計
		while (!path.empty()) {
			cost += path.back();
			path.pop_back();
		}
		std::cout << cost << std::endl;
	}
	return 0;
}

