#define infinity 65535
#define V 100000
#define C 10000
#define E 500000

int i_counter;
struct edge
{
	int t;  //target vertices of i-th edge
	int d;  //the cost of the i-th edge
	int next; //The next edge of the same starting point
};
int minn; //minn represents the min cost of the point to the source point in the set of P
int k;	//k records this point

int v;//v represents the number of vertices
int e;//e represents the number of edges
int	r;//r represents the source of the graph
vector<int> head;  //The location of the edge corresponding to the node in the storage array
vector<edge> edges;  //information of edge

void add_edge(int s, int t, int d);

int main()
{
	while (1)
	{
		cin >> v >> e >> r;
		if (v<1 || v>V || e<0 || e>E || r >= v)
		{
			cin.clear();
		}
		else
			break;
	}
	int i, j;
	vector<int> dis(v, infinity);
	vector<bool> flag(v, false);
	head.resize(v, -1);
	edges.resize(e);
	for (i = 0; i<e; i++) //initialize edges
		edges[i].next = -1;

	int point1, point2, cost;
	i = 1;
	while (1)
	{
		for (; i <= e; i++)
		{
			cin >> point1 >> point2 >> cost;
			if (point1<0 || point1>C || point2<0 || point2>C)
			{
				cin.clear();
				break;
			}
			add_edge(point1, point2, cost);
		}
		if (i>e)
			break;
	}

	dis[r] = 0;
	for (j = head[r]; j >= 0; j = edges[j].next)//initialize the cost of the shortest path
		dis[edges[j].t] = edges[j].d;

	flag[r] = 1;
	for (i = 1; i<v; i++)//There is no comparison between the source and the source point, so the total number of times is less  
	{
		minn = infinity;
		k = 0;
		for (j = 0; j<v; j++)
			if (!flag[j] && minn>dis[j])//The points from the source are compared in turn to get the min cost in P
			{
				minn = dis[j];
				k = j;
			}
		flag[k] = 1;
		for (j = head[k]; j >= 0; j = edges[j].next)	
			if (!flag[edges[j].t] && dis[edges[j].t]>dis[k] + edges[j].d)
				dis[edges[j].t] = dis[k] + edges[j].d;
	}
	for (i = 0; i<v; i++)  //output dis
	{
		if (dis[i]<infinity)
			cout <<dis[i];
		else
			cout << "INF";
	}
	return 0;
}

void add_edge(int s, int t, int d) //add information of edge
{
	edges[i_counter].t = t;
	edges[i_counter].d = d;
	edges[i_counter].next = head[s];
	head[s] = i_counter;
	i_counter++;
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using P = pair<ll, int>;
const ll INF = 1e12;
struct Edge {
	int from, to;
	ll cost;
	Edge() {}
	Edge(int f, int t, ll c) : from(f), to(t), cost(c) {}
};

using Edges = vector<Edge>;
using Graph = vector<Edges>;

vector<ll> Dijkstra(const Graph& G, int s) {
	int n = G.size();
	vector<ll> res(n, INF);
	priority_queue<P, vector<P>, greater<P>> pq;
	pq.emplace(0, s);
	while (!pq.empty()) {
		auto p = pq.top(); pq.pop();
		if (res[p.second] != INF) continue;
		res[p.second] = p.first;
		for (auto e : G[p.second]) {
			if (res[e.to] == INF) {
				pq.emplace(e.cost + p.first, e.to);
			}
		}
	}
	return res;
}

