        G[x].emplace_back(y, d);
    }

    auto dist = dijkstra(G, r);
    for(int i=0; i<N; ++i) {
        if(dist[i] == numeric_limits<long long>::max()) cout << "INF\n";
        else cout << dist[i] << '\n';
    }
}

