  int d[vertex_num + 1];
  bool used[vertex_num + 1];

  for(int i = 0; i < vertex_num; i++) {
    d[i] = INF;
    used[i] = false;

    for(int j = 0; j < vertex_num; j++) {
      cost[i][j] = INF;
