int main()
{
    int n_vertices, n_edges, source_node;
    cin >> n_vertices >> n_edges >> source_node;
    vector< vector<Edge> > adjlist(n_vertices);

    for (int i = 0; i < n_edges; ++i) {
        int source, target, distance;
