	bool operator<(const Node &other) const {return weight < other.weight;}
	bool operator>(const Node &other) const {return other.weight > weight;}
	bool operator==(const Node &other) const {return weight == other.weight;}
	bool operator<=(const Node &other) const {return weight >= other.weight;}
