    G[s].push_back(edge_v);
  }

  vector<lint> path = dijkstra(G,r);

  for (int i = 0; i < V; i++)
  {
    if(path[i] != I64_MAX)
    cout<<path[i]<<endl;
    else
    cout<<"INF"<<endl;

  }



  return;
}

