			pair<ll, int> p = pqa.top(); pqa.pop();
			int u = p.second;
			if(dist[u] < p.first) continue;
			for(int v = 0; v < adj[u].size(); v++){
				edge e = adj[u][v];
				if(dist[e.to] > dist[u] + e.cost){
					dist[e.to] = dist[u] + e.cost;
					pqa.push(make_pair(dist[e.to], e.to));
				}
			}
		}
