struct Edge {
    int to;
    int cost;
    Edge(int t, int c) : to(t), cost(c) {}
};

struct Node {
    int v;
    int d;
    Node(int vv, int dd) : v(vv), d(dd) {}
};

struct NodeGreater {
    bool operator()(Node lhs, Node rhs) const
    {
        return lhs.d > rhs.d;
    }
};

constexpr int INF = numeric_limits<int>::max();

int V;
int E;
int r;
vector<vector<Edge>> G;

void dijkstra(int start, vector<int>& d)
{
    deque<bool> done(V, false);
    priority_queue<Node, vector<Node>, NodeGreater> que;

    d.resize(V);
    fill(begin(d), end(d), INF);
    d[start] = 0;
    que.push(Node(start, 0));

    int n_remain = V;
    while(!que.empty()) {
        Node nodemin = que.top(); que.pop();
        int vmin = nodemin.v;
        int dmin = nodemin.d;

        if(d[vmin] < dmin) continue;

        done[vmin] = true;
        if(--n_remain == 0) break;

        for(Edge e : G[vmin]) {
            if(done[e.to]) continue;
            int d_new = dmin + e.cost;
            if(d_new < d[e.to]) {
                d[e.to] = d_new;
                que.emplace(e.to, d_new);
            }
        }
    }
}

void solve()
{
    vector<int> d(V);
    dijkstra(r, d);

    REP(i, V) {
        if(d[i] == INF) {
            cout << "INF" << "\n";
        }
        else {
            cout << d[i] << "\n";
        }
    }
}

int main()
{
    cin >> V >> E >> r;
    G.resize(V);

    REP(_, E) {
        int s, t, d;
        cin >> s >> t >> d;
        G[s].emplace_back(t, d);
    }

    solve();

    return 0;
}

