		nodes_.resize(n);
		// エッジ数の読み込み
		int e;
		in >> e;
		// 始点の読み込み
		in >> start_;
		for (int i = 0; i < e; ++i) {
			int s, t, u;
			in >> s >> t >> u;
			Edge edge;
			edge.node = t; edge.cost = u;
			nodes_[s].edges.push_back(edge);
		}

	}
	// ノードを取得
	const Node& operator[] (int index) const {
		return nodes_[index];
	}
	// ノード数を取得
	std::size_t node_count() const {
		return nodes_.size();
	}
