using namespace std;
#define _N 100010
class priorityQueue{
    private:
        struct Node{int id,key,degree;struct Node *p,*l,*r;};
        Node *ids[_N];
        Node head;

    public:
        priorityQueue(){
            head.l = head.r = head.p = NULL;
        }
        void father(Node *f, Node *s){
            s->p = f;
            s->r = f->l;
            f->l = s;
            f->degree++;
        }
        void unionTree(Node *adds){
            Node *p  = &head;
            Node *p1 = head.r;
            Node *p2 = adds;
            while(p1!=NULL || p2!=NULL){
                if(p1!=NULL && p2!=NULL){
                    if(p1->degree < p2->degree)
                        {p->r = p1; p1 = p1->r;}
                    else
                        {p->r = p2; p2 = p2->r;}
                }else if(p1!=NULL) {p->r = p1; break;}
                else {p->r = p2; break;}
                p = p->r;
            }
            p  = &head;
            p1 = head.r;
            p2 = p1->r;
            while(p2!=NULL){
                if(p1->degree==p2->degree
                   &&(p2->r==NULL || p2->r->degree!=p2->degree)){
                    if(p1->key < p2->key){
                        p1->r = p2->r;
                        father(p1, p2);
                        p2 = p1->r;
                        continue;
                    }else{
                        father(p2, p1);
                        p->r = p2;
                        p1 = p2;
                        p2 = p2->r;
                        continue;
                    }
                }
                p  = p1;
                p1 = p2;
                p2 = p2->r;
            }
        }
        void push(int id, int key){
            Node *t = (Node *)malloc(sizeof(Node));
            t->id = id;
            t->key = key;
            t->degree = 0;
            t->l = t->p = t->r = NULL;
            ids[id] = t;
            unionTree(t);
        }
        bool empty(){
            return head.r==NULL;
        }
        int extractMin(){
            Node *cur = head.r;
            Node *pre = &head;
            Node *t = pre;
            while(cur!=NULL){
                if(cur->key < t->r->key)
                    t = pre;
                pre = pre->r;
                cur = cur->r;
            }
            int ans = t->r->id;
            Node *p = t->r->l;
            t->r = t->r->r;
            if(p!=NULL){
                t = p->r;
                p->p = p->r = NULL;
                Node *adds = p;
                while(t!=NULL){
                    p = t;
                    t = t->r;
                    p->p = NULL;
                    p->r = adds;
                    adds = p;
                }
                unionTree(adds);
            }
            return ans;
        }
        void decreaseKey(int id, int key){
            Node *p = ids[id];
            p->key = key;
            while(p->p!=NULL && p->p->key > p->key){
                int tid  = p->id;
                int tkey = p->key;
                p->id  = p->p->id;
                p->key = p->p->key;
                p->p->id = tid;
                p->p->key = tkey;
                ids[p->id] = p;
                ids[p->p->id] = p->p;
                p = p->p;
            }
        }
};



const int N = 100010;
const int M = 500010;
const long INF = 200000000;
struct Node{int v,w,nt;};
int heads[N],path[N],len;
Node nodes[M];

void insertEdge(int u, int v, int w){
    nodes[len].v = v;
    nodes[len].w = w;
    nodes[len].nt = heads[u];
    heads[u] = len++;
}

void getGraph(int n, int m){
    len = 0;
    for(int i=0; i<n; i++) heads[i] = -1;
    //build graph
    int u,v,w;
    while(m--){
        scanf("%d%d%d",&u,&v,&w);
        insertEdge(u,v,w);
        //insertEdge(v,u,w);
    }
}
int dist[N];
void dijkstra(int n,int s){
    //initialize
    priorityQueue q;
    for(int i=0; i<n; i++) dist[i] = INF;
    dist[s] = 0;
    path[s] = s;
    q.push(s, 0);
    //work
    while(!q.empty()){
        int x = q.extractMin();
        int p = heads[x];
        while(p!=-1){
            Node y = nodes[p];
            if(dist[x]+y.w<dist[y.v]){
                if(dist[y.v]==INF) q.push(y.v, dist[x]+y.w);
                else q.decreaseKey(y.v, dist[x]+y.w);
                dist[y.v] = dist[x]+y.w;
                path[y.v] = x;
            }
            p = y.nt;
        }
    }
}

int main(){
    int n,m,r;
    scanf("%d%d%d",&n,&m,&r);
    getGraph(n,m);
    dijkstra(n,r);
    for(int i=0; i<n; i++)
        if(dist[i]==INF)printf("INF\n");
        else printf("%d\n",dist[i]);
    return 0;
}

