	vector<ll> res(n,INF);
	priority_queue<P,vector<P>,greater<P> > que;
	que.push(P(0,r));
	res[r]=0;
	while(!que.empty()){
		P x = que.top();que.pop();
		for(int i = 0; i < g[x.second].size(); i++){
			if(res[g[x.second][i].second] > x.first + g[x.second][i].first){
				res[g[x.second][i].second] = x.first + g[x.second][i].first;
