class RadixHeap32 {
	using uint32 = std::uint_fast32_t;
	using P = std::pair<uint32, uint32>;
	uint32 bsr(const uint32 x) {
		if (!x)
			return 0;
#ifdef __GNUC__
		return 32 - __builtin_clz(x);
#else
		uint32 t = 16;
		for (uint32 i = 3; ~i; --i) {
			if (x & ~(((uint32)1 << t) - 1)) {
				t += (uint32)1 << i;
			}
			else {
				t -= (uint32)1 << i;
			}
		}
		if (x & ~(((uint32)1 << t) - 1))
			++t;
		return t;
#endif
	}
	std::vector<P> v[33];
	uint32 last, size;

public:
	RadixHeap32() : last(0), size(0) {}
	P pop() {
		assert(size);
		--size;
		if (v[0].empty()) {
			uint32 i = 1;
			while (v[i].empty())
				++i;
			last = v[i][0].first;
			for (uint32 j = 1; j < v[i].size(); ++j)
				last = std::min(last, v[i][j].first);
			for (uint32 j = 0; j < v[i].size(); ++j)
				v[bsr(last ^ v[i][j].first)].push_back(v[i][j]);
			v[i].erase(v[i].begin(), v[i].end());
		}
		P ret = v[0].back();
		v[0].pop_back();
		return ret;
	}
	void push(const P &x) {
		assert(last <= x.first);
		++size;
		v[bsr(x.first ^ last)].push_back(x);
	}
	bool empty() { return !size; }
};
