vector<ll> dijkstra(int n, vector<vector<PL>>& G,int& s) {
    vector<ll> dist(n,INF);
    dist[s] = 0;

    priority_queue<PL,vector<PL>,greater<P>> q;
    q.push({0,s});

    while (!q.empty()) {
