void Dijkstra(int f,int V, int c[], bool u[],int d[]){
  fill(d, d+V, INF);
  fill(u, u+V, false);
  d[f] = 0;
  while(true){
    int v = -1;
    REP(i,V){
      if(!u[i] && (v == -1 || d[i] < d[v])){
	v = i;
      }
    }
    if(v == -1){
      break;
    }
    u[v] = true;
    REP(i,V){
      d[i] = min(d[i], d[v] + c[v*V+i]);
    }
  }
}

