vll dijkstra(int s,Graph G){
    priority_queue<P, vector<P>, greater<P> > Q;
    vll ret(V,LINF);
    ret[s] = 0;
    Q.push(P(0,s));

    while(!Q.empty()){
        P p = Q.top();Q.pop();
        int v = p.second;
        for(Edge e: G[v]){
