    int s,t,d;
    cin>>s>>t>>d;
    adj_list.at(s).push_back(make_pair(t,d));

  }

  vector<int> distance=Dijkstra(adj_list,r);
  REP(i,V){
    if(distance.at(i)==INF){
      cout<<"INF"<<endl;
    }else{
      cout<<distance.at(i)<<endl;
    }
  }


  return 0;
}

