using namespace std;
#define _N 100010
class priorityQueue{
    private:
        struct Node{int id,key;};
        int ids[_N];
        Node heap[_N*2];
        int size;

    public:
        priorityQueue(){
            size = 1;
        }
        void up(int t){
            while(t!=1 && heap[t].key<heap[t/2].key){
                Node tmp = heap[t/2];
                heap[t/2] = heap[t];
                heap[t] = tmp;
                ids[heap[t/2].id] = t/2;
                ids[heap[t].id] = t;
                t>>=1;
            }
        }
        void down(int t){
            while(1){
                int cur = 0;
                if(t*2<size && t*2+1<size){
                    if(heap[t*2].key<heap[t].key)
                        cur = t*2;
                    if(heap[t*2+1].key<heap[t].key && heap[t*2+1].key<heap[t*2].key)
                        cur = t*2+1;
                }else if(t*2<size){
                    if(heap[t*2].key<heap[t].key)
                        cur = t*2;
                }
                if(cur==0)break;
                Node tmp = heap[cur];
                heap[cur] = heap[t];
                heap[t] = tmp;
                ids[heap[cur].id] = cur;
                ids[heap[t].id] = t;
                t = cur;
            }
        }
        void push(int id, int key){
            heap[size].id = id;
            heap[size].key = key;
            ids[id] = size;
            up(size);
            size++;
        }
        bool empty(){
            return size==1;
        }
        int extractMin(){
            int ans = heap[1].id;
            heap[1] = heap[--size];
            down(1);
            return ans;
        }
        void decreaseKey(int id, int key){
            heap[ids[id]].key = key;
            up(ids[id]);
        }
};

const int N = 100010;
const int M = 500010;
const long INF = 200000000;
struct Node{int v,w,nt;};
int heads[N],path[N],len;
Node nodes[M];

void insertEdge(int u, int v, int w){
    nodes[len].v = v;
    nodes[len].w = w;
    nodes[len].nt = heads[u];
    heads[u] = len++;
}

void getGraph(int n, int m){
    len = 0;
    for(int i=0; i<n; i++) heads[i] = -1;
    //build graph
    int u,v,w;
    while(m--){
        scanf("%d%d%d",&u,&v,&w);
        insertEdge(u,v,w);
        //insertEdge(v,u,w);
    }
}
int dist[N];
void dijkstra(int n,int s){
    //initialize
    priorityQueue q;
    for(int i=0; i<n; i++) dist[i] = INF;
    dist[s] = 0;
    path[s] = s;
    q.push(s, 0);
    //work
    while(!q.empty()){
        int x = q.extractMin();
        int p = heads[x];
        while(p!=-1){
            Node y = nodes[p];
            if(dist[x]+y.w<dist[y.v]){
                if(dist[y.v]==INF) q.push(y.v, dist[x]+y.w);
                else q.decreaseKey(y.v, dist[x]+y.w);
                dist[y.v] = dist[x]+y.w;
                path[y.v] = x;
            }
            p = y.nt;
        }
    }
}

