int main(void) {
    int V, E, r; // vertices, edges, start
    cin >> V >> E >> r;

    edges.resize(V, vector<Elem>());

    for (int i = 0; i < E; i++) {
        int s, t, d;
        cin >> s >> t >> d;
        edges[s].push_back({t, d});
    }

    Graph g(V, E, edges);
    g.dijkstra(r);

    for (int i = 0; i < V; i++) {
        if (g.d_list[i] != INF) {
            cout << g.d_list[i] << endl;
        } else {
            cout << "INF" << endl;
        }
    }

    return 0;
}

