template<typename T>
struct Q002 {
   Int v;
   std::vector<std::vector<std::tuple<Int, T>>> graph;
   Q002(Int v_) : v(v_), graph(v) {}
   void set(Int a, Int b, T c) {
      graph[a].emplace_back(b, c);
   }
   const std::vector<std::tuple<Int, T>>& nexts(Int a) const {
      return graph[a];
   }
};

template<typename T>
struct F002 {
   std::tuple<std::vector<T>, std::vector<bool>> operator()(const Q002<T>& graph, Int begin) const {
      Int v = graph.v;
      std::vector<bool> checked(v, false);
      std::vector<T> xs(v);
      std::priority_queue<std::tuple<T, Int>, std::vector<std::tuple<T, Int>>, std::greater<std::tuple<T, Int>>> q;
      q.push(std::make_tuple(0, begin));
      xs[begin] = 0;
      checked[begin] = true;
      while( not q.empty() ) {
         Int i; T d;
         std::tie(d, i) = q.top(); q.pop();
         dumpll(i, d);
         for(auto kc : graph.nexts(i)) {
            Int k; T c;
            std::tie(k, c) = kc;
            T nd = d + c;
            if( not checked[k] or nd < xs[k] ) {
               xs[k] = nd;
               dumpl(nd);
               checked[k] = true;
               q.push(std::make_tuple(nd, k));
            }
         }
      }
      return std::make_tuple(xs, checked);
   }
};

