      Q002<Int> graph(v);
      for(Int i = 0; i < e; ++i) {
         Int a, b, c; scan(a, b, c);
         graph.set(a, b, c);
      }
      F002<Int> dijkstra;
      std::vector<Int> dists;
      std::vector<bool> checked;
      std::tie(dists, checked) = dijkstra(graph, r);
      for(Int i = 0; i < v; ++i) {
         if( not checked[i] ) puts("INF");
         else printf("%ld\n", dists[i]);
      }
   }
};

