template<typename TWeight = int>
class Network {
public:
  Network() {}
  std::vector< std::tuple<int, TWeight> > *edges;
  int v;
};

template<typename TWeight = int>
Network<TWeight> initNetwork(int v) {
  Network<TWeight> network;
  network.edges = new std::vector< std::tuple<int, TWeight> > [v + 3];
  network.v     = v + 3;
  return network;
}

template<typename TWeight = int>
void deleteNetwork(Network<TWeight> network) {
  if( network.edges == nullptr ) {
    delete [] network.edges;
  }
}

template<typename TWeight = int>
void addEdge(int from, int to, TWeight weight) {
  auto *network = (Network<TWeight>*)hidden::pstack.top();
  network->edges[from].push_back(std::make_tuple(to, weight));
}

template<typename TWeight = int>
std::vector<TWeight> dijkstra(Network<TWeight> network, int source) {
  std::vector<TWeight> res(network.v, INF);
  res[source] = 0;
  std::priority_queue< std::tuple<TWeight, int> > q;
  q.push(std::make_tuple(0, source));
  while( not q.empty() ) {
    TWeight dist; int id;
    std::tie(dist, id) = q.top(); q.pop();
    dist = -dist;
    for(auto edge : network.edges[id]) {
      int next; TWeight weight;
      std::tie(next, weight) = edge;
      auto nextdist = dist + weight;
      if( nextdist >= res[next] ) continue;
      res[next] = nextdist;
      q.push(std::make_tuple(-nextdist, next));
    }
  }
  return res;
}

int main() {
  int v, e, r;
  scanf("%d %d %d", &v, &e, &r);
  auto network = initNetwork<long>(v);
