  for(int i = 0; i < e; ++i) {
    int s, t; long d;
    scanf("%d %d %ld", &s, &t, &d);
    addEdge(s, t, d);
  }
  pop();
  auto dists = dijkstra(network, r);
  for(int i = 0; i < v; ++i) {
    if( dists[i] != INF ) {
      printf("%ld\n", dists[i]);
    }
    else {
      puts("INF");
    }
  }
}

