      if(!used[u] && (v==-1 || dist[u]<dist[v]))
	v=u;
    }

    if(v==-1){
      break;
    }

    used[v] = true;

    for(int u=0;u<V;u++){
      dist[u]=min(dist[u],dist[v]+cost[v][u]);
    }
  }

  for(int i=0;i<V;i++){
    if(dist[i] == INF){
      cout<<"INF"<<endl;
    }else{
      cout<<dist[i]<<endl;
    }
  }
  return 0;
}

