   * @param e 辺数
   * @param r 開始点
   */
  int v;
  int e0;
  int s;

  scanf("%d %d %d", &v, &e0, &s);
  // 頂点の数でメモリを確保

  /**
   * @param from 始点
   */
  int from;

  vector<vector<edge> > vec(v);

  REP (i, e0) {
    edge edge;
    scanf("%d %d %d", &from, &edge.to, &edge.cost);
    // 隣接リストの作成
    vec[from].push_back(edge);
  }

  // 開始点からの距離
  int dist[v];
  REP (i, v) dist[i] = INF;
  // 開始点の初期化
  dist[s] = {0};
  // 探索済みかどうか
  //bool done[v] = false;

