  priority_queue<p, vector<p>, greater<p> > pq;
  // スタート地点はコスト0としてキューに追加
  pq.push(make_pair(0, s));

  // ここからダイクストラ
  while (!pq.empty()) {
    int cost = pq.top().first;
    int vertex = pq.top().second;
    pq.pop();

    // キューから取り出された頂点の隣接リストを走査する
    REP (i, (int)vec[vertex].size()) {
