        adjlist[a].push_back(make_pair(c, b));
        //adjlist[b].push_back(make_pair(c, a));      
    }

    vector<int> result(V);
    result = dijk(S, V, adjlist);
    //cout << result[G] << endl;

    for(int i = 0; i < V; i++){
        if(result[i] == INF) cout << "INF" << endl;
        else cout << result[i] << endl;
    }
    return 0;
}

