template<class T>
struct d_heap {
  int d;
  vector<T> heap;

  d_heap(int d): d(d) {}
  void push(const T& t) {
    heap.push_back(t);

    int i = heap.size() - 1;
    while(i > 0){
      if(heap[(i - 1) / 2] > heap[i]) swap(heap[(i - 1) / 2], heap[i]);
      i = (i - 1) / 2;
    }
  }

  T pop() {
    T ans = heap[0];
    swap(heap.back(), heap.front());
    heap.pop_back();
    for(int i = 1;i < heap.size() && i <= d;i++) {
      if(heap[0] > heap[i]) swap(heap[0], heap[i]);
    }
    return ans;
  }

  bool empty() const {
    return heap.empty();
  }

  T top() {
    return heap[0];
  }
};
