                que.push(make_pair(d.at(e.to), e.to));
            }
        }
    }

    for (auto &x : d) {
        if (x == INT_MAX) {
            cout << "INF" << endl;
        } else {
            cout << x << endl;
        }
    }

    return 0;
}

