        graph[s].push_back(make_pair(t, w));
    }

    // 3. 単一始点最短経路の重み計算.
    bfs();

    // 4. 出力.
    for(int i = 0; i < V; ++i){
        if(dist[i] < INF) printf("%lld\n", dist[i]);
        else              printf("%s\n", "INF");
    }
    return 0;

}

