    while(not que.empty()){
        State now = que.top(); que.pop();
        for(Edge e : G[now.index]){
            if(dist[e.to] > now.cost + e.cost){
                State nxt = State(e.to, now.cost + e.cost);
                dist[e.to] = nxt.cost;                
                que.push(nxt);
            }
        }
    }
    return dist;
}
