	REP(i,Q){
		auto u=in(),v=in(),w=in();
		connect.AddDirectionalConnection(u,v,w);
	}
	Dijkstra di;
	di.CalcShortestPath(R,connect);
	REP(i,N){
		if(di.GetDistance(i)>=(1LL<<60)){
			out("INF");
		}
		else{
			out(di.GetDistance(i));
		}
	}
	return 0;
}

