lli dis[100500];

void dijkstra(lli r) {
    for(lli i=0; i<sizeof(dis)/sizeof(lli); i++)
        dis[i] = 0xFFFFFF;

    priority_queue<P, vector<P>, greater<P> > q;
    q.push(P(0,r));
    while(!q.empty()) {
        lli cost = q.top().first;
        lli now = q.top().second;
        q.pop();

        if(dis[now] <= cost)
            continue;
        dis[now] = cost;
        for(vector<P>::iterator it = G[now].begin(); it != G[now].end(); it++)
            q.push(P(cost+it->second,it->first));
    }
}

