#include <iostream>
#include <cstdio>
#include <algorithm>
#include <queue>
#include <map>
using namespace std;

int V, E, r, s, t, d;

map<int,int> edges[100010]; // 隣接行列が使えれば最高だがそうもいかないのでこうしてみる。標準ライブラリからよさそうなものを選んだ。

long long infty = 10000*100000+100; // ゆえにC[]はlong longを入れる。
priority_queue< pair<long long,int> > Q; // firstは上限の-1倍。secondは都市。
long long C[100010]; // 確定したらQから出し、答えはここに入れる。

int main() {
  // 入力
  scanf("%d%d%d", &V, &E, &r);
  for (int i=0; i<E; i++) {
    scanf("%d%d%d", &s, &t, &d);
    edges[s][t] = d;
    // cerr << "edges[" << s << "][" << t << "] = " <<  edges[s][t] << endl;
  }
  // 優先度付きキューに初期状態を入れる。
  for (int i=0; i<V; i++) {
    if (i == r) {
      Q.push(make_pair(0, i));
    } else {
      Q.push(make_pair(-1 * infty, i));
    }
  }
  // Dijkstra法。
  while(!Q.empty()) {
    int u = Q.top().second; // 最小コスト確定
    C[u] = -1 * Q.top().first; // 最小コスト記録
    Q.pop(); // Qからは出す。
    priority_queue< pair<long long,int> > tempQ; 
    while(Q.size() > 0) {
      int v = Q.top().second;
      int tempC = -1 * Q.top().first;
      Q.pop();
      if (edges[u].find(v) != edges[u].end() && tempC > edges[u][v] + C[u]) {
	tempC =  edges[u][v] + C[u];
	// cerr << tempC << endl;
      }
      tempQ.push(make_pair(-1 * tempC, v));
    }
    Q = tempQ;
  }
  // 答えの出力。
  for (int i=0; i<V; i++) {
    if (C[i] < infty) {
      printf("%lld\n", C[i]);
    } else {
      printf("INF\n");
    }
  }
}

