#include<utility>

const long long INF=0xfffffffe;
const int FIRSTALLOCATE=100000;
typedef std::pair<int,int> P;

struct nodes{
		int number;
		long long cost;
		std::vector<P> edge;
};
std::vector<nodes> node(FIRSTALLOCATE);
bool operator>(const nodes *node_a,const nodes *node_b){
	return node_a.cost>node_b.cost;
}
std::priority_queue<nodes*,std::vector<nodes*>,std::greater<nodes*>  >pq;
int v,e,r;

void initialize(void){
	for(int lp1=0;lp1<FIRSTALLOCATE;lp1++){
		node[lp1].cost=INF;
		node[lp1].number=lp1;
	}
}

void input(void){
	int m1,m2,m3;
	std::cin>>v>>e>>r;
	for(int lp=0;lp<e;lp++){
		scanf("%d%d%d",&m1,&m2,&m3);
		m1--; m2--;
		node[m1].edge.push_back(std::make_pair(m2,m3));
		node[m2].edge.push_back(std::make_pair(m1,m3));
	}
}

void solve(void){
	node[r].cost=0;
	pq.push(&node[r]);
	while(!pq.empty()){
		nodes* node_now=pq.top();
		pq.pop();
		for(auto x:node_now->edge){
			nodes* node_next=&node[x.first];
			int node_next_cost=x.second+node_now->cost;
			if(node_next_cost<node_next->cost){
				node_next->cost=node_next_cost;
				pq.push(node_next);
			}
		}
	}
}

void output(void){
	for(int lp=0;lp<v;lp++){
		if(node[lp].cost==INF){
			printf("INF\n");
		}else{
			printf("%lld\n",node[lp].cost);
		}
	}
}

int main(void){
	initialize();
	input();
	solve();
	output();
	return 0;
}

