template<typename W_>
struct Solver5 {
   using W = W_;
   struct Edge {
      Edge(Int src_, Int dest_, W cost_)
         : src(src_), dest(dest_), cost(cost_) {}
      Int src, dest;
      W cost;
   };
   Int n;
   std::vector<std::vector<Edge>> fss;
   Solver5(Int n_)
      : n(n_+1), fss(n) {}
   void addEdge(Int src, Int dest, W cost) {
      fss[src].emplace_back(src, dest, cost);
   }
   const std::vector<Edge>& forwardEdges(Int v) const {
      return fss[v];
   }
};

struct Solver4 {
   template<typename T> std::vector<std::tuple<bool, typename T::W>> solve(const T& graph, Int begin) const {
      using W = typename T::W;
      using WI = std::tuple<W, Int>;
      Int n = graph.n;
      std::vector<std::tuple<bool, W>> xs(n, std::make_tuple(false, 0));
      std::priority_queue<WI, std::vector<WI>, std::greater<WI>> q;
      q.push(std::make_tuple(0, begin));
      xs[begin] = std::make_tuple(true, 0);
      while( not q.empty() ) {
         W d; Int i; std::tie(d, i) = q.top(); q.pop();
         for(auto kc : graph.forwardEdges(i)) {
            Int k = kc.dest; W c = kc.cost;
            W nd = d + c;
            bool b; W td; std::tie(b, td) = xs[k];
            if( not b or nd < td ) {
               xs[k] = std::make_tuple(true, nd);
               q.push(std::make_tuple(nd, k));
            }
         }
      }
      return xs;
   }
};


struct Solver {
   Solver() { fprintf(stderr, "--------Solver begin--------\n"); }
   ~Solver() { fprintf(stderr, "--------Solver end--------\n"); }
   void solve() {
      Int v, e, r; scan(v, e, r);
      Solver5<Int> graph(v);
      for(Int i = 0; i < e; ++i) {
         Int a, b, c; scan(a, b, c);
         graph.addEdge(a, b, c);
      }
      Solver4 dijkstra;
      auto xs = dijkstra.solve(graph, r);
      for(Int i = 0; i < v; ++i) {
         bool f; Int w; std::tie(f, w) = xs[i];
         if( not f ) {
            puts("INF");
         }
         else {
            printf("%ld\n", w);
         }
      }
   }
};

int main() {
   loop std::unique_ptr<Solver>(new Solver())->solve();
}

