    for(int i = 0; i < m; i++){
        int s, t, c;
        cin >> s >> t >> c;
        E[s].push_back(P(t, c));
    }
    dijkstra();
    for(int i = 0; i < n; i++)
        cout << (d[i] == INT_MAX ? "INF" : to_string(d[i])) << endl;

    return 0;
}

