priority_queue<P,vector<P>,greater<P> > q;

int V,E,r;
int d[100000];

int main(){
  scanf("%d %d %d",&V,&E,&r);
  for(int i=0;i<E;i++){
    int s;
    edge e;
    scanf("%d %d %d",&s,&e.to,&e.cost);
    G[s].push_back(e);
  }
  fill(d,d+V,INF);
  d[r] = 0;
  q.push(P(0,r));
  while(!q.empty()){
    P p = q.top();
    q.pop();
    if(d[p.second]<p.first) continue;
    int v = p.second;
