    cin >> s >> t >> d;
    graph.addEdge((Edge){s, t, d});
  }
  ShortestPath<Edge> shortestPath = graph;
  shortestPath.run(r);
  for (int c : shortestPath.dist) {
    if (c != shortestPath.INF) cout << c << endl;
    else cout << "INF" << endl;
  }
}

