  }
  bellman_ford<int> bf(n, r, edg);
  auto inf = bf.inf; auto res = bf.result();
  for (auto const& x : res) {
    if (x == inf) cout << "INF" << '\n';
    else cout << x << '\n';
  }
  cout << flush;
  return 0;
}

