class AdjList {
  vector<vector<int>> g;

public:
  AdjList(const int &n, const vector<int> &src) : g(n) {
    int m = src.size();
    rep(i, m) g[src[i]].emplace_back(i);
  }

  int size() const { return g.size(); }
  const vector<int> &operator[](const int &i) const { return g[i]; }
  auto begin() { return g.begin(); }
  auto begin() const { return g.begin(); }
  auto end() { return g.end(); }
  auto end() const { return g.end(); }
};

template<typename Weight> class Dijkstra {
  int s;
  vector<int> src, dst;
  vector<Weight> weight;

  AdjList g;
  vector<Weight> dist;
  vector<int> prev;

public:
  Dijkstra(const int &n,
           const vector<int> &src,
           const vector<int> &dst,
           const vector<Weight> &weight,
           const int &s,
           const Weight &inf = numeric_limits<Weight>::max() / 8) //
      : src(src), dst(dst), weight(weight), g(n, src), s(s), dist(n, inf), prev(n) {
    using state = pair<Weight, int>;
    priority_queue<state, vector<state>, greater<state>> q;
    dist[s] = 0;
    q.emplace(0, s);
    while (q.size()) {
      Weight d;
      int v;
      tie(d, v) = q.top();
      q.pop();
      if (dist[v] < d) continue;
      for (auto &e : g[v]) {
        if (cmin(dist[dst[e]], dist[v] + weight[e])) {
          prev[dst[e]] = v;
          q.emplace(dist[dst[e]], dst[e]);
        }
      }
    }
  }

  Weight shortestDist(const int &v) { return dist[v]; }
};

