  priority_queue<Vertex> Q;
  Q.push({ R, 0 });
  D.at(R) = 0;

  while (Q.size()) {
    auto v = Q.top(); Q.pop();
    for (auto u: G.at(v.id)) {
      Int d = D.at(v.id) + u.d;
      if (D.at(u.id) <= d) continue;
      D.at(u.id) = d;
      Q.push(u);
