// ダイクストラ法
void solve() {
  vll d(v);
  rep(i, v) { d[i] = INF; }
  d[r] = 0;
  // 比較関数（昇順）
  auto comp = [](pll a, pll b) { return a.first > b.first; };
  // ↓pairは(始点からの距離,頂点番号)
  priority_queue<pll, vector<pll>, decltype(comp)> Q{comp};
  vll s(v, 0);                // 確定したら1にする
  Q.push(make_pair(d[r], r)); // 始点を追加
  while (!Q.empty()) {
    ll u = Q.top().second;
    // cout << "u:" << u << endl;
    Q.pop();
    if (s[u] == 0) { // 未確定なら
      rep(i, E[u].size()) {
        ll V = E[u][i].first;
        if (s[V] == 0) { // uと接続する頂点が未確定なら
          d[V] = min(d[V], d[u] + E[u][i].second); // 緩和
          // cout << "d[" << V << "]:" << d[V] << endl;
          Q.push(make_pair(d[V], V));
        }
      }
    }
    s[u] = 1;
  }
  rep(i, v) {
    if (d[i] == INF) {
      cout << "INF" << endl;
    } else {
      cout << d[i] << endl;
    }
  }
}

int main() {
  input();
  solve();
  return 0;
}

