  }

  // node cost / id
  std::priority_queue< std::tuple<long, long> >q;
  dist[r] = 0;
  q.push(std::tuple<long, long>(0, r));
  while( not q.empty() ) {
    long cost, id;
    std::tie(cost, id) = q.top(); q.pop();
    cost = -cost;
    for(int i = 0; i < (int)graph[id].size(); ++i) {
      long next, edgecost;
      std::tie(next, edgecost) = graph[id][i];
      if( dist[next] > cost + edgecost ) {
        dist[next] = cost + edgecost;
        q.push(std::tuple<long, long>(-dist[next], next));
      }
    }
  }

  for(int i = 0; i < V; ++i) {
    if( dist[i] == INF ) {
      puts("INF");
    }
    else {
      printf("%ld\n", dist[i]);
    }
  }

  return 0;
}

