int showmin(vector<int>& D,int* cur)
{
  int minD = D[0];
  *cur = 0;
  for(int i = 0;i < D.size();++i){
    *cur = minD > D[i]? i:*cur;
    minD = min(minD,D[i]);
  }
  return minD;
}
