using namespace std;

struct Node{
    int v;
    int d;
    Node(int v_, int d_){
        v = v_;
        d = d_;
    }
};

bool operator < (const Node& l, const Node& r){
    return l.d > r.d;
}

vector<Node> neighbors(int v, const vector<vector<int> >& graph, vector<int>& vs){
    vector<Node> ns;
    for (int i = 0; i < graph[v].size(); i++) {
        int cost = graph[v][i];
        if (cost == -1) {
            continue;
        }
        int newCost = cost + vs[v];
        if (newCost < vs[i] || vs[i] == -1) {
            vs[i] = newCost;
            ns.push_back(Node(i, newCost));
        }
    }
    return ns;
}


int main (int argc, char* argv[]){
    int V, E, r;
    cin >> V >> E >> r;
    vector<vector<int> > graph(V, vector<int>(V, -1));
    vector<int> vs(V, -1);
    for (int i = 0; i < E; i++) {
        int s, t, d;
        cin >> s >> t >> d;
        graph[s][t] = d;
    }

    priority_queue<Node> q;
    q.push(Node(r, 0));
    vs[r] = 0;

    while (!q.empty()) {
        Node next = q.top();
        q.pop();
        vector<Node> ns = neighbors(next.v, graph, vs);
        for (auto n : ns) {
            q.push(n);
        }
    }

    for (int d: vs) {
        if (d == -1) {
            cout << "INF" << endl;
        }else{
            cout << d << endl;
        }
    }

	return 0;
}

