#define Emax 500000
#define Vmax 100000
#define Dmax 100000000

using namespace std;

struct Edge {
  int to, cost;
};

vector<Edge> edges[Vmax];
static int d[Vmax + 1];
static int Vnum, Enum, r;
static bool visited[Vmax];

void dijkstra() {
  fill_n(d, Vnum + 1, Dmax);
  fill_n(visited, Vnum, false);
  d[r] = 0;
  for (int i = 0; i < Vnum; i++) {
    int u = Vnum;
    for (int j = 0; j < Vnum; j++) {
      if (!visited[j] && d[j] < d[u]) {
        u = j;
      }
    }
    if (u == Vnum) {
      break;
    }
    visited[u] = true;
    for (int j = 0; j < edges[u].size(); j++) {
      auto v = edges[u][j];
      d[v.to] = min(d[v.to], d[u] + v.cost);
    }
  }
}

void dijkstra_priority_queue() {
  auto c = [](int a, int b) {
    return d[a] > d[b];
  };
  priority_queue<int, vector<int>, decltype(c)> Q(c);

  fill_n(d, Vnum, Dmax);
  d[r] = 0;
  for (int i = 0; i < Vnum; i++) {
    Q.push(i);
  }
  while (!Q.empty()) {
    int u = Q.top();
    Q.pop();
    for (int i = 0; i < edges[u].size(); i++) {
      auto v = edges[u][i];
      auto alt = d[u] + v.cost;
      if (d[v.to] > alt) {
        d[v.to] = alt;
        Q.push(v.to);
      }
    }
  }
}

int main(int ac, char **av) {
  scanf("%d %d %d", &Vnum, &Enum, &r);

  for (int i = 0; i < Enum; i++) {
