    scanf("%d %d %d", &s, &t, &d);
    Edge e;
    e.to = t;
    e.cost = d;
    edges[s].push_back(e);
  }

  dijkstra_priority_queue();

  for (int i = 0; i < Vnum; i++) {
    if (d[i] == Dmax) {
      printf("INF\n");
    } else {
      printf("%d\n", d[i]);
    }
  }
  return 0;
}

