void dijkstra(int s) {
    priority_queue<PII, vector<PII>, greater<PII> > q;
    fill(dis, dis+1000000, 0xFFFFFFF);
    q.push(PII(0,s)); // cost, pos
    while(!q.empty()) {
        int cost = q.top().first;
        int pos = q.top().second;
        q.pop();

        if(dis[pos] <= cost) continue;

        dis[pos] = cost;
        for(int i=0; i<G[pos].size(); i++)
            q.push(PII(cost+G[pos][i].second, G[pos][i].first));
    }
    return;
}

