    edge.cost = cost;
    edge.node = end;
    V[begin].edges.push_back(edge);
  }
  V[r].cost = 0;

  while (true) {
    // find closest node
    int closest = -1;
    for (int i = 0; i < nv; ++i) {
      if (!V[i].done && V[i].cost >= 0) {
        if (closest < 0 || V[i].cost < V[closest].cost) {
          closest = i;
        }
      }
    }
    if (closest < 0) {
      break; // done
    }
    V[closest].done = true;

    for (auto& edge : V[closest].edges) {
      // set distances
      int newCost = V[closest].cost + edge.cost;
      if (V[edge.node].cost < 0 || newCost < V[edge.node].cost) {
        V[edge.node].cost = newCost;
      }
    }
  }

  for (auto& v : V) {
    if (v.cost == -1) {
      cout << "INF" << endl;
    } else {
      cout << v.cost << endl;
    }
  }
