void bellmanFord(int s) {
    fill(d, d + V + 10, intmax);
    d[s] = 0;
    for (int i = 0; i < V - 1; i++) {
        bool update = false;
        for (int j = 0; j < V; j++) {
            for (int k = 0; k < G[j].size(); k++) {
                edge e = G[j][k];
                if (d[j] + e.cost < d[e.to]) {
                    d[e.to] = d[j] + e.cost;
                    update = true;
                }
            }
        }
        if (!update) {
            break;
        }
    }
}

