using namespace std;

template< typename T >
struct WeightedGraph : vector< pair< int, T > >
{
  using T
  struct edge
  {
    int to;
    T cost;
  };

  vector< vector< edge > > g;

  WeightedGraph() {}

  WeightedGraph(int n) : g(n) {}

  void add_edge(int u, int v, T cost)
  {
    g[u].emplace_back((edge) {v, cost});
  }

  size_t size() const
  {
    return g.size();
  }
};

template< typename T >
vector< T > dijkstra(WeightedGraph< T > &g, int s)
{
  const auto INF = numeric_limits< T >::max();
  vector< T > dist;
  dist.assign(g.size(), INF);

  using Pi = pair< T, int >;
  priority_queue< Pi, vector< Pi >, greater< Pi > > que;
  dist[s] = 0;
  que.emplace(dist[s], s);
  while(!que.empty()) {
    T cost;
    int idx;
    tie(cost, idx) = que.top();
    que.pop();
    if(dist[idx] < cost) continue;
    for(auto &e : g[idx]) {
      auto next_cost = cost + e.cost;
      if(dist[e.to] <= next_cost) continue;
      dist[e.to] = next_cost;
      que.emplace(dist[e.to], e.to);
    }
  }
  return dist;
}

int main()
{
  int V, E, S;
  scanf("%d %d %d", &V, &E, &S);
  WeightedGraph< int > g(V);
  for(int i = 0; i < E; i++) {
    int x, y, z;
    scanf("%d %d %d", &x, &y, &z);
    g.add_edge(x, y, z);
  }
  auto cost = dijkstra(g, S);
  for(int i = 0; i < V; i++) {
    if(cost[i] == numeric_limits< int >::max()) puts("INF");
    else printf("%d\n", cost[i]);
  }
}

