template <class T>
class radix_heap_64 {
	int bsr(unsigned long long x) {
		return x ? 63 - __builtin_clzll(x) : -1;
	}
	vector<pair<ll, T>> v[65];
	ll last;
	int sz;
public:
	radix_heap_64() : last(0), sz(0) {}
	bool empty() const {
		return !sz;
	}
	void push(ll x, T val) {
		assert(last <= x);
		++sz;
		v[bsr(x ^ last) + 1].emplace_back(x, val);
	}
	pair<ll, T> pop() {
		assert(sz);
		if (v[0].empty()) {
			int i = 1;
			while (v[i].empty()) ++i;
			pair<ll, T> new_last = *min_element(v[i].begin(), v[i].end());
			for (auto x : v[i])  v[bsr(x.first ^ new_last.first) + 1].push_back(x);
			last = new_last.first;
			v[i].clear();
		}
		--sz;
		auto res = v[0].back(); v[0].pop_back();
		return res;
	}
};

const ll INF = 1e18;

vector<ll> dijkstra(int s, const graph<ll>& G, const ll inf = INF) {
	vector<ll> dist(G.size(), inf);
	radix_heap_64<int> pq;
	pq.push(0LL, s);
	while (!pq.empty()) {
		ll d; int v;
		tie(d, v) = pq.pop();
		if (dist[v] != inf) continue;
		dist[v] = d;
		for (auto e : G[v]) if (dist[e.to] > d + e.cost) {
			pq.push(d + e.cost, e.to);
		}
	}
	return dist;
}

