  for (int i = 0; i < n; i++) {
    if (i != s and mark[i]) {
      st.insert(mp(i, INF));
    }
  }
  while (st.size()) {
    pii t = *st.begin();
    st.erase(st.begin());
    for (auto e : G[t.F]) {
      if (dist[e.F] > dist[t.F] + e.S) {
        st.erase(mp(e.F, dist[e.F]));
        dist[e.F] = dist[t.F] + e.S;
        st.insert(mp(e.F, dist[e.F]));
      }
    }
  }
  for (int i = 0; i < n; i++) {
    if (dist[i] > INF) cout<<"INF"<<endl;
    else cout<<dist[i]<<endl;
  }
}

