    while (E--){
        int s, t, d;
        cin >> s >> t >> d;
        Es[s].emplace_back(t, d);
    }
    auto dist = single_source_shortest_path(r, Es);
    for (auto d : dist){
        if (d == -1){
            cout << "INF" << '\n';
        }else{
            cout << d << '\n';
        }
    }
    return 0;
}

