s64 N;
s64 M;
s64 R;

vector<vector<pair<s64,s64>>> G; // to,cost

void dijkstra(s64 start, vector<s64>& d, vector<s64>& trace)
{
    d.assign(N, INF);
    trace.assign(N, INF);
    deque<bool> done(N, false);
    min_heap<pair<s64,s64>> que; // dist,vertex

    d[start] = 0;
    que.emplace(0, start);

    s64 n_remain = N; // ????¢????????????°
    while(!que.empty()) {
        s64 dmin,vmin; tie(dmin,vmin) = POP(que);

        if(d[vmin] < dmin) continue;

        done[vmin] = true;
        if(--n_remain == 0) break;

        for(const auto& p : G[vmin]) {
            s64 to,cost; tie(to,cost) = p;
            if(done[to]) continue;

            s64 d_new = dmin + cost;
            if(d_new < d[to]) {
                d[to] = d_new;
                trace[to] = vmin;
                que.emplace(d_new, to);
            }
        }
    }
}

void solve()
{
    vector<s64> d;
    vector<s64> trace;
    dijkstra(R, d, trace);

    REP(i, N) {
        if(d[i] == INF) {
            PRINTLN("INF");
        }
        else {
            PRINTLN(d[i]);
        }
    }

#ifdef DEBUG
    // ?????????????????????
    REP(i, N) {
        vector<s64> route;
        for(s64 v = i; v != INF; v = trace[v]) {
            route.emplace_back(v);
        }
        ALL(reverse, route);

        if(route[0] != R) {
            assert(d[i] == INF);
        }
        else {
            s64 d_route = 0;
            REP(j, SIZE(route)-1) {
                s64 from = route[j];
                s64 to   = route[j+1];
                s64 cost = ALL(find_if, G[from], [to](const auto& p) {
                    return p.first == to;
                })->second;
                d_route += cost;
            }
            assert(d[i] == d_route);
        }
    }
#endif
}

signed main(signed /*argc*/, char** /*argv*/)
{
    RD(N);
    G.resize(N);
    RD(M);
    RD(R);

    REP(_, M) {
        s64 from, to; RD(from); RD(to);
        s64 cost;     RD(cost);
        G[from].emplace_back(to, cost);
    }

#ifdef DEBUG

#endif

    solve();

    EXIT();
}

