    que.meld(v[r]);
    diff[r]=0;
    while(!que.empty()){
        lint c,e;
        tie(c,e)=que.top();
        que.pop();
        if(diff[e]>c){
            diff[e]=c;
            v[e].add(c);
            que.meld(v[e]);
        }
    }
    rep(i,n){
        if(diff[i]==INF)cout<<"INF"<<endl;
        else cout<<diff[i]<<endl;
    }
}

