int main()
{
	int V = 0; //num of vertices
	int E = 0; //num of edges
	int r = 0; //source node
	//input V, E, r
	cin >> V >> E >> r;

	int **G = new int*[V];//2 dim array to memorize distances
	for (int i = 0; i < V; i++){
		G[i] = new int[V];
	}
	//initiate G
	for (int i = 0; i < V; i++){
		for (int j = 0; j < V; j++){
			G[i][j] = INF;
		}
	}
	for (int i = 0; i < V; i++){
		G[i][i] = 0;
	}

	//input G
	int src = 0; 
	int tar = 0;
	int dis = 0;
	for (int i = 0; i < E; i++){
		cin >> src >> tar >> dis;
		G[src][tar] = dis;
	}

	//start dijkstra
	vector<int> *U = new vector<int>();
	U->push_back(r);
	bool *valid = new bool[V];
	for (int i = 0; i < V; i++){
		valid[i] = true;
	}
	valid[r] = false;

	int min = INF;//record the min-distance
	int ver = V;//record the min-distance-vertice
	while (U->size() < V){
		min = INF;
		ver = V;
		for (int i = 0; i < V; i++){
			if (G[r][i] < min && valid[i]){
				min = G[r][i];
				ver = i;
			}
		}
		if (V == ver){
			break;
		}

		U->push_back(ver);
		valid[ver] = false;
		for (int i = 0; i < V; i++){
			if (i != r && G[r][ver] + G[ver][i] < G[r][i]){
				G[r][i] = G[r][ver] + G[ver][i];
			}
		}
	}

	//output
	for (int i = 0; i < V; i++){
		if (INF == G[r][i]){
			cout << "INF" << endl;
		}
		else{
			cout << G[r][i] << endl;
		}
	}

	//delete
	for (int i = 0; i < V; i++){
		delete[] G[i];
	}
	delete[] G;
	delete[] valid;

	return 0;
}

