void dijkstra(int s) {
    priority_queue<P, vector<P>, greater<P> > que;
    fill(d, d +V, INF);
    d[s] = 0;
    que.push(P(0, s));

    while (!que.empty()){
        P p = que.top(); que.pop();
        int v = p.second;
        if (d[v] < p.first) continue; // 取り出したものが頂点の最短距離でなければ無視
