template <typename T>
struct dijkstra{
    using P = pair<T, ll>;
    const T inf = numeric_limits<T>::max();
    vector<vector<pair<ll,T>>> G;
    vector<ll> beforev;
    vector<T> dist;
    ll N, start;
    priority_queue<P, vector<P>, greater<P>> pq;

    dijkstra(ll n) : N(n) {
        G.resize(n), beforev.assign(n, -1), dist.assign(n, inf);
    }

    void add_edge(ll u, ll v, T cost){
        G[u].emplace_back(v, cost);
    }

    void init(ll s){
        start = s;
        fill(beforev.begin(), beforev.end(), -1), fill(dist.begin(), dist.end(), inf);
        dist[start] = 0, pq.emplace(0, start);

        while(!pq.empty()){
            T c; ll from;
            tie(c, from) = pq.top(), pq.pop();
            if (dist[from] < c) continue;
            for(auto& e: G[from]){
                ll to; T cost;
                tie(to, cost) = e;
                if(dist[to]>dist[from]+cost){
                    dist[to] = dist[from] + cost;
                    beforev[to] = from;
                    pq.emplace(dist[to], to);
                }
            }
        }
    }

    vector<ll> get_route(ll goal){
        vector<ll> route;
        ll now = goal;
        while(now!=-1){
            route.emplace_back(now);
            now = beforev[now];
        }
        reverse(route.begin(), route.end());
        return route;
    }
};
int main() {
    init();
    ll N, M, S;
    cin >> N >> M >> S;
    dijkstra<ll> dj(N);
    rep(i,M){
        ll u, v, c;
        cin >> u >> v >> c;
        dj.add_edge(u, v, c);
    }
    dj.init(S);
    rep(i,N){
        ll d = dj.dist[i];
        if(d>=INF){
            cout << "INF" << '\n';
        }
        else{
            cout << d << '\n';
        }
    }
}

