const int Inf = 10000 * 100000 + 100;

int main()
{
    cin >> POINT_NUM >> NODE_NUM >> start;
    if (NODE_NUM == 0)
    {
        for (int i = 0; i < POINT_NUM; i++)
        {
            cout << (i == start ? to_string(0) : "INF") << endl;
