    {
        bool update = false;
        for (int i = 0; i < NODE_NUM; ++i)
        {
            // t: 頂点
            // i: ノードの値
            int s = S[i], t = T[i], d = D[i];
            if (C[s] < Inf && C[t] > C[s] + d)
