  for(int i=0;i<V;i++) mindist[i] = IINF;
  mindist[r] = 0;
  priority_queue<Data> Q;
  Q.push((Data){r,0});
  while( !Q.empty() ){
    Data data = Q.top(); Q.pop();
    int cur = data.cur;
    if( mindist[cur] < data.weight ) continue;
    for(int i=0;i<(int)G[cur].size();i++){
      int next   = G[cur][i];
      if( mindist[next] > data.weight + W[cur][i] )  {
	mindist[next] = data.weight + W[cur][i];
	Q.push((Data){next,mindist[next]});
      }
    }
  }
}

