//aoj 単一始点最短経路
void solve(void){

	int V, E, r;
	cin >> V >> E >> r;

	Dijkstra dijkstra(V);

	while(E--)
	{
		int s, g; ll c;
		cin >> s >> g >> c;
		dijkstra.add_edge(s, g, c, 1);
	}
	dijkstra.calc(r);
	rep(V, i)
	{
		ll dis = dijkstra.dis[i];
		if (dis == dijkstra.inf)
		{
			cout << "INF" << endl;
		}
		else
		{
			cout << dis << endl;
		}
	}
}

int main(void){
	solve();
	//cout << "yui(*-v・)yui" << endl;
	return 0;
}

