int getMinDistVertex(int V)
{
    int min = MAX;
    int v=0;
    for(int i=0; i<V; i++)
    {
        if(!visited[i] && min > dist[i])
        {
            min = dist[i];
            v = i;
        }

    }
    return v;
}

void dijkstra(int V)
{
    int v = getMinDistVertex(V);   
    visited[v] = true;

