#include <iostream>
#define MAX_LEN 100001
#define MAX_DIST 2147483647
using namespace std;

typedef struct node {
    int id;
    int dist;
    node* next;

    node(int inpId, int inpDist, node* inpNext = NULL): id(inpId), dist(inpDist), next(inpNext) {}
}* nodeptr;

class chain {
public:
    nodeptr head;
    nodeptr tail;

    chain(): head(NULL), tail(NULL) {}

    void push(int id, int dist) {
        nodeptr tmp = new node(id, dist);
        if (this->tail != NULL) {
            this->tail->next = tmp;
            this->tail = tmp;
        } else {
            this->head = this->tail = tmp;
        }
    }
};

int main() {
//    freopen("in.txt", "r", stdin);

    chain* graph[MAX_LEN];
    int s[MAX_LEN];
    int finalDist[MAX_LEN];
    int path[MAX_LEN];
    int V, E, r;
    int si, ti, di;
    long long int minDist = MAX_DIST;
    int curMinV = -1;
    nodeptr tmpNodeptr;

    // preparation
    cin >> V >> E >> r;
    for (int i = 0; i < MAX_LEN; ++i) {
        graph[i] = new chain();
        path[i] = -1;
        finalDist[i] = MAX_DIST;
        s[i] = 0;
    }
    for (int i = 0; i < E; ++i) {
        cin >> si >> ti >> di;
        graph[si]->push(ti, di);
    }

    // main process
    s[r] = 1;
    path[r] = r;
    finalDist[r] = 0;
    if (graph[r]->head != NULL) {
        tmpNodeptr = graph[r]->head;
        while (1) {
            path[tmpNodeptr->id] = r;
            finalDist[tmpNodeptr->id] = tmpNodeptr->dist;
            if (tmpNodeptr->next != NULL) {
                tmpNodeptr = tmpNodeptr->next;
            } else {
                break;
            }
        }

        for (int i = 0; i < MAX_LEN - 1; ++i) {
            minDist = MAX_DIST, curMinV = -1;
            for (int j = 0; j < V; ++j) {
                if (!s[j] && finalDist[j] >= 0 && minDist > finalDist[j]) {
                    minDist = finalDist[j];
                    curMinV = j;
                }
            }
            if (curMinV == -1) {break;}

            s[curMinV] = 1;
            tmpNodeptr = graph[curMinV]->head;
            while (1) {
                if (tmpNodeptr == NULL) {break;}
                if (!s[tmpNodeptr->id] && finalDist[tmpNodeptr->id] > tmpNodeptr->dist + minDist) {
                    finalDist[tmpNodeptr->id] = tmpNodeptr->dist + minDist;
                    path[tmpNodeptr->id] = curMinV;
                }

                if (tmpNodeptr->next != NULL) {
                    tmpNodeptr = tmpNodeptr->next;
                } else {
                    break;
                }
            }
        }
    }

    for (int i = 0; i < V; ++i) {
        if (finalDist[i] < MAX_DIST)
            cout << finalDist[i] << endl;
        else
            cout << "INF" << endl;
    }
}

