void add_edge(int s,int t,int d) //add information of edge
{    
    edges[count].t=t;
    edges[count].d=d;
    edges[count].next=head[s];
    head[s]=count;
	count++;
}

int hash_transfer(int point)
{
	int j;
	for(j=0;j<v;j++)
		if(hash[j]==point)
		{
			point=j;
			break;
		}
	if(j>=v)
		point=hash_map(point%v,point,0);	
	return point;
}

int hash_map(int x,int point,int i)
{	
	if(hash[x]<0)
		hash[x]=point;
	else
		if(i<=v)
			x=hash_map((x+1)%v,point,i++);
		else 
			return -1;
	return x;
}

