void bellman_ford(int V, int E, int D[], int r){

	for(int i = 0; i <= V; ++i){
		C[i] = Inf;
		C[r] = 0;
		//cout << C[i] << endl;
	}
	//cout << r << endl;
	//cout << C[0] << " " << C[1] << " "<< C[2] <<   endl;
	for (int t=0; t<V; ++t){
