			int s = S[i], t = T[i], d = D[i]; // i 番目の辺のs,t,d に対して
			//cout << C[s] << " " << C[t] << endl;
			if(C[s] < Inf && C[t] > C[s] + d){//s,tを緩和できるならば
				C[t] = C[s] + d; //C[t]を更新
				update = true;	
			} 
		}
		if (!update) break;
	}
	for (int t=0; t<V; ++t){
		if(C[t] != Inf){
			cout <<  C[t] << endl;
		}
		else{
			cout << "INF" << endl;
