    const int now = pii.second;
    for(int i=0; i<G[now].size(); i++) {
      const int next = G[now][i].to;
      if(dist[next] > cost+G[now][i].cost) {
        dist[next] = cost+G[now][i].cost;
        pq.push(Pii(dist[next], next));
      }
    }
  }

  for(int i=0; i<V; i++) {
    if(dist[i] == INF) cout << "INF" << endl;
    else cout << dist[i] << endl;
  }

  return 0;
}

