      typedef std::vector<long> LI;
      long v, e, r;
      scan(v, e, r);
      LI ss(e+1), ds(e+1);
      LI ws(e+1);
      for(long i = 0; i < e; ++i) {
         scan(ss[i], ds[i], ws[i]);
      }
      N003<long> g(v, ss, ds, ws);
      N004<long> dijkstra(g, r, (1LL << 60));
      for(long i = 0; i < v; ++i) {
         long res = dijkstra.xs[i];
         if( res == (1LL << 60) ) {
            puts("INF");
         }
         else {
            printf("%ld\n", res);
         }
      }
   }
};

