class Node{
public:
	vector<int> to;
	vector<int> from;
	vector<int> ecost;
	int cost;
	bool done;
	bool avail;
	Node(){ done=0; cost=-1; avail=0; }
};

void check(Node *node, int nodes, int start);
void find(Node *node, int nodes, int start);

int main(){
	int v, e, r;
	cin >> v >> e >> r;

	int s[e], t[e], d[e];
	int i;
	for(i=0 ; i<e; i++){
		cin >> s[i] >> t[i] >> d[i];
	}

	Node node[v];
	for(i=0; i<e; i++){
		node[s[i]].to.push_back(t[i]);
		node[s[i]].ecost.push_back(d[i]);
		node[t[i]].from.push_back(s[i]);
	}

	check(node, v, r);
	find(node, v, r);
	for(i=0; i<v; i++){
		if(node[i].cost==-1){ cout << "INF" << endl;}
		else{ cout << node[i].cost << endl; }
	}

	return 0;
}

void check(Node *node, int nodes, int start){
	int i ,j;
	int loop=0;

	node[start].avail=1;
	for(i=0; i<node[start].to.size(); i++){
		node[node[start].to[i]].avail=1;
		loop=1;
	}

	while(loop){
		loop=0;
		for(i=0; i<nodes; i++){
			for(j=0; j<node[i].to.size(); j++){
				if(node[node[i].to[j]].avail==0){
					node[node[i].to[j]].avail=1;
					loop=1;
				}
			}
		}
	}
	for(i=0; i<nodes; i++){
		if(node[i].avail==0){
			node[i].done=1;
		}
	}
}

void find(Node *node, int nodes, int start){
	int i, j;
	if(node[start].done) return;

	node[start].cost=0;
	node[start].done=1;

	for(i=0; i<node[start].to.size(); i++){
		node[node[start].to[i]].cost = node[start].ecost[i];
	}


	bool dflag;
	while(1) {
		j=1;
	    for(i=0; i<nodes; i++){ j *= node[i].done; }
	    if(j) break;

		for(i=0; i<nodes; i++){
			dflag=1;
			if(node[i].to.size()==0) node[i].done=1;
			if(node[i].done) continue;
			if(node[i].cost==-1) continue;

			for(j=0; j<node[i].to.size(); j++){
				if(node[node[i].to[j]].cost == -1){
					node[node[i].to[j]].cost = node[i].cost + node[i].ecost[j];
					dflag=0;
					continue;
				}
				if(node[node[i].to[j]].cost > node[i].cost + node[i].ecost[j]){
					node[node[i].to[j]].cost = node[i].cost + node[i].ecost[j];
					dflag=0;
					continue;
				}
			}
			if(dflag) node[i].done=1;
		}
	}
}

