using namespace std;
typedef pair<int, int> P;
vector<vector<P> > G;
vector<int> d;
int min(int a, int b) {
	if (a == -1) return b;
	if (b == -1) return a;
	if (a < b) return a;
	return b;
}
void dijkstra(int s) {
	int N = G.size();
	d.resize(N);
	for (int i = 0; i < N; i ++) d[i] = -1;
	vector<bool> visited(N, false);
	d[s] = 0;
	while (true) {
		int v = -1; int min_d = -1;
		for (int i = 0; i < N; i ++) {
			if (visited[i]) continue;
			if (v == -1 || min(d[i], min_d) != min_d) {
				v = i; min_d = d[i];
			}
		}
		if (v == -1) break;
		visited[v] = true;
		for (int i = 0; i < int (G[v].size()); i ++) {
			P e = G[v][i];
			int e_next = e.first;
			int e_cost = e.second;
			if (d[v] != -1) d[e_next] = min(d[e_next], d[v] + e_cost);
		}
	}
}
int main() {
