using namespace std;

#define INFINITE 100000*10000
#define _for(j,N) for(int i = (j);i < (N);++i)

vector<long> wt;

class Node{
public:
    int v;
    long wt;
    Node(int vi,long wti):v(vi),wt(wti){;}
};

struct compare{
    bool operator()(const Node& n1,const Node& n2) const{
        return n1.wt < n2.wt;
    }
};

priority_queue<Node,vector<Node>,compare> pq;

class Graph{
public:
    int V;
    int E;
    vector<forward_list<Node>> adj;
    Graph(int v,int e):V(v),E(e){
        adj.resize(V);
        wt.resize(V);
        _for(0,V) {wt[i] = INFINITE;}

    }
    void addEdge(int v,int w,long wt){adj[v].push_front(Node(w,wt));}
    void distra(int v);
};


void Graph::distra(int v){
    wt[v] = 0;
    pq.push(Node(v,0));
    while(!pq.empty()){
        int w = pq.top().v;
        long ac_wt = pq.top().wt;
        pq.pop();

        for(auto a = adj[w].begin();a != adj[w].end();++a){
            int t = (*a).v;
            long wt_now = (*a).wt;

            if(wt[t] > wt_now + ac_wt){
                wt[t] = wt_now + ac_wt;
                pq.push(Node(t,wt[t]));
            }
        }
    }
}

int main()
{
    int V,E,r;
    int s,t,w;
    scanf("%d %d %d",&V,&E,&r);
    Graph G(V,E);
    _for(0,E){
        scanf("%d %d %d",&s,&t,&w);
        G.addEdge(s,t,w);
    }

    G.distra(r);

    _for(0,V){
        if(wt[i] == INFINITE) printf("INF\n");
        else printf("%ld\n",wt[i]);
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

template< typename T >
struct edge {
    int src,to;
    T cost;

    edge() = default;

    edge(int to, T cost) : src(-1), to(to), cost(cost) {}

    edge(int src, int to, T cost) : src(src), to(to), cost(cost) {}

    bool operator<(const edge &e) const {
        return cost < e.cost;
    }
};

////////////////////////////////////////////////////////////////////////

template<typename T>
vector<T> Dijkstra(vector<vector<edge<T>>> &G, int s, T inf) {
    vector<T> dist(G.size(),inf);

    using Pi = pair<T, int>;
    priority_queue<Pi, vector<Pi>, greater<Pi>> pq;
    dist[s] = 0;
    pq.emplace(dist[s],s);
    while (!pq.empty()) {
        T d; int v;
        tie(d,v) = pq.top(); pq.pop();
        if (d > dist[v]) continue;
        for (auto &e : G[v]) {
            if (dist[e.to] > dist[v] + e.cost) {
                dist[e.to] = dist[v] + e.cost;
                pq.emplace(dist[e.to],e.to);
            }
        }
    }

    return dist;
}

