void dij(int s){
//use greater<P> to pop minimum struct in the P-queue
	priority_queue<P,vector<P>,greater<P> >que;
	fill(d,d+V,INF);//insted of "for"loop
	d[s]=0;
	que.push(P(0,s));

	while(!que.empty()){
		P p=que.top();
		que.pop();
		int v=p.second;
