		if(i==r){cout<<0<<endl;continue;}

		std::function<void(int,int)> func = [&](int cur, int sum){
			mark[cur] = 1;

			if(matrix[cur][i] != -1){
				if(min == -1){
					min = sum + matrix[cur][i];
				}
				else if(sum + matrix[cur][i] <= min){
					min = sum + matrix[cur][i];
				}
			}
			for(int j=0;j<V;++j){
				if(j!=i){
					if(matrix[cur][j] != -1){
						if(mark[j]==0){
							func(j,sum+matrix[cur][j]);
						}

					}
				}
			}
			mark[cur]=0;
		};


		func(r,0);
		if(min!=-1)cout<<min<<endl;
		else cout<<"INF"<<endl;


		delete[] mark;

	}

	for(int i=0;i<V;++i){
		delete[] matrix[i];
	}
