#include <bits/stdc++.h>
using namespace std;

template<class Weight> using edge = pair<int, Weight>;
template<class Weight> using graph = vector<vector<edge<Weight>>>;

template<class Weight>
vector<Weight> dijkstra(int s, const graph<Weight> &G) {
	using P = pair<Weight, int>;
	const int n = G.size();

	vector<Weight> dist(n, numeric_limits<Weight>::max());
	priority_queue<P, vector<P>, greater<P>> que;

	dist[s] = 0;
	que.emplace(0, s);

	while(!que.empty()) {
		const auto d = que.top().first;
		const auto v = que.top().second;
		que.pop();

		if(dist[v] < d) continue;

		for(const auto &e : G[v]) {
			const auto next_dist = d + e.second;
			if(dist[e.first] > next_dist) {
				dist[e.first] = next_dist;
				que.emplace(next_dist, e.first);
			}
		}
	}

	return dist;
}

template<class Weight>
Weight dijkstra(int s, int g, const graph<Weight> &G) {
	return dijkstra(s, G)[g];
}

