template<typename T> class Heap {
public:
    struct node {
        node* l; node* r; T val;
        node(T t) : l(nullptr), r(nullptr), val(t){}
    };
    node* root;
    node* meld(node* a, node* b){
		if(!a) return b; if(!b) return a;
        if(a->val < b->val) swap(a, b);
        a->r = meld(a->r,b); swap(a->l, a->r);
        return a;
    }
    void push(T val){ node* p = new node(val); root = meld(root, p); }
    T top(){ return root->val; }
    void pop(){ node* p = root; root = meld(root->r, root->l); delete p; }
};


struct edge{
	int to, cost;
};

int d[MAX_N];
vector<edge> G[MAX_N];

void dijkstra(int s)
{
	Heap<P> que;
	d[s] = 0;
	que.push(P(0,s));
	while(que.root){
		P p = que.top();
		que.pop();
		int v = p.second;
		if(d[v] < p.first) continue;
		for(auto w : G[v]){
			if(d[w.to] > d[v] + w.cost){
				d[w.to] = d[v] + w.cost;
				que.push(P(d[w.to],w.to));
			}
		}
	}
}

