template<typename Tweight, bool isdirected, u32 maxV, u32 maxE>
Graph<Tweight, isdirected, maxV, maxE>::Graph() {
  edge_num = 0;
  vertex_num = 0;
  for(int i = 0; i < maxV; ++i) {
    adjust_size_[i] = 0;
    index[i] = 0;
  }
}

template<typename Tweight, bool isdirected, u32 maxV, u32 maxE>
Graph<Tweight, isdirected, maxV, maxE>::Graph(u32 V) {
  edge_num = 0;
  vertex_num = V;
  for(int i = 0; i < maxV; ++i) {
    adjust_size_[i] = 0;
    index[i] = 0;
  }
}

template<typename Tweight, bool isdirected, u32 maxV, u32 maxE>
void Graph<Tweight, isdirected, maxV, maxE>::insert(Edge<Tweight> edge) {
  edge_[edge_num] = edge;
  edge_num += 1;
  if( not isdirected ) {
    edge_[edge_num] = edge.reverse();
    edge_num += 1;
  }
  vertex_num = Max(vertex_num, edge.from());
  vertex_num = Max(vertex_num, edge.to());
}

template<typename Tweight, bool isdirected, u32 maxV, u32 maxE>
void Graph<Tweight, isdirected, maxV, maxE>::insert(u32 s, u32 t, Tweight w) {
  insert(Edge<Tweight>(s, t, w));
}

template<typename Tweight, bool isdirected, u32 maxV, u32 maxE>
void Graph<Tweight, isdirected, maxV, maxE>::activate() {
  Edge<Tweight> buffer[maxE];
  u32 E = edge_num;
  u32 count[maxV];
  for(int i = 0; i < maxV; ++i) count[i] = 0;
  for(int i = 0; i < E; ++i) {
    count[edge_[i].from()] += 1;
  }
  for(int i = 0; i < maxV; ++i) {
    adjust_size_[i] = count[i];
  }
  int t = 0;
  for(int i = 0; i < maxV; ++i) {
    t += count[i];
    count[i] = t - count[i];
    index[i] = count[i];
  }
  for(int i = 0; i < E; ++i) {
    buffer[count[edge_[i].from()]] = edge_[i];
    count[edge_[i].from()] += 1;
  }
  for(int i = 0; i < E; ++i) {
    edge_[i] = buffer[i];
  }
}

template<typename Tweight, bool isdirected, u32 maxV, u32 maxE>
