u32 Graph<Tweight, isdirected, maxV, maxE>::adjust_size(u32 v) {
  return adjust_size_[v];
}

template<typename Tweight, bool isdirected, u32 maxV, u32 maxE>
u32 Graph<Tweight, isdirected, maxV, maxE>::Vsize() const {
