template<typename Tweight, bool isdirected, u32 maxV, u32 maxE>
bool Bellman_Ford(const Graph<Tweight, isdirected, maxV, maxE>& graph, u32 s, Tweight dist[]);

template<typename Tweight, bool isdirected, u32 maxV, u32 maxE>
bool Bellman_Ford(const Graph<Tweight, isdirected, maxV, maxE>& graph, u32 s, Tweight dist[]) {
  for(int i = 0; i < graph.Vsize(); ++i) dist[i] = INF;
  dist[s] = 0;
  for(int i = 0; i < graph.Vsize(); ++i) {
    bool update = false;
    for(int j = 0; j < graph.Esize(); ++j) {
      auto edge = graph.edge(j);
      if( dist[edge.from()] != INF && dist[edge.to()] > dist[edge.from()] + edge.weight()) {
        dist[edge.to()] = dist[edge.from()] + edge.weight();
        update = true;
        if( i == graph.Vsize() - 1) return false;
      }
    }
    if( not update ) break;
  }
  return true;
}


