template<class node_t,class cost_t>
class djikstra {
private:
	map<node_t, multiset<pair<node_t, cost_t>>> g;
	priority_queue<pair<cost_t, node_t>,deque<pair<cost_t, node_t>>,greater<>> q;
	map<node_t, cost_t> d;
	set<node_t> v;
	node_t s = -1;
	void compute(node_t start) {
		s = start;
		v.clear();
		d.clear();
		d[s] = 0;
		q.push(make_pair(0,s));
		while (!q.empty()) {
			node_t c = q.top().second;
			q.pop();
			if (v.find(c) != v.end()) continue;
			v.insert(c);
			for (auto& e : g[c]) {
				if (d.find(e.first) == d.end()) d[e.first] = d[c] + e.second;
				else d[e.first] = min(d[e.first], d[c] + e.second);
				q.push(make_pair(d[e.first], e.first));
			}
		}
	}
public:
	cost_t get_dist(node_t start, node_t end) {
		if (start != s) compute(start);
		if (d.find(end) != d.end()) return d[end];
		else return cost_t(-1);
	}
	void add_path(node_t src, node_t dst,cost_t cost) {
		g[src].insert(make_pair(dst, cost));
	}
};

int main() {
	int v, e, r, s, t, d;
	cin >> v >> e >> r;
	djikstra<int, int> w;
	rep(i, e) {
		cin >> s >> t >> d;
		w.add_path(s, t, d);
	}
	rep(i, v) {
		if (w.get_dist(r, i) == -1) cout << "INF";
		else cout << w.get_dist(r,i);
		cout << "\n";
	}
}

