	for(i=0;i<MAX_V;i++) d[i]=INF;
	d[r]=0;
	priority_queue< P > Q;
	Q.push(P(0,r));
	while(!Q.empty()){
		P p=Q.top();
		Q.pop();
		int pos=p.second,cost=-p.first;
		if(cost>d[pos]) continue;
		for(i=0;i<G[pos].size();i++){
			edge e=G[pos][i];
			int to=e.to;
			int newcost=cost+e.cost;
			if(newcost<d[to]){
				d[to]=newcost;
				Q.push(P(-d[to],to));
			}
		}
	}
	for(i=0;i<V;i++){
		if(d[i]==INF)printf("INF\n");
		else printf("%d\n",d[i]);
	}
}

