void solve(int r){

  fill(d,d+MAX+1,INF);

  priority_queue<P,vector<P>,greater<P> > qu;

  qu.push(P(0,r));
  d[r]=0;

  while(!qu.empty()){

    P p=qu.top();
    qu.pop();
    int v=p.second;

    if(d[v]<p.first) continue;
    for(int i=0;i<G[v].size();i++){
      Edge *e=&G[v][i];
      if(d[v]+e->cost < d[e->to]){
	d[e->to]=d[v]+e->cost;
	qu.push(P(d[e->to],e->to));
      }
    }
  }

}



