void func(int cur, int sum, int i, int*mark, int *min, int V){
	mark[cur] = 1;

		if(matrix[cur][i] != -1){
			if(*min == -1){
				*min = sum + matrix[cur][i];
			}
			else if(sum + matrix[cur][i] <= *min){
				*min = sum + matrix[cur][i];
			}
		}
		for(int j=0;j<V;++j){
			if(j!=i){
				if(matrix[cur][j] != -1){
					if(mark[j]==0){
						if(*min==-1 ||  sum+matrix[cur][j]<=*min)
						func(j,sum+matrix[cur][j],i,mark,min,V);
					}
				}
			}
		}
	mark[cur] = 0;
}


