typedef ll Cost;
typedef vector<vector<Edge<Cost>>> Graph;

template<class Cost> vector<vector<Cost> > dijkstra_k(const Graph& g,const int s,const int k){
    vector<vector<Cost>> ds(g.size());ds[s].push_back(0);
    priority_queue<pair<Cost,int>,vector<pair<Cost,int>>,greater<pair<Cost,int>>> que;que.push({0,s});// [ ,e,,f, ] <=> e.cost < e.cost
    while(!que.empty()){
        Cost c;int v;tie(c,v)=que.top();que.pop();
        for(const Edge<Cost>& e:g[v]){ 
            if(ds[v].size()<k){
                ds[v].push_back(c);
                que.push({c + e.cost,e.to});
            }
        }
    }
    return ds;
}

