        if(d[x]<p.first) continue;
        for(int i=0;i<G[x].size;i++){
            edge e=G[x][i];
            if(d[e.to]>e.cost+d[x]){
                d[e.to]=e.cost+d[x];
                q.push(d[e.to],e.to);
            }
        }
    }
    for(int i=0;i<v;i++){
        if(d[e.to]==INF) printf("INF\n");
        else printf("%d\n",d[e.to]);
    }
    return 0;
}

#include <bits/stdc++.h>

using namespace std;

struct edge {
    int to, cost;
};

vector<int> dijkstra(const vector<vector<edge>>& g, int s) {

    int n = g.size();
    const int INF = numeric_limits<int>::max();
    vector<int> dist(n, INF);

    using P = pair<int,int>;
    priority_queue<P, vector<P>, greater<P>> que;

    que.emplace(0, s);
    dist[s] = 0;
    while (!que.empty()) {
        int d, v; tie(d, v) = que.top(); que.pop();
        if (dist[v] < d) continue;
        for (const edge& e : g[v]) {
            int nxt = d + e.cost;
            if (dist[e.to] > nxt) {
                dist[e.to] = nxt;
                que.emplace(nxt, e.to);
            }
        }
    }
    return dist;
}

