        g[u].push_back((edge){v, c});
    }

    const int INF = numeric_limits<int>::max();
    for (int d : dijkstra(g, s)) {
        if (d < INF) cout << d << endl;
        else cout << "INF" << endl;
    }

    return 0;
}

