  cin.tie(0);
  ios::sync_with_stdio(false);
  cout << fixed << setprecision(10);

  ll n, m, r;
  cin >> n >> m >> r;
  dijkstra D(n);
  REP(i,m){
    ll s, t, d;
    cin >> s >> t >> d;
    D.in_edge(s,t,d);
  }
  vll tmp = D.dis_from_s(r);
  REP(i,n){
    if(tmp[i] == LINF) cout << "INF" <<endl;
    else cout << tmp[i] << endl;
  }

  return 0;
}

