int main() {
    ll N, M, R;
    cin >> N >> M >> R;
    REP(i, M) {
        ll a, b, c;
        cin >> a >> b >> c;
        V[a].node.push_back(pll(b, c));
    }
    REP(i, N) {
        C[i] = INF;
    }

    priority_queue<pll, vector<pll>, function<bool(pll, pll)>> q([](pll a, pll b) { return a.second > b.second; });

    q.push(pll(R, 0));
    while (!q.empty()) {
        pll t = q.top();
        q.pop();

        if (C[t.first] <= t.second)
