	}

	Node node[v];
	for(i=0; i<e; i++){
		node[s[i]].to.push_back(t[i]);
		node[s[i]].ecost.push_back(d[i]);
		node[t[i]].from.push_back(s[i]);
	}

	find(node, v, r);
	for(i=0; i<v; i++){
