class Node{
public:
    int v;
    long wt;
    Node(int vi,long wti):v(vi),wt(wti){;}
};

struct compare{
    bool operator()(const Node& n1,const Node& n2) const{
        return n1.wt < n2.wt;
    }
};

priority_queue<Node,vector<Node>,compare> pq;

class Graph{
public:
    int V;
    int E;
    vector<forward_list<Node>> adj;
    Graph(int v,int e):V(v),E(e){
        adj.resize(V);
        wt.resize(V);
        _for(0,V) {wt[i] = INFINITE;}

    }
    void addEdge(int v,int w,long wt){adj[v].push_front(Node(w,wt));}
    void distra(int v);
};


void Graph::distra(int v){
    wt[v] = 0;
    pq.push(Node(v,0));
    while(!pq.empty()){
        int w = pq.top().v;
        long ac_wt = pq.top().wt;
        pq.pop();

        for(auto a = adj[w].begin();a != adj[w].end();++a){
            int t = (*a).v;
            long wt_now = (*a).wt;

            if(wt[t] > wt_now + ac_wt){
                wt[t] = wt_now + ac_wt;
                pq.push(Node(t,wt[t]));
            }
        }
    }
}

