vector<Weight> dijkstra(const Graph &g,int s){
	int n=g.size();
	using state=tuple<Weight,int>;
	vector<Weight> dist(n,inf);
	priority_queue<state,vector<state>,greater<state>> q;
	dist[s]=0,q.push(state(0,s));
	while(!q.empty()){
		Weight c; int v;
