/* 詳細なグラフ定義 */
using Node = long long; //頂点
using Distance = long long; //距離
using Weight = long long; //重み
using Edge = pair<Node, Weight>; //辺
using Graph = vector<vector<Edge>>; //隣接リスト

ll V,E,r;
