int main() {
  int n, m, source;
  cin >> n >> m >> source;
  vector<map<int, int>> adj(100000);
  constexpr int UNSEEN{1000000001};
  vector<int> d(100000, UNSEEN);
  bool visited[100000];
  int n_visited = 0;

  for (int u, v, len; cin >> u >> v >> len;) {
    adj[u][v] = len;
  }

  auto cmp = [&](int s, int t) { return d[s] > d[t]; };
  priority_queue<int, vector<int>, decltype(cmp)> q(cmp);

  d[source] = 0;
  q.push(source);
  while (!q.empty() and n_visited < n) {
    auto u = q.top();
    q.pop();
    if (visited[u])
      continue;
    ++n_visited;
    visited[u] = true;
    for (auto &kv : adj[u]) {
      d[kv.first] = min(d[kv.first], d[u] + kv.second);
      q.push(kv.first);
    }
  }

  for (int i = 0; i < n; ++i) {
    if (visited[i])
      cout << d[i];
    else
      cout << "INF";
    cout << endl;
  }
}

