vector<Weight> dijkstra(const Graph &G, int s) {
    using P = pair<Weight, int>;
    priority_queue<P, vector<P>, greater<P>> que;
    vector<Weight> d(G.size(), INF);
    fill(ALL(d), INF);
    d[s] = 0;
    que.push(P(0, s));
    while (not que.empty()) {
        P p = que.top(); que.pop();
        int v = p.second;
        if (d[v] < p.first) continue;
        REP(i, G[v].size()) {
            Edge e = G[v][i];
            if (d[v]+e.cost < d[e.to]) {
                d[e.to] = d[v] + e.cost;
                que.push(P(d[e.to], e.to));
            }
        }
    }
    return d;
}


