	int num,start;
	list *L[LARGE];
	node N[LARGE];

	scanf("%d %d %d",&V,&E,&start);
	num=V;

	for(i=0;i<V;i++){
		L[i]=NULL;
		N[i].id=i;
		N[i].cost=INF;
		heap_id[i]=i;
		id_heap[i]=i;
	}
	N[start].cost=0;
	swap(0,start);

	for(i=0;i<E;i++){
		scanf("%d %d %d",&s,&t,&d);
		Make_AdjList(L,s,t,d);
	}

	while(num!=0){
		num=Dijkstra(L,N,num);
	}

	for(i=0;i<V;i++){
		if(N[i].cost==INF)printf("INF\n");
		else printf("%d\n",N[i].cost);
	}

	return 0;

}

