  H[1]=H[heapS];
  heapS--;
  minHeapify(1);
  return min;
}

void minHeapify(int i)
{
  int r,l,small,tmp;
  l=i*2;
  r=i*2+1;

  if(l<=heapS && d[H[l]]>d[H[i]])small=l;
  else small=i;

  if(r<=heapS && d[H[r]]>d[H[small]])small=r;

  if(small!=i){
    tmp=H[i];
    H[i]=H[small];
    H[small]=tmp;
    minHeapify(small);
  }
}
void HI(int key)
{
  heapS+=1;
  H[heapS]=-1;
  Increase(heapS,key);
}
void Increase(int i,int key)
{
  int tmp;
  H[i]=key;
  while(i>1 && d[H[i/2]]>d[H[i]]){
    tmp=H[i];
    H[i]=H[i/2];
    H[i/2]=tmp;
    i=i/2;
  }
}

