void Make_AdjList(list* L[],int s,int t,int d){
	list *new=malloc(sizeof(list));
	list **p=&L[s];
	/*card作成*/
	new->id=t;	new->cost=d;  new->next=NULL;

	while((*p)!=NULL)p=&((*p)->next);
	(*p)=new;

	return;
}

void swap(int x,int y){
	int temp;

	temp=heap_id[x];
	heap_id[x]=heap_id[y];
	heap_id[y]=temp;

	temp=id_heap[heap_id[x]];
	id_heap[heap_id[x]]=id_heap[heap_id[y]];
	id_heap[heap_id[y]]=temp;

	return;
}

void heap_updata(node N[],int x){

	for(int i=x;i>0;i--){
		if(i%2==0){
			if(N[heap_id[i]].cost < N[heap_id[i/2-1]].cost)swap(i,i/2-1);
		}else {
			if(N[heap_id[i]].cost < N[heap_id[i/2]].cost)swap(i,i/2);
		}
	}

	return;

}


int Dijkstra(list* L[],node N[],int num){
	int u=heap_id[0];
	list *p=L[u];

	swap(0,num-1);
	num--;

	while(p!=NULL){
		if(N[p->id].cost > N[u].cost+(p->cost)){
			N[p->id].cost=N[u].cost+(p->cost);
			heap_updata(N,id_heap[p->id]);
		}
		p=p->next;
	}

	return num;

}

