    int s, t, d;
    scanf("%d%d%d", &s, &t, &d);
    vec_push(tree->data[s], new_Edge(t, d));
  }

  Vector *ret = dijkstra(tree, r);

  for (int i = 0; i < V; i++) {
    int result = VoPTR_TO_INT(ret->data[i]);
    if (result >= INF) {
      printf("INF\n");
    } else {
      printf("%ld\n", result);
    }
  }

  return 0;
}

