void Dijkstra(int p, int size)
{
        dist[p] = 0;
        while (1) {
                int i, u = -1, min = INT_MAX;
                for (i = 0; i < size; i++) {
                        if (!visit[i] && dist[i] < min) {
                                u = i;
                                min = dist[i];
                        }
                }
                if (u == -1) break;
                visit[u] = 1;
                for (i = 0; i < size; i++) {
                        if (matrix[u][i] >= 0) {
                                int w = matrix[u][i], newlen = dist[u] + w;
                                if (newlen < dist[i]) {
