}
void downheap(int k)
{
  int j, v = heap[k];
  while (k < heapsize / 2) {
    j = 2 * k + 1;
    if (j < heapsize - 1 && dist[heap[j]] > dist[heap[j + 1]]) j++;
    if (dist[v] <= dist[heap[j]]) break;
    heap[k] = heap[j];
    heap_index[heap[j]] = k;
    k = j;
  }
  heap[k] = v;
  heap_index[v] = k;
}
void upheap(int j)
{
  int k, v = heap[j];
  while (j > 0) {
    k = (j + 1) / 2 - 1;
    if (dist[v] >= dist[heap[k]]) break;
    heap[j] = heap[k];
    heap_index[heap[k]] = j;
    j = k;
  }
  heap[j] = v;
  heap_index[v] = j;
}
void PQ_Init(int size)
{
  int i;
  heapsize = size;
  heap = (int*)malloc(sizeof(int) * size);
  heap_index = (int*)malloc(sizeof(int) * size);
  for (i = 0; i < size; i++) {
    heap[i] = i;
    heap_index[i] = i;
  }
  for (i = size / 2 - 1; i >= 0; i--) {
    downheap(i);
  }
}
void DijkstraPQ(int p, int size)
{
  int i;
  for (i = 0; i < size; i++) dist[i] = INT_MAX;
  for (i = 0; i < size / 2; i++) prev[i] = -1;
  dist[p] = 0;
  PQ_Init(size);
  while (heapsize > 0) {
    struct node *n;
    int u = heap[0];
    heap[0] = heap[heapsize - 1];
    heap_index[heap[heapsize - 1]] = 0;
    heapsize--;
    downheap(0);
    for (n = list[u%(size/2)]; n != NULL; n = n->next) {
      long int w = n->weight, newlen2 = dist[u] + w;
      if (newlen2 < dist[n->id]) {
        int temp = newlen2;
        newlen2 = dist[n->id];
        dist[n->id] = temp;
        upheap(heap_index[n->id]);
      }
      if (newlen2 < dist[n->id+size/2]) {
        dist[n->id+size/2] = newlen2;
        upheap(heap_index[n->id+size/2]);
      }
    }
  }
}

