	cell Heap[maxN];
	fscanf(stdin, "%d%d%d", &N, &M, &v0);
	for (int i = 0; i < N; i++)
	{
		for (int j = 0; j < N; j++)
		{
			Lmat[i][j] = INF;
		}
	}

	for (int i = 0; i < M; i++)
	{
		fscanf(stdin, "%d%d%d", &u, &v, &len);
		Lmat[u][v] = len;
	}



	for (int i = 0; i < N; i++)
	{
		d[i] = INF;
		p[i] = -1;
		adr[i] = -1;

	}
	d[v0] = 0;
	hsize = 1;
	insert(Heap, adr, hsize, d[v0], v0);

	while (hsize != 0)
	{
		v = delete_min(Heap, adr, hsize);
		hsize--;
		for (int w = 0; w < N; w++)
		{
			if (Lmat[v][w] == INF)continue;
			if (d[w] == INF)
			{
				d[w] = d[v] + Lmat[v][w];
				p[w] = v;
				hsize++;
				insert(Heap, adr, hsize, d[w], w);
			}
			else if (d[w] > d[v] + Lmat[v][w])
			{
				d[w] = d[v] + Lmat[v][w];
