void Make_AdjList(list* L[],int s,int t,int d){
	list *new=malloc(sizeof(list));
	list **p=&L[s];
	/*card作成*/
	new->id=t;	new->cost=d;  new->next=NULL;

	while((*p)!=NULL)p=&((*p)->next);
	(*p)=new;

	return;
}

void swap(int x,int y){
	int temp;

	temp=heap_id[x];
	heap_id[x]=heap_id[y];
	heap_id[y]=temp;

	temp=id_heap[heap_id[x]];
	id_heap[heap_id[x]]=id_heap[heap_id[y]];
	id_heap[heap_id[y]]=temp;

	return;
}

int check(int i,int num){
	if(num%2==1){
		if((num-1)/2<=i && i<num)return 0;
	}
	else {
		if(num/2 <=i && i<num)return 0;
	}

	return 1;
}

void heap_updata(node N[],int i,int num){


	while(i>=0){

		if(i==0){
			if(N[heap_id[1]].cost <N[heap_id[2]].cost){
				if(N[heap_id[0]].cost > N[heap_id[1]].cost){
					swap(0,1);
					i=MIN(1,num-1);
				}
				else break;
			}
			else {
				if(N[heap_id[0]].cost > N[heap_id[2]].cost){
					swap(0,2);
					i=MIN(2,num-1);
				}
				else break;
			}


		else if(i%2==0){
			if(N[heap_id[i]].cost < N[heap_id[i/2-1]].cost){
				swap(i,i/2-1);
				if(check(i,num))i=MIN(i*2+2,num-1);
			}
			else i--;
		}else {
			if(N[heap_id[i]].cost < N[heap_id[i/2]].cost){
				swap(i,i/2);
				if(check(i,num))i=MIN(i*2+2,num-1);
			}
			else i--;
		}
	}

	return;

}


int Dijkstra(list* L[],node N[],int num){
	int u=heap_id[0];
	list *p=L[u];

	swap(0,num-1);
	num--;
	/*heap_updata(N,num-1,num);*/

	while(p!=NULL){
		if(N[p->id].cost > N[u].cost+(p->cost)){
			N[p->id].cost=N[u].cost+(p->cost);
			heap_updata(N,id_heap[p->id],num);
		}
		p=p->next;
	}

	return num;

}

