	new->next=NULL;
	return new;
}

void Insert(int s,edge* new){
	edge **p=&E[s];

	while((*p)!=NULL){
		p=&((*p)->next);
	}
	(*p)=new;

	return;
}

void swap(int a,int b){
	node *temp; int TEMP;
	temp=H[a];
	H[a]=H[b];
	H[b]=temp;

	TEMP=H[a]->heapid;
	H[a]->heapid=H[b]->heapid;
	H[b]->heapid=TEMP;
	return;
}


void heap_reconst(int x){
	int i;
	i=x;
	for(i=x;i>0;i--){
		if(i%2==0){
			if(H[i]->cost < H[i/2-1]->cost){
				swap(i,i/2-1);

			}

		}
		else {
			if(H[i]->cost < H[i/2]->cost){
				swap(i,i/2);

			}

		}
	}

	return;
}


void Dijkstra(int start,int rest){
	int min_idx=-1;
	int i;
	edge *p;

	if(rest==0)return;

	if(rest==V){
		H[0]->cost=0;
		H[0]->flg=1;
	}
	swap(0,rest-1);


	p=E[start];

	while(p!=NULL){
		if(N[p->to_node].flg==0){
			if(N[p->to_node].cost > N[start].cost+(p->cost)){
				N[p->to_node].cost=N[start].cost+(p->cost);

			}
		}
		p=p->next;
	}
	heap_reconst(rest-2);
	min_idx=H[0]->id;

	N[min_idx].flg=1;

	Dijkstra(min_idx,rest-1);

	return;

}


int main(){
	int start;
	int s,t,d;
	int n,e;
	int i,j;
	int rest;
	edge* new;

	scanf("%d %d %d",&V,&e,&start);

	/*初期化*/
	for(i=0;i<V;i++){
		E[i]=NULL;
		N[i].cost=INF;
		N[i].id=i;
		N[i].heapid=i;
		N[i].flg=0;
		H[i]=&N[i];
	}

	/*隣接リスト作成*/
	for(i=0;i<e;i++){
		scanf("%d %d %d",&s,&t,&d);
		new=Make_Edge(t,d);
		Insert(s,new);
	}
	if(e==0)N[start].cost=0;

	swap(start,0);
	rest=V;
	Dijkstra(start,rest);

	for(i=0;i<V;i++){
		if(N[i].cost==INF)printf("INF\n");
		else printf("%d\n",N[i].cost);
	}

	return 0;
}

