int *dijkstra(Edge ***tree, int V, int src) {
  int *dist = xmalloc(sizeof(int) * V);
  for (size_t i = 0; i < V; i++) {
    dist[i] = INF;
  }

  PriorityQueue *pqueue = new_PriorityQueue(cmp_Edge);

  dist[src] = 0;
  pqueue_push(pqueue, new_Edge(src, 0));

  while (!pqueue_empty(pqueue)) {
    Edge *e = pqueue_pop(pqueue);
    int v = e->dst, cost = e->cost;

    if (dist[v] < cost) {
      continue;
    }

    Edge **vec = tree[v];
    for (int i = 0; i < V; i++) {
      Edge *e = vec[i];
      if (dist[v] + e->cost < dist[e->dst]) {
        dist[e->dst] = dist[v] + e->cost;
        pqueue_push(pqueue, new_Edge(e->dst, dist[e->dst]));
      }
    }
  }

  return dist;
}

