void dijkstra(graph *g,int source,int *path){
  int *used=(int *)malloc(sizeof(int)*g->v);
  int i;
  for(i=0;i<g->v;i++){
    path[i]=inf;
    used[i]=0;
  }
  node *h=(node *)malloc(sizeof(node)*(g->e+1));
  h[0].v=0;
  path[source]=0;
  push(h,source,0);
  while(h[0].v>0){
    int v=pop(h);
    if(used[v]) continue;
    used[v]=1;
    int p;
    for(p=g->start[v];p!=-1;p=g->next[p]){
      int u=g->vertex[p];
      if(path[v]+g->cost[p]>=path[u]) continue;
      path[u]=path[v]+g->cost[p];
      push(h,u,path[u]);
    }
  }
  free(h);
  free(used);
  return;
}

