// Mathematics

fun abs(n: Long): Long = Math.abs(n)
fun abs(n: Double): Double = Math.abs(n)
fun max(vararg values: Long) = if (values.isEmpty()) -INF else values.max()!!
fun min(vararg values: Long) = if (values.isEmpty()) INF else values.min()!!
tailrec fun gcd(a: Long, b: Long): Long = if (b == 0L) a else if (a % b == 0L) b else gcd(b, (a % b))
fun lcm(a: Long, b: Long): Long = a / gcd(a, b) * b
fun erathos(n: Long): LongArray {
    val res = LongArray(n.toInt() + 1) { it.toLong() }
    for (i in 2..n) {
        if(i * i > n) break
        for (j in i * i..n step i) {
            if(res[j] == j) res[j] = i
        }
    }
    res[0] = -1L
    res[1] = -1L
    return res
}
fun modAdd(a: Long, b: Long) = if(a + b >= MOD) a + b - MOD else a + b
fun modpow(a: Long, n: Long, p: Long = MOD): Long {
    var res = 1L
    var ar = a
    var nr = n
    while (nr > 0) {
        if ((nr and 1) == 1L) res = res * ar % p
        ar = ar * ar % p
        nr = nr shr 1
    }
    return res
}
fun modinv(a: Long, p: Long = MOD): Long = modpow(a, p - 2, p)
fun ncr(n: Long, r: Long): Long {
    var a = 1L
    var b = 1L
    for (i in 1..r) {
        a = a * (n + 1 - i) % MOD
        b = b * i % MOD
    }
    return modinv(b, MOD) * a % MOD
}

class Combination(private val max: Long) {
    private val fac = longAry(max)
    private val finv = longAry(max)
    private val inv = longAry(max)
    private val p = MOD
    fun init() {
        fac[0] = 1
        fac[1] = 1
        finv[0] = 1
        finv[1] = 1
        inv[1] = 1
        for (i in 2 until max) {
            fac[i] = fac[i - 1] * i % p
            inv[i] = p - inv[p % i] * (p / i) % p;
            finv[i] = finv[i - 1] * inv[i] % p
        }
    }

    fun com(n: Long, r: Long): Long = if (n < r || (n < 0 || r < 0)) 0L else fac[n] * (finv[r] * finv[n - r] % p) % p
}

class Permutation(private val n: Long, private var searched: Long = 0L, private var nextIndex: Long = 0L) {
    private val size = fact(n)
    private val permList = longAry2(size, n)

    private tailrec fun fact(n: Long, ans: Long = 1L): Long {
        return if (n == 0L) ans
        else fact(n - 1, ans * n)
    }

    fun init() {
        create(0, longAry(n), boolAry(n))
    }

    private fun create(num: Long, list: LongArray, flag: Array<Boolean>) {
        if (num == n) {
            permList[searched] = list.copyOf()
            searched++
        }
        for (i in 0 until n) {
            if (flag[i]) continue
            list[num] = i
            flag[i] = true
            create(num + 1, list, flag)
            flag[i] = false
        }
    }

    fun hasNext(): Boolean {
        return if (nextIndex < size) {
            true
        } else {
            nextIndex = 0
            false
        }
    }

    fun nextPerm(): LongArray = permList[nextIndex++]
}


// String

fun zAlgo(s: String): LongArray {
    val n = s.len
    val res = longAry(n)
    var i = 1L
    var j = 0L
    while(i < n) {
        while (i + j < n && s[j] == s[i + j]) j++
        res[i] = j
        if(j == 0L) {
            i++
            continue
        }
        var k = 1L
        while (i + k < n && k + res[k] < j) {
            res[i + k] = res[k]
            k++
        }
        i += k
        j -= k
    }

    return res
}


// Graph

data class Node(val id: Long, var past: Long = -1, val edges: MutableList<Edge> = mutableListOf())
data class Edge(val from: Long, val to: Long, val cost: Long = 1L)

class Graph(
    private val size: Int,
    private val nodes: Array<Node> = Array(size) { Node(it.toLong()) },
    private val edgeList: MutableList<Edge> = mutableListOf()
) {
    fun unite(from: Long, to: Long, cost: Long = 1L, undirected: Boolean = false) {
        nodes[from].edges.add(Edge(from, to, cost))
        edgeList.add(Edge(from, to, cost))
        if(undirected) {
            nodes[to].edges.add(Edge(to, from, cost))
            edgeList.add(Edge(to, from, cost))
        }
    }

    fun bfs(start: Long): LongArray {
        val dist = LongArray(size) { -1L }
        dist[start] = 0L
        val queue = ArrayDeque<Long>()
        queue.add(start)

        while (queue.isNotEmpty()) {
            val now = queue.poll()
            for (edge in nodes[now].edges) {
                if(dist[edge.to] != -1L) continue
                dist[edge.to] = dist[now] + 1L
                queue.add(edge.to)
            }
        }

        return dist
    }

    fun dijkstra(start: Long): LongArray {
        data class Step(val from: Long, val cost: Long)
        val queue = PriorityQueue<Step>(16) {x, y ->
            return@PriorityQueue when {
                x.cost < y.cost -> -1
                x.cost > y.cost -> 1
                else -> 0
            }
        }
        queue.add(Step(start, 0L))
        val dist = LongArray(size) { INF / 2 }
        dist[start] = 0L

        while (queue.isNotEmpty()) {
            val (from, fromCost) = queue.poll()
            if(dist[from] < fromCost) continue
            for (edge in nodes[from].edges) {
                if(dist[edge.to] > dist[from] + edge.cost) {
                    dist[edge.to] = dist[from] + edge.cost
                    queue.add(Step(edge.to, dist[edge.to]))
                }
            }
        }

        return dist
    }

}


