/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskA solver = new TaskA();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskA {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int v = in.nextInt();
            Dijkstra dijkstra = new Dijkstra(v);

            int e = in.nextInt();
            int r = in.nextInt();
            for (int i = 0; i < e; i++) {
                int s = in.nextInt();
                int t = in.nextInt();
                int d = in.nextInt();

                dijkstra.addDirectedEdge(s, t, d);
            }

            int[] dist = dijkstra.getDist(r);
            for (int x : dist) {
                out.println(x >= Integer.MAX_VALUE / 3 ? "INF" : x);
            }
        }

    }

    static class Dijkstra {
        int n;
        ArrayList<Pair>[] G;
        int INF = Integer.MAX_VALUE / 3;

        public Dijkstra(int n) {
            this.n = n;
            G = new ArrayList[n];
            for (int i = 0; i < n; i++) {
                G[i] = new ArrayList<>();
            }
        }

        public void addDirectedEdge(int from, int to, int cost) {
            G[from].add(new Pair(to, cost));
        }

        public int[] getDist(int s) {
            PriorityQueue<Pair> Q = new PriorityQueue<>();
            Q.add(new Pair(s, 0));
            int[] dist = new int[n];
            Arrays.fill(dist, INF);
            boolean[] used = new boolean[n];
            while (!Q.isEmpty()) {
                Pair p = Q.poll();
                if (used[p.x]) continue;
                used[p.x] = true;
                dist[p.x] = p.y;

                for (Pair edge : G[p.x]) {
                    Q.add(new Pair(edge.x, p.y + edge.y));
                }
            }
            return dist;
        }

        class Pair implements Comparable<Pair> {
            int x;
            int y;

            Pair(int x, int y) {
                this.x = x;
                this.y = y;
            }

            public int compareTo(Pair p) {
                return y - p.y;
            }

        }

    }

    static class InputReader {
        BufferedReader in;
        StringTokenizer tok;

        public String nextString() {
            while (!tok.hasMoreTokens()) {
                try {
                    tok = new StringTokenizer(in.readLine(), " ");
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
            }
            return tok.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextString());
        }

        public InputReader(InputStream inputStream) {
            in = new BufferedReader(new InputStreamReader(inputStream));
            tok = new StringTokenizer("");
        }

    }
}

import java.util.*;
import java.io.*;

class Main {

	static final int INF = Integer.MAX_VALUE/2;

	public static void main(String[] args) throws IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

		String line = br.readLine();
		String[] str = line.split(" ");

		int V = Integer.parseInt(str[0]);
		int E = Integer.parseInt(str[1]);
		int r = Integer.parseInt(str[2]);

		PriorityQueue<Edge> pQue = new PriorityQueue<Edge>(11,COMPARATOR);

		for (int i=0; i<E; i++) {
			line = br.readLine();
			str = line.split(" ");
			int s = Integer.parseInt(str[0]);
			int t = Integer.parseInt(str[1]);
			int d = Integer.parseInt(str[2]);
			Edge edge = new Edge(s,t,d);
			pQue.add(edge);
		}

		List<List<Edge>> Ed = new ArrayList<List<Edge>>();
		int count = 0;

		while (pQue.size() != 0) {
			List<Edge> list = new ArrayList<Edge>();
			while (pQue.peek().from == count) {
				list.add(pQue.poll());
				if (pQue.size() == 0)
					break;
			}
			Ed.add(list);
			count++;
		}

		boolean[] flag = new boolean[V];
		flag[r] = true;

		int[] d = new int[V];
		Arrays.fill(d,INF);
		d[r] = 0;

		int now = r;
		count = 0;

		while (true) {
			List list = Ed.get(now);
			for (int i=0; i<list.size(); i++) {
				Edge edge = (Edge)list.get(i);
				if (!flag[edge.to])
					d[edge.to] = Math.min(d[edge.to],d[now]+edge.cost);
				count++;
			}

			if (count == E)
				break;

			int min = INF;
			for (int i=0; i<V; i++) {
				if (!flag[i] && d[i]<min){
					min = d[i];
					now = i;
				}
			}
			flag[now] = true;
		}

		for (int i=0; i<V; i++) {
			System.out.println((d[i]==INF?"INF":d[i]));
		}

		br.close();
	}

	static class Edge {
		int from;
		int to;
		int cost;

		Edge(int from,int to,int cost){
			this.from = from;
			this.to = to;
			this.cost = cost;
		}
	}

	public static final Comparator<Edge> COMPARATOR = new Comp();

	private static class Comp implements Comparator<Edge>{
		public int compare(Edge x,Edge y){
			return (x.from > y.from) ? 1 : ((x.from == y.from) ? 0 : -1);
		}
	}
}

import java.util.*;

public class Main{

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int v = sc.nextInt();
        int e = sc.nextInt();
        int r = sc.nextInt();
        int[][][] g = buildDirectedWeightedGraph(sc, v, e);
        long[] d = dijkstra(v, g, r);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < v; i++) {
            sb.append(d[i] == Long.MAX_VALUE ? "INF" : d[i]).append("\n");
        }
        System.out.print(sb.toString());
        sc.close();

    }

    public static int[][][] buildDirectedWeightedGraph(Scanner sc, int n, int m) {
        int[][][] graph = new int[n][][];
        int[][] edges = new int[m][3];
        int[] deg = new int[n];
        for (int i = 0; i < m; i++) {
            int a = sc.nextInt();
            int b = sc.nextInt();
            int c = sc.nextInt();
            edges[i][0] = a;
            edges[i][1] = b;
            edges[i][2] = c;
            deg[a]++;
        }
        for (int i = 0; i < n; i++) {
            graph[i] = new int[deg[i]][2];
        }
        for (int i = 0; i < m; i++) {
            int a = edges[i][0];
            int b = edges[i][1];
            int c = edges[i][2];
            graph[a][--deg[a]] = new int[]{b, c};
        }

        return graph;
    }


    public static long[] dijkstra(int n, int[][][] graph, int s) {
        // {sからの最短距離, 頂点}
        PriorityQueue<long[]> pq = new PriorityQueue<long[]>((x, y) -> Long.compare(x[0], y[0]));
        long[] d = new long[n]; // sからの最短距離
        Arrays.fill(d, Long.MAX_VALUE);
        d[s] = 0;
        pq.add(new long[] { 0, s });
        while (!pq.isEmpty()) {
            long[] a = pq.poll();
            int v = (int) a[1];
            if (d[v] < a[0])
                continue;
            for (int[] g : graph[v]) {
                int to = g[0];
                int cost = g[1];
                if (d[to] > d[v] + cost) {
                    d[to] = d[v] + cost;
                    pq.add(new long[] { d[to], to });
                }
            }
        }

        return d;
    }
}

