final class IO {
	private static final InputStream in = System.in;
	private static final PrintWriter out = new PrintWriter(System.out, false);
	private static final byte[] buffer = new byte[1024];
	private static int ptr = 0;
	private static int len = 0;

	private static boolean hasNextByte() {
		if (ptr < len)
			return true;
		ptr = 0;
		try {
			len = in.read(buffer);
		} catch (IOException e) {
			e.printStackTrace();
		}
		return len > 0;
	}

	private static int readByte() {
		if (hasNextByte())
			return buffer[ptr++];
		else
			return -1;
	}

	static boolean hasNext() {
		byte c;
		while (hasNextByte() && ((c = buffer[ptr]) < '!' || c > '~'))
			ptr++;
		return hasNextByte();
	}

	static String next() {
		if (!hasNext())
			throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while (b >= '!' && b <= '~') {
			sb.append((char) b);
			b = readByte();
		}
		return sb.toString();
	}

	static char nextChar() {
		if (!hasNext())
			throw new NoSuchElementException();
		return (char) readByte();
	}

	static long nextLong() {
		if (!hasNext())
			throw new NoSuchElementException();
		long n = 0;
		int sign = 1;
		int b = readByte();
		if (b == '-') {
			sign = -1;
			b = readByte();
		}
		if (b < '0' || '9' < b)
			throw new NumberFormatException();
		while (true) {
			if ('0' <= b && b <= '9')
				n = n * 10 + b - '0';
			else if (b == -1 || b < '!' || b > '~')
				return n * sign;
			else
				throw new NumberFormatException();
			b = readByte();
		}
	}

	static int nextInt() {
		if (!hasNext())
			throw new NoSuchElementException();
		int n = 0;
		int sign = 1;
		int b = readByte();
		if (b == '-') {
			sign = -1;
			b = readByte();
		}
		if (b < '0' || '9' < b)
			throw new NumberFormatException();
		while (true) {
			if ('0' <= b && b <= '9')
				n = n * 10 + b - '0';
			else if (b == -1 || b < '!' || b > '~')
				return n * sign;
			else
				throw new NumberFormatException();
			b = readByte();
		}
	}

	static double nextDouble() {
		return Double.parseDouble(next());
	}

	static void out(String val) {
		out.println(val);
	}

	static void flush() {
		out.flush();
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

class Edge{
	int u,v;
	int weight;
}

public class Main{
	int nodenum, edgenum, source;
	int[] dist;
	Edge[] edge;
	public static void main(String[] args) throws IOException{
		Main f = new Main();
		f.init();
		if (f.Bellman_Ford()){
			for(int i=0;i<f.nodenum;i++){
				if(f.dist[i]==500000000){
					System.out.println("INF");
				}else{
					System.out.println(f.dist[i]);
				}
			}
		}
	}
	public void init() throws IOException{
		BufferedReader BR = new BufferedReader(new InputStreamReader(System.in));
		String str = BR.readLine();
		String [] arr = str.split("\\s+");
		this.nodenum = Integer.parseInt(arr[0]);
		this.edgenum = Integer.parseInt(arr[1]);
		this.source = Integer.parseInt(arr[2]);
		dist = new int[nodenum];
		edge = new Edge[edgenum];
		for(int i=0;i<edgenum;i++){
			edge[i] = new Edge();
		}
		for(int i=0;i<nodenum;i++){
			dist[i] = 500000000;
		}
		dist[source] = 0;
		for(int i=0;i<edgenum;i++){
			String tempstr = BR.readLine();
			String [] temparr = tempstr.split("\\s+");
			int p1 = Integer.parseInt(temparr[0]);
			int p2 = Integer.parseInt(temparr[1]);
			int w = Integer.parseInt(temparr[2]);
			edge[i].u = p1;
			edge[i].v = p2;
			edge[i].weight = w;
			if(edge[i].u == source){
				dist[edge[i].v] = edge[i].weight;
			}
		}
	}

	public void relax(int u, int v, int weight){
		if(dist[v]>dist[u] + weight){
			//System.out.println(dist[v]+" "+dist[u]+" "+weight);
			dist[v] = dist[u] + weight;
			//System.out.println(dist[v]);
		}
	}

	public boolean Bellman_Ford(){
		for(int i=0;i<nodenum-1;i++){
			for(int j=0;j<edgenum; j++){
				relax(edge[j].u, edge[j].v, edge[j].weight);
			}
		}
		boolean flag = true;
		for(int i=0;i<edgenum;i++){
			if(dist[edge[i].v] > dist[edge[i].u] + edge[i].weight){
				flag = false;
				break;
			}
		}
		return flag;
	}
}

