			int s = sc.nextInt();
			int t = sc.nextInt();
			int d = sc.nextInt();
			adj[s].add(new Edge(t, d));
		}
		dijkstra(r);
		for(int i=0; i<V; i++) {
			if(dist[i] == INF) {
				System.out.println("INF");
			} else {
				System.out.println(dist[i]);
			}
		}
	}

