            int w = in.nextInt();
            dijkstra.addEdge(p, q, w);
        }

        ArrayList<Integer> distance = dijkstra.shortestPath(s);
        for (Integer d: distance)
            System.out.println(d == -1 ? "INF" : d);
    }
}

