      for(int i = 0; i < e; i++){
        int from = scanner.nextInt();
        int to = scanner.nextInt();
        T weight = nextWeight.apply(scanner);
        edges.get(from).add(new MyEdge<>(from, to, weight));
        edges.get(to).add(new MyEdge<>(to, from, weight));
      }
    }
  }
  /**
   * ??????????????£??\??????????????????
   * @param id ????????????
