class FastScanner {
// ????????¨???
public FastScanner(InputStream in_){in = in_;}
// ????????¨??????????????§
private final InputStream in;
private final byte[] buffer = new byte[1024];
private int ptr = 0;
private int buflen = 0;
private boolean hasNextByte() {
 if (ptr < buflen) {
   return true;
 }else{
   ptr = 0;
   try {
     buflen = in.read(buffer);
   } catch (IOException e) {
     e.printStackTrace();
   }
   if (buflen <= 0) {
     return false;
   }
 }
 return true;
}
private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
public String next() {
 if (!hasNext()) throw new NoSuchElementException();
 StringBuilder sb = new StringBuilder();
 int b = readByte();
 while(isPrintableChar(b)) {
   sb.appendCodePoint(b);
   b = readByte();
 }
 return sb.toString();
}
public long nextLong() {
 if (!hasNext()) throw new NoSuchElementException();
 long n = 0;
 boolean minus = false;
 int b = readByte();
 if (b == '-') {
   minus = true;
   b = readByte();
 }
 if (b < '0' || '9' < b) {
   throw new NumberFormatException();
 }
 while(true){
   if ('0' <= b && b <= '9') {
     n *= 10;
     n += b - '0';
   }else if(b == -1 || !isPrintableChar(b)){
     return minus ? -n : n;
   }else{
     throw new NumberFormatException();
   }
   b = readByte();
 }
}
public int nextInt() {
 long nl = nextLong();
 if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
 return (int) nl;
}
public double nextDouble() { return Double.parseDouble(next());}
}

import java.util.*;

class ProblemC{
  int[] d = null;//sからの最短経路
  ArrayList<ArrayList<Edge>> g = new ArrayList<ArrayList<Edge>>();
  int inf = 1000000;

  void solve(){
    Scanner scan = new Scanner(System.in);
    int v = scan.nextInt();
    int e = scan.nextInt();
    int r = scan.nextInt();

    d = new int[v];

    for(int i=0 ; i<v ; ++i){
      g.add(new ArrayList<Edge>());
    }

    for(int i=0 ; i<e ; ++i){
      int s = scan.nextInt();
      int t = scan.nextInt();
      int d = scan.nextInt();
      g.get(s).add(new Edge(t, d));
    }

    dijkstra(r, v);

    for(int i=0 ; i<d.length ; ++i){
      if(d[i] == inf) System.out.println("INF");
      else System.out.println(d[i]);
    }

  }

  void dijkstra(int r, int vn){
    PriorityQueue<IntPair> que = new PriorityQueue<IntPair>();
    for(int i=0 ; i<vn ; ++i) d[i] = inf;
    d[r] = 0;
    que.add(new IntPair(0, r));
    while(!que.isEmpty()){
      IntPair p = que.poll();//IntPair(Key:頂点番号, Value:最短距離)
      int v = p.value;//頂点番号
      if(d[v] < p.key) continue;
      for(int i=0 ; i<g.get(v).size() ; ++i){

        Edge e = g.get(v).get(i);
        if(d[e.to] > d[v] + e.cost){
          d[e.to] = d[v] + e.cost;
          que.add(new IntPair(d[e.to], e.to));
        }
      }
    }//----end of while----
  }//----end of dijkstra----
}

