			for(int k=0; k<v; k++) {
				boolean update=false;
				for(int i=0; i<v; i++) {
					for(int j=0; j<v; j++) {
						if(c[i]<inf && w[i][j]>0) {
							if(c[j]>c[i]+w[i][j]) {
								c[j]=c[i]+w[i][j];
								update=true;
							}
						}
					}
				}
				if(! update) break;
			}
			for(int i=0; i<v; i++) {
