    for(int i : shortDist) {
      if(i == INF) {
        System.out.println("INF");
      } else System.out.println(i);
    }
  }

  static void dijkstra() {
    while(true) {
      int u = getMin();
      if(u == -1) {
        break;
      }
      if(shortDist[u] == INF) {
        break;
      }
      visited[u] = true;
      for(int i = 0 ; i < v ; i++) {
        if(adjArr[u][i] > 0) {
          int neighbor = i;
          int wei = adjArr[u][i];
          int newL = shortDist[u] + wei;
          if(newL < shortDist[neighbor]) {
            shortDist[neighbor] = newL;
          }
        }
      }
    }
  }

  // startから最小の距離の頂点取得
  static int getMin() {
    int tmp = INF;
    for(int i = 0 ; i < v ; i++) {
      if(visited[i] == false && shortDist[i] < tmp) {
        tmp = i;
      }
    }
    if(tmp == INF) {
      tmp = -1;
    }
    return tmp;
  }

}

