    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);

        int V = in.nextInt();
        int E = in.nextInt();
        int r =  in.nextInt();

        int a[][] = new int[V][V];

        for (int i = 0; i < V; i++){
