public class Main {
	private static FastScanner sc = new FastScanner();
	static Node[] V;

	public static void main(String[] args) {
		int Vn = sc.nextInt();
		int En = sc.nextInt();
		int r = sc.nextInt();

		V = new Node[Vn]; 
		for(int i=0; i<Vn; i++) {
			V[i] = new Node();
		}

		for(int i=0; i<En; i++) {
			int s = sc.nextInt();
			int t = sc.nextInt();
			int d = sc.nextInt();
			V[s].nbr.add(new Edge(t, d));
		}

		PriorityQueue<Node> cdt = new PriorityQueue<>((a, b) -> a.min - b.min);
		cdt.add(V[r]);
		V[r].min = 0;

		while(!cdt.isEmpty()) {
			Node n = cdt.poll();
			for(Edge e : n.nbr) {
				if(n.min + e.d < V[e.t].min) {
					V[e.t].min = n.min + e.d;
					if(cdt.contains(V[e.t])) {
						cdt.remove(V[e.t]);
					}
					cdt.add(V[e.t]);
				}
			}
		}

		StringBuilder ans = new StringBuilder();
		for(int i=0; i<Vn; i++) {
			if(V[i].min == Integer.MAX_VALUE) {
				ans.append("INF");
			} else {
				ans.append(V[i].min);
			}
			ans.append("\n");
		}
		System.out.print(ans);
	}

	static class Node {
		int min = Integer.MAX_VALUE;
		Set<Edge> nbr = new HashSet<>();
	}

	static class Edge {
		int t;
		int d;

		Edge(int t, int d) {
			this.t = t;
			this.d = d;
		}
	}

	static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;
        private boolean hasNextByte() {
            if(ptr < buflen) {
                return true;
            } else {
                ptr = 0;
                try {
                    buflen = in.read(buffer);
                } catch(IOException e) {
                    e.printStackTrace();
                }
                if(buflen <= 0) {
                    return false;
                }
            }
            return true;
        }
        private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
        private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
        private void skipUnprintable() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;}
        public boolean hasNext() { skipUnprintable(); return hasNextByte();}
        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while(isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }
        public long nextLong() {
            return Long.parseLong(next());
        }
        public int nextInt(){
            return Integer.parseInt(next());
        }
        public double nextDouble(){
            return Double.parseDouble(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.PriorityQueue;

public class Dijkstra {

    static class edge{
        int from, to, cost;
    }

    public static void main(String[] args) throws IOException{
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] str = br.readLine().split(" ");
        int v = Integer.parseInt(str[0]);
        int e = Integer.parseInt(str[1]);
        int r = Integer.parseInt(str[2]);

        ArrayList[] es = new ArrayList[v];
        for(int i=0; i<v; i++) es[i] = (new ArrayList<edge>());

        for (int i=0; i<e; i++){
            str = br.readLine().split(" ");
            edge ed = new edge();
            ed.from = Integer.parseInt(str[0]);
            ed.to = Integer.parseInt(str[1]);
            ed.cost = Integer.parseInt(str[2]);
            es[ed.from].add(ed);
        }

        PriorityQueue dist = new PriorityQueue<long[]>((long[] le, long[] ri) -> (int)(le[0] - ri[0]));
        long[] vertex = new long[2];
        vertex[0] = 0;
        vertex[1] = r;
        dist.add(vertex);

        long[] len = new long[v];
        Arrays.fill(len, Long.MAX_VALUE);
        len[r] = 0;

        while(!dist.isEmpty()){
            vertex = (long[])dist.poll();

            long u = vertex[1];
            for (Object ed: es[(int)u]){
                if(len[((edge) ed).from] + ((edge) ed).cost < len[((edge) ed).to]) {
                    len[((edge) ed).to] = len[((edge) ed).from] + ((edge) ed).cost;
                    long[] p = new long[2];
                    p[0] = len[((edge) ed).to];
                    p[1] = ((edge) ed).to;
                    dist.add(p);
                }
            }
        }

        for(int i=0; i<v; i++){
            if(len[i] == Long.MAX_VALUE){
                System.out.println("INF");
            } else {
                System.out.println(len[i]);
            }
        }
    }
}

