private static void BellmanFord(int e,int r,Edge[] es,int[] d){
Arrays.fill(d,INF);
d[r]=0;
while(true){
boolean update=false;
for(int i=0;i<e;i++){
Edge e=es[i];
if(d[e.to]>d[e.from]+d[e.cost]){
d[e.to]=d[e.from]+d[e.cost];
update=true;
}
}
if(!update) break;
}
}
