final class IO {
	private static final InputStream in = System.in;
	private static final PrintWriter out = new PrintWriter(System.out, false);
	private static final byte[] buffer = new byte[1024];
	private static int ptr = 0;
	private static int len = 0;

	private static boolean hasNextByte() {
		if (ptr < len)
			return true;
		ptr = 0;
		try {
			len = in.read(buffer);
		} catch (IOException e) {
			e.printStackTrace();
		}
		return len > 0;
	}

	private static int readByte() {
		if (hasNextByte())
			return buffer[ptr++];
		else
			return -1;
	}

	static boolean hasNext() {
		byte c;
		while (hasNextByte() && ((c = buffer[ptr]) < '!' || c > '~'))
			ptr++;
		return hasNextByte();
	}

	static String next() {
		if (!hasNext())
			throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while (b >= '!' && b <= '~') {
			sb.append((char) b);
			b = readByte();
		}
		return sb.toString();
	}

	static char nextChar() {
		if (!hasNext())
			throw new NoSuchElementException();
		return (char) readByte();
	}

	static long nextLong() {
		if (!hasNext())
			throw new NoSuchElementException();
		long n = 0;
		int sign = 1;
		int b = readByte();
		if (b == '-') {
			sign = -1;
			b = readByte();
		}
		if (b < '0' || '9' < b)
			throw new NumberFormatException();
		while (true) {
			if ('0' <= b && b <= '9')
				n = n * 10 + b - '0';
			else if (b == -1 || b < '!' || b > '~')
				return n * sign;
			else
				throw new NumberFormatException();
			b = readByte();
		}
	}

	static int nextInt() {
		if (!hasNext())
			throw new NoSuchElementException();
		int n = 0;
		int sign = 1;
		int b = readByte();
		if (b == '-') {
			sign = -1;
			b = readByte();
		}
		if (b < '0' || '9' < b)
			throw new NumberFormatException();
		while (true) {
			if ('0' <= b && b <= '9')
				n = n * 10 + b - '0';
			else if (b == -1 || b < '!' || b > '~')
				return n * sign;
			else
				throw new NumberFormatException();
			b = readByte();
		}
	}

	static double nextDouble() {
		return Double.parseDouble(next());
	}

	static void out(String val) {
		out.println(val);
	}

	static void flush() {
		out.flush();
	}
}

import java.util.*;

class Main {
  static final int INF = 99999999;
  static class Vertex implements Comparable<Vertex> {
    List<Route> routes = new ArrayList<Route>();
    int cost = INF;

    public void addRoute(Vertex to, int dist) {
      routes.add(new Route(this, to, dist));
    }

    public int compareTo(Vertex o) {
      return cost - o.cost;
    }
  }

  static class Route {
    Vertex from;
    Vertex to;
    int weight;

    public Route(Vertex from, Vertex to, int weight) {
      this.from = from;
      this.to = to;
      this.weight = weight;
    }
  }

  public static void main(String[] args) {
    Scanner scan = new Scanner(System.in);
    int v = scan.nextInt();
    int e = scan.nextInt();
    int sP = scan.nextInt();

    Vertex[] vertexArr = new Vertex[v];

    for(int i = 0 ; i < v ; i++) {
      vertexArr[i] = new Vertex();
    }

    int start;
    int end;
    int weight;
    for(int i = 0 ; i < e ; i++) {
      start = scan.nextInt();
      end = scan.nextInt();
      weight = scan.nextInt();
      vertexArr[start].addRoute(vertexArr[end], weight);
    }

    vertexArr[sP].cost = 0;

    PriorityQueue<Vertex> pq = new PriorityQueue<Vertex>(Arrays.asList(vertexArr));
    while (!pq.isEmpty()) {
      Vertex s = pq.poll();
      for (Route route : s.routes) {
        Vertex to = route.to;
        int cost = s.cost + route.weight;
        if (cost < to.cost) {
          pq.remove(to);
          to.cost = cost;
          pq.add(to);
        }
      }
    }

    for (Vertex s : vertexArr) {
      if(s.cost == INF) {
        System.out.println("INF");
      } else System.out.println(s.cost);
    }
  }
}

