 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastScanner in = new FastScanner(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        ShortestPathDijkstra solver = new ShortestPathDijkstra();
        solver.solve(1, in, out);
        out.close();
    }

    static class ShortestPathDijkstra {
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int V = in.nextInt();
            int E = in.nextInt();
            int r = in.nextInt();
            final int INF = Integer.MAX_VALUE;
            List<Edge>[] g = new List[V];
            Arrays.setAll(g, i -> new ArrayList<>());
            int[] d = new int[V];
            Arrays.fill(d, INF);
            d[r] = 0;
            for (int i = 0; i < E; i++) {
                int v = in.nextInt();
                g[v].add(new Edge(in.nextInt(), in.nextInt()));
            }
            Comparator<Pair> c = Comparator.comparingInt(x -> x.first);
            PriorityQueue<Pair> pairs = new PriorityQueue<>(c);
            pairs.offer(new Pair(0, r));
            while (!pairs.isEmpty()) {
                Pair p = pairs.poll();
                int v = p.second;
                for (int i = 0; i < g[v].size(); i++) {
                    Edge e = g[v].get(i);
                    if (d[v] != INF && d[e.to] > d[v] + e.cost) {
                        d[e.to] = d[v] + e.cost;
                        pairs.offer(new Pair(d[e.to], e.to));
                    }
                }
            }
            for (int i = 0; i < V; i++) {
                if (d[i] == INF) out.println("INF");
                else out.println(d[i]);
            }

        }

        class Edge {
            public int to;
            public int cost;

            public Edge(int end, int cost) {
                this.to = end;
                this.cost = cost;
            }

        }

        class Pair {
            public int first;
            public int second;

            public Pair(int first, int second) {
                this.first = first;
                this.second = second;
            }

            public boolean equals(Object o) {
                if (this == o) return true;
                if (o == null || getClass() != o.getClass()) return false;
                Pair pair = (Pair) o;
                return first == pair.first &&
                        second == pair.second;
            }

            public int hashCode() {
                return Objects.hash(first, second);
            }

        }

    }

    static class FastScanner implements Closeable {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private boolean hasNextByte() {
            if (ptr < buflen) {
                return true;
            } else {
                ptr = 0;
                try {
                    buflen = in.read(buffer);
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (buflen <= 0) {
                    return false;
                }
            }
            return true;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            else return -1;
        }

        private static boolean isPrintableChar(int c) {
            return 33 <= c && c <= 126;
        }

        public boolean hasNext() {
            while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;
            return hasNextByte();
        }

        public long nextLong() {
            if (!hasNext()) throw new NoSuchElementException();
            long n = 0;
            boolean minus = false;
            int b = readByte();
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            if (b < '0' || '9' < b) {
                throw new NumberFormatException();
            }
            while (true) {
                if ('0' <= b && b <= '9') {
                    n *= 10;
                    n += b - '0';
                } else if (b == -1 || !isPrintableChar(b)) {
                    return minus ? -n : n;
                } else {
                    throw new NumberFormatException();
                }
                b = readByte();
            }
        }

        public int nextInt() {
            long nl = nextLong();
            if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
            return (int) nl;
        }

        public void close() {
            try {
                in.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

    }
}

