						c[t]=c[s]+d;
						update=true;
					}
				}
				if(! update) break;
			}
			for(int i=0; i<v; i++) {
				if(c[i]==inf) {
					System.out.println("INF");
				}
				else {
					System.out.println(c[i]);
				}
			}
		}
	}
}

