public class Main {

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);

        int V = in.nextInt();
        int E = in.nextInt();
        int r =  in.nextInt();

        int a[][] = new int[V][V];

        for (int i = 0; i < V; i++){
            for (int j = 0; j < V; j++){
                a[i][j] =  -1;
            }
        }

        for (int i = 0; i < E; i++){
            int s = in.nextInt();
            int t = in.nextInt();
            int d = in.nextInt();
                a[s][t] = d;
        }

        int[] distance = new int[V];
        dijkstra(a,r,distance);
        for (int i = 0; i < V; i++){
            if (distance[i]==Integer.MAX_VALUE) {
                System.out.print("INF");
            } else {
                System.out.println(distance[i]);
            }
        }
    }

    public static void dijkstra(int[][] map,int src,int[] distance) {
        int V = distance.length;
	    boolean[] fixed = new boolean[V]; 
        for (int i=0; i<V; i++) {
            distance[i] = Integer.MAX_VALUE;
            fixed[i] = false;
        }
        distance[src] = 0;
        while (true) {
            int marked = minIndex(distance,fixed);
            if (marked < 0) return; 
            if (distance[marked]==Integer.MAX_VALUE) return;
            fixed[marked] = true; 
            for (int j=0; j<V; j++) { 
                if (map[marked][j]>0 && !fixed[j]) {

                    int newDistance = distance[marked]+map[marked][j];

                    if (newDistance < distance[j]) distance[j] = newDistance;
                }
            }
        }
    }

    static int minIndex(int[] distance,boolean[] fixed) {
        int idx=0;
        for (; idx<fixed.length; idx++)	
            if (!fixed[idx]) break;
	    if (idx == fixed.length) return -1; 
        for (int i=idx+1; i<fixed.length; i++) 
            if (!fixed[i] && distance[i]<distance[idx]) idx=i;
        return idx;
    }

}

import java.util.ArrayList;
import java.util.List;
import java.util.PriorityQueue;
import java.util.Scanner;


public class Main {

	static class State { // →bの辺の重さw
		int b, w;
		public State(int b, int w) {
			this.b = b;
			this.w = w;
		}
	}
	static class PQ implements Comparable<PQ>{
		int now;
		long d;
		public PQ(int now, long d) {
			this.now = now;
			this.d = d;
		}
		public int compareTo(PQ p) {
			return this.d>p.d? 1:-1;
		}
	}

	public static void main(String[] args) throws Exception {
		try(Scanner sc = new Scanner(System.in)) {
			int V = sc.nextInt(); // 頂点数
			int E = sc.nextInt(); // 辺数
			int r = sc.nextInt(); // 初めの頂点
			long INF = 500000*10000+1;

			@SuppressWarnings("unchecked")
			List<State>[] edge = new ArrayList[V];
			for(int i=0; i<V; i++) {
				edge[i] = new ArrayList<State>();
			}
			PriorityQueue<PQ> pq = new PriorityQueue<>();
			for(int i=0; i<E; i++) {
				int s = sc.nextInt();
				int t = sc.nextInt();
				int d = sc.nextInt();
				edge[s].add(new State(t, d));
			}
			long[] dis = new long[V];
			boolean[] processed = new boolean[V];
			for(int i=0; i<V; i++) {
				dis[i] = INF;
				processed[i] = false;
			}

			dis[r] = 0;
			pq.add(new PQ(r, 0));
			while(! pq.isEmpty()) {
				PQ p = pq.poll();
				int a = p.now;
				if(processed[a]) {
					continue;
				}
				processed[a] = true;
				for(State s : edge[a]) {
					if(dis[a]+s.w < dis[s.b]) {
						dis[s.b] = dis[a] + s.w;
						pq.add(new PQ(s.b, dis[s.b]));
					}
				}
			}
			for(int i=0; i<V; i++) {
				if(dis[i] >= INF)	System.out.println("INF");
				else	System.out.println(dis[i]);
			}
		}
	}

}

