private static void BellmanFord(int e,int r,Edge[] es,int[] d){
Arrays.fill(d,INF);
d[r]=0;
while(true){
boolean update=false;
for(int i=0;i<e;i++){
Edge ee=es[i];
if(d[ee.to]>d[ee.from]+d[ee.cost]){
d[ee.to]=d[ee.from]+d[ee.cost];
update=true;
}
}
if(!update) break;
}
}
