@SuppressWarnings("resource")
final class IO {
	private static final InputStream in;

	static {
		InputStream is;
		try {
			is = new FileInputStream(new java.io.File("in.txt"));
			try {
//				System.out.println("sleeping...");
//				Thread.sleep(10000);
//				System.out.println("started.");
			} catch (Exception e) {
			}
		} catch (FileNotFoundException e) {
			is = System.in;
		}
		in = is;
	}

	private static final PrintWriter out = new PrintWriter(System.out, false);
	private static final byte[] buffer = new byte[1024];
	private static int ptr = 0;
	private static int len = 0;

	private static boolean hasNextByte() {
		if (ptr < len)
			return true;
		ptr = 0;
		try {
			len = in.read(buffer);
		} catch (IOException e) {
			e.printStackTrace();
		}
		return len > 0;
	}

	private static int readByte() {
		if (hasNextByte())
			return buffer[ptr++];
		else
			return -1;
	}

	static boolean hasNext() {
		byte c;
		while (hasNextByte() && ((c = buffer[ptr]) < '!' || c > '~'))
			ptr++;
		return hasNextByte();
	}

	static String next() {
		if (!hasNext())
			throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while (b >= '!' && b <= '~') {
			sb.append((char) b);
			b = readByte();
		}
		return sb.toString();
	}

	static char nextChar() {
		if (!hasNext())
			throw new NoSuchElementException();
		return (char) readByte();
	}

	static long nextLong() {
		if (!hasNext())
			throw new NoSuchElementException();
		long n = 0;
		int sign = 1;
		int b = readByte();
		if (b == '-') {
			sign = -1;
			b = readByte();
		}
		if (b < '0' || '9' < b)
			throw new NumberFormatException();
		while (true) {
			if ('0' <= b && b <= '9')
				n = n * 10 + b - '0';
			else if (b == -1 || b < '!' || b > '~')
				return n * sign;
			else
				throw new NumberFormatException();
			b = readByte();
		}
	}

	static int nextInt() {
		if (!hasNext())
			throw new NoSuchElementException();
		int n = 0;
		int sign = 1;
		int b = readByte();
		if (b == '-') {
			sign = -1;
			b = readByte();
		}
		if (b < '0' || '9' < b)
			throw new NumberFormatException();
		while (true) {
			if ('0' <= b && b <= '9')
				n = n * 10 + b - '0';
			else if (b == -1 || b < '!' || b > '~')
				return n * sign;
			else
				throw new NumberFormatException();
			b = readByte();
		}
	}

	static double nextDouble() {
		return Double.parseDouble(next());
	}

	static void out(String val) {
		out.println(val);
	}

	static void flush() {
		out.flush();
	}
}

import java.util.Arrays;
import java.util.Scanner;

class Main{
	public static void main(String args[]){
		try(Scanner sc=new Scanner(System.in)){
			int v=sc.nextInt();//頂点数
			int e=sc.nextInt();//辺数
			int r=sc.nextInt();//始点
			int inf=10000*100000+100;
			int[] c=new int[v+1];//始点からの距離
			int[] S=new int[e+1];
			int[] T=new int[e+1];
			int[] D=new int[e+1];
			Arrays.fill(c, inf);
			Arrays.fill(D, inf);
			for(int i=0; i<e; i++) {
				S[i]=sc.nextInt();
				T[i]=sc.nextInt();
				D[i]=sc.nextInt();
			}
			c[r]=0;
			for(int k=0; k<v; k++) {
				boolean update=false;
				for(int i=0; i<e; i++) {
					int s=S[i], t=T[i], d=D[i];
					if(c[s]<inf && c[s]+d<c[t]) {
						c[t]=c[s]+d;
						update=true;
					}
				}
				if(! update) break;
			}
			for(int i=0; i<v; i++) {
				if(c[i]==inf) {
					System.out.println("INF");
				}
				else {
					System.out.println(c[i]);
				}
			}
		}
	}
}

