public class Main {

    static int vertex;
    static int edges;
    static boolean[] visited;
    static int[] cost;
    static int[] parent;
    static ArrayList<Edge>[] graph;
    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    static final int INFINITY = Integer.MAX_VALUE;
    static Main obj = new Main();

    class Edge implements Comparable<Edge> {

        int from;
        int to;
        int weight;

        public Edge(int from, int to, int weight) {
            this.from = from;
            this.to = to;
            this.weight = weight;
        }

        @Override
        public int compareTo(Edge other) {
            int diff = weight - other.weight;
            return diff;
        }

    }

    public static void main(String[] args) throws IOException {

        input();
        prim();

    }

    @SuppressWarnings("unchecked")
    public static void input() throws IOException {
        StringTokenizer st = new StringTokenizer(br.readLine());
        vertex = Integer.parseInt(st.nextToken());
        edges = Integer.parseInt(st.nextToken());
        visited = new boolean[vertex];
        cost = new int[vertex];
        parent = new int[vertex];
        graph = new ArrayList[vertex];
        for (int i = 0; i < graph.length; i++) {
            graph[i] = new ArrayList<Edge>();
        }
        for (int i = 0; i < edges; i++) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (Exception e) {
                break;
            }
            int a = Integer.parseInt(st.nextToken()) ;
            int b = Integer.parseInt(st.nextToken()) ;
            int c = Integer.parseInt(st.nextToken());

            graph[a].add(obj.new Edge(a, b, c));

        }
        for (int i = 0; i < cost.length; i++) {
            cost[i] = INFINITY;
        }

    }

    public static void prim() {

        int added = 1;
        int sum = 0;
        visited[0] = true;
        cost[0] = 0;
        PriorityQueue<Edge> pq = new PriorityQueue<Edge>();
        for (Edge e : graph[0]) {
            pq.offer(e);
        }
        while (!pq.isEmpty()) {
            Edge e = pq.poll();
            if (visited[e.to]) {
                continue;
            }

            sum += e.weight;
            added++;
            cost[e.to] = e.weight + cost[e.from];
            parent[e.to] = e.from;
            visited[e.to] = true;

            if (added == vertex) {
                break;
            }
            for (Edge q : graph[e.to]) {
                if (visited[q.to]) {
                    continue;
                } else {
                    pq.offer(q);
                }
            }

        }
        for (int i = 0; i < vertex; i++) {
            System.out.println(cost[i]);
        }

    }

}

import java.util.*;
import java.io.*;

class Main {

	static final int INF = Integer.MAX_VALUE/2;

	public static void main(String[] args) throws IOException {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

		String line = br.readLine();
		String[] str = line.split(" ");

		int V = Integer.parseInt(str[0]);
		int E = Integer.parseInt(str[1]);
		int r = Integer.parseInt(str[2]);

		if (E == 0) {
			for (int i=0; i<V; i++) {
				System.out.println(i==r?0:"INF");
			}
			return;
		}

		PriorityQueue<Edge> pQue = new PriorityQueue<Edge>(11,COMPARATOR);

		for (int i=0; i<E; i++) {
			line = br.readLine();
			str = line.split(" ");
			int s = Integer.parseInt(str[0]);
			int t = Integer.parseInt(str[1]);
			int d = Integer.parseInt(str[2]);
			Edge edge = new Edge(s,t,d);
			pQue.add(edge);
		}

		List<List<Edge>> Ed = new ArrayList<List<Edge>>();
		int count = 0;

		while (pQue.size() != 0) {
			List<Edge> list = new ArrayList<Edge>();
			while (pQue.peek().from == count) {
				list.add(pQue.poll());
				if (pQue.size() == 0)
					break;
			}
			Ed.add(list);
			count++;
		}

		boolean[] flag = new boolean[V];
		flag[r] = true;

		int[] d = new int[V];
		Arrays.fill(d,INF);
		d[r] = 0;

		int now = r;
		count = 0;

		while (true) {
			List list = Ed.get(now);
			for (int i=0; i<list.size(); i++) {
				Edge edge = (Edge)list.get(i);
				if (!flag[edge.to])
					d[edge.to] = Math.min(d[edge.to],d[now]+edge.cost);
				count++;
			}

			if (count == E)
				break;

			int min = INF;
			for (int i=0; i<V; i++) {
				if (!flag[i] && d[i]<min){
					min = d[i];
					now = i;
				}
			}
			flag[now] = true;
		}

		for (int i=0; i<V; i++) {
			System.out.println((d[i]==INF?"INF":d[i]));
		}

		br.close();
	}

	static class Edge {
		int from;
		int to;
		int cost;

		Edge(int from,int to,int cost){
			this.from = from;
			this.to = to;
			this.cost = cost;
		}
	}

	public static final Comparator<Edge> COMPARATOR = new Comp();

	private static class Comp implements Comparator<Edge>{
		public int compare(Edge x,Edge y){
			return (x.from > y.from) ? 1 : ((x.from == y.from) ? 0 : -1);
		}
	}
}

