        while ((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-')) ;
        if (b == '-') {
            minus = true;
            b = readByte();
        }

        while (true) {
            if (b >= '0' && b <= '9') {
                num = num * 10 + (b - '0');
            } else {
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private static void tr(Object... o) {
        if (INPUT.length() != 0) System.out.println(Arrays.deepToString(o));
        // System.out.println(Arrays.deepToString(o));
    }
}

class DijkstraMatrix {
    int[][] a;
    boolean[] b;
    PriorityQueue<int[]> q;

    public DijkstraMatrix(int n) {
        a = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                a[i][j] = -1;
            }
        }
        b = new boolean[n];
        q = new PriorityQueue<int[]>(n, new Comparator<int[]>() {
            @Override
            public int compare(int[] o1, int[] o2) {
                return o1[1] - o2[1];
            }
        });
    }

    public void set(int i, int j, int cost) {
        a[i][j] = cost;
    }

    public int getCost(int s, int e) {
        if (s == e) {
            return 0;
        }
        Arrays.fill(b, false);
        q.clear();
        b[s] = true;
        for (int i = 1; i < a.length; i++) {
            if (a[s][i] >= 0) {
                q.add(new int[] { i, a[s][i] });
            }
        }
        int c = -1;
        while (!q.isEmpty()) {
            int[] t = q.poll();
            if (t[0] == e) {
                c = t[1];
                break;
            }
            b[t[0]] = true;
            for (int k = 0; k < a.length; k++) {
                if (!b[k] && a[t[0]][k] >= 0) {
                    q.add(new int[]{k, t[1] + a[t[0]][k]});
                    if (a[s][k] == -1) {
                        set(s, k, t[1] + a[t[0]][k]);
                    } else{
                        set(s, k, Math.min(a[s][k], t[1] + a[t[0]][k]));
                    }
                }
            }
        }
        return c;
    }
}

