Edge[] es=new Edge[e];
int[] d=new int[v];
for(int i=0;i<e;i++){
int s=Integer.parseInt(br.readLine());
int t=Integer.parseInt(br.readLine());
int c=Integer.parseInt(br.readLine());
es[i]=new Edge(s,t,c);
}
BellmanFord(e,r,es,d);
for(int i=0;i<v;i++){
out.println(d[i]);
}
out.flush();
}

static void BellmanFord(int e,int r,Edge[] es,int[] d){
Arrays.fill(d,INF);
d[r]=0;
while(true){
boolean update=false;
for(int i=0;i<e;i++){
Edge e=es[i];
if(d[e.to]>d[e.from]+d[e.cost]){
d[e.to]=d[e.from]+d[e.cost];
update=true;
}
}
if(!update){
break;
}
}
}
}

