        if(visited[j]==false &&  dist[j] < shortestDist) {
          shortestDist = dist[j];
          shortestPoint = j;
        }
      }

      visited[shortestPoint] = true;

      for(int j = 0 ; j < v ; j++) { // 距離設定
        if(dist[shortestPoint] + adjArr[shortestPoint][j] < dist[j]) {
          dist[j] = dist[shortestPoint] + adjArr[shortestPoint][j];
        }
      }
    }
  }
