            obj.calculate(g.getVertex(source));

            // Print the minimum Distance.
            for (Vertex v : g.getVertices()) {
                if(v.minDistance == Integer.MAX_VALUE)
                    System.out.println("INF");
                else
                    System.out.println(v.minDistance);
            }
        }
    }

}

