int v=Integer.parseInt(line.split(" ")[0]);
int e=Integer.parseInt(line.split(" ")[1]);
int r=Integer.parseInt(line.split(" ")[2]);
HashMap<Integer,ArrayList<Edge>> dic=new HashMap<Integer,ArrayList<Edge>>();
