        int start = ni();
        int[][] map = new int[V][V];
        for (int i = 0; i < V; i++) {
            for (int j = 0; j < V; j++) {
                map[i][j] = Integer.MAX_VALUE;
            }
        }
        DijkstraMatrix dij = new DijkstraMatrix(V);

        for (int i = 0; i < E; i++) {
            int s = ni();
