                v--;

                foreach(var destination in destinations)
                {
                    if(!isFixed[destination[0]] && costs[destination[0]] > costs[node] + destination[1])
                    {
                        costs[destination[0]] = costs[node] + destination[1];
                        queue.Enqueue(destination[0], costs[destination[0]]);
                    }
