        private class PriorityQueue
        {
            private int[][] heap;


            public int Count { get; private set; } = 0;

            public PriorityQueue(int size)
            {
                this.heap = new int[size][];
            }

            public void Enqueue(int node, int distance)
            {
                if(this.Count == 0)
                {
                    heap[0] = new int[2] { node, distance };
                    this.Count++;
                    return;
                }

                var nodeNo = this.Count;

                while(nodeNo > 0)
                {
                    var parentNo = (nodeNo - 1) / 2;
                    if(distance >= heap[parentNo][1])
                    {
                        break;
                    }
                    heap[nodeNo] = heap[parentNo];
                    nodeNo = parentNo;
                }

                heap[nodeNo] = new int[2] { node, distance };
                this.Count++;
            }

            public int Dequeue()
            {
                this.Count--;

                var node = heap[0];
                var last = heap[this.Count];

                var parentNo = 0;
                while(parentNo * 2 + 1 < this.Count)
                {
                    var leftChild = parentNo * 2 + 1;
                    var rightChild = parentNo * 2 + 2;

                    if(rightChild < this.Count && heap[leftChild][1] > heap[rightChild][1])
                    {
                        leftChild = rightChild;
                    }

                    if(heap[leftChild][1] > last[1])
                    {
                        break;
                    }

                    heap[parentNo] = heap[leftChild];
                    parentNo = leftChild;
                }

                heap[parentNo] = last;

                return node[0];
            }
        }
    }
}

