    {
        string[] line = Console.ReadLine().Trim().Split(' ');
        var n = int.Parse(line[0]);
        var pq = new PriorityQueue<Node>(n + 100000, 0);
        var e = int.Parse(line[1]);
        var r = int.Parse(line[2]);
        var a = new List<Edge>[n];
        for (int i = 0; i < n; i++) a[i] = new List<Edge>();
        for (int i = 0; i < e; i++)
        {
            string[] line2 = Console.ReadLine().Trim().Split(' ');
            var s = int.Parse(line2[0]);
            var t = int.Parse(line2[1]);
            var d = int.Parse(line2[2]);
            a[s].Add(new Edge { to = t, d = d });
        }
        var mind = new int[n];
        for (int i = 0; i < n; i++) mind[i] = 9999999;
        goDijk(pq, a, r, n, mind);
        foreach (var x in mind)
            if (x == 9999999) Console.WriteLine("INF");
            else Console.WriteLine(x);
    }
    public static void goDijk(PriorityQueue<Node> pq, List<Edge>[] aa, int r, int n, int[] mind)
    {
        pq.Push(new Node { id = r, d = 0 });
        while (pq.Count() > 0)
        {
            var targ = pq.Pop();
            var nowd = targ.d;
            var nowid = targ.id;
            if (mind[nowid] < nowd) continue;
            mind[nowid] = nowd;
            foreach (var x in aa[nowid])
                if (nowd + x.d < mind[x.to])
                    pq.Push(new Node { id = x.to, d = nowd + x.d });
        }
    }
}

