    class Dijkstra
    {
        private List<ComparablePair>[] adjacencyList;
        private bool isDirectedGraph;
        public Dijkstra(int capacity, bool isDirected = true)
        {
            adjacencyList = new List<ComparablePair>[capacity];
            for (int i = 0; i < capacity; i++)
            {
                adjacencyList[i] = new List<ComparablePair>();
            }
            isDirectedGraph = isDirected;
        }

        public void AddEdge(int from, int to, int cost)
        {
            adjacencyList[from].Add(new ComparablePair(to, cost));
            if (!isDirectedGraph)
            {
                adjacencyList[to].Add(new ComparablePair(from, cost));
            }
        }

        public int[] GetDistances(int start)
        {
            var distances = new int[adjacencyList.Length];
            for (int i = 0; i < adjacencyList.Length; i++)
            {
                distances[i] = -1;
            }
            distances[start] = 0;
            var visitedList = new HashSet<int>();
            var current = start;
            var pq = new Heap<ComparablePair>();
            pq.Push(new ComparablePair(start, 0));
            while (pq.Count > 0)
            {
                var vertex = pq.Pop();
                visitedList.Add(vertex.Index);
                var adjanctes = adjacencyList[vertex.Index];
                foreach (var candEdge in adjanctes)
                {
                    if (distances[candEdge.Index] > candEdge.Cost + vertex.Cost || distances[candEdge.Index] < 0)
                    {
                        distances[candEdge.Index] = candEdge.Cost + vertex.Cost;
                    }
                    if (!visitedList.Contains(candEdge.Index))
                    {
                        pq.Push(new ComparablePair(candEdge.Index, candEdge.Cost + vertex.Cost));
                    }
                }
            }
            return distances;
        }

        struct ComparablePair : IComparable<ComparablePair>
        {
            public int Index { get; set; }
            public int Cost { get; set; }
            public ComparablePair(int index, int cost)
            {
                Index = index;
                Cost = cost;
            }
            public int CompareTo(ComparablePair other)
            {
                return Cost.CompareTo(other.Cost);
            }
            public override string ToString()
            {
                return $"Index: {Index}, Cost: {Cost}";
            }
        }
    }

    class Heap<T> where T : IComparable<T>
    {
        private List<T> heapList;
        public Heap()
        {
            heapList = new List<T>();
        }
        public Heap(int capacity)
        {
            heapList = new List<T>(capacity);
        }
        public void Push(T item)
        {
            var index = heapList.Count;
            heapList.Add(item);
            while (true)
            {
                var parentInd = (index - 1) / 2;
                var parent = heapList[parentInd];
                if (parent.CompareTo(item) > 0)
                {
                    Exchange(parentInd, index);
                    index = parentInd;
                    continue;
                }
                break;
            }
        }
        public T Pop()
        {
            var lastInd = heapList.Count - 1;
            if (lastInd == 0)
            {
                var cur = heapList[0];
                heapList.RemoveAt(0);
                return cur;
            }
            else if (lastInd < 0)
            {
                throw new InvalidOperationException();
            }
            var ret = heapList[0];
            var msi = heapList[0] = heapList[lastInd];
            heapList.RemoveAt(lastInd--);
            var current = 0;
            while (true)
            {
                var child1 = current * 2 + 1;
                var child2 = current * 2 + 2;
                if (child1 > lastInd)
                {
                    return ret;
                }
                else if (child2 > lastInd)
                {
                    if (msi.CompareTo(heapList[child1]) > 0)
                    {
                        Exchange(current, child1);
                    }
                    return ret;
                }
                if (heapList[child1].CompareTo(heapList[child2]) > 0)
                {
                    if (msi.CompareTo(heapList[child2]) > 0)
                    {
                        Exchange(current, child2);
                        current = child2;
                        continue;
                    }
                }
                else
                {
                    if (msi.CompareTo(heapList[child1]) > 0)
                    {
                        Exchange(current, child1);
                        current = child1;
                        continue;
                    }
                }
                return ret;
            }

        }
        private void Exchange(int first, int second)
        {
            var sItem = heapList[second];
            heapList[second] = heapList[first];
            heapList[first] = sItem;
        }
        public int Count => heapList.Count;
    }

    private static int UpperBound<T>(this IEnumerable<T> list, T item) where T : IComparable<T> => UpperBound(list.ToList(), item);
    private static int LowerBound<T>(this IEnumerable<T> list, T item) where T : IComparable<T> => LowerBound(list.ToList(), item);

    private static int UpperBound<T>(this List<T> list, T item) where T : IComparable<T>
    {
        return list.BinarySearch(item, -1, list.Count, (first, second) => first.CompareTo(second) > 0);
    }

    private static int LowerBound<T>(this List<T> list, T item) where T : IComparable<T>
    {
        return list.BinarySearch(item, -1, list.Count, (first, second) => first.CompareTo(second) >= 0);
    }

    private static int BinarySearch<T>(this List<T> list, T item, int left, int right, Func<T, T, bool> isOkPredicate)
    {
        while (Math.Abs(right - left) > 1)
        {
            var mid = left + (right - left) / 2;
            if (isOkPredicate(list[mid], item))
            {
                right = mid;
            }
            else
            {
                left = mid;
            }
        }
        return right;
    }


