            }

            var used = new bool[V];
            var dist = new int[V];
            for(var i = 0; i < V; i++) dist[i] = int.MaxValue;
            dist[R] = 0;

            var pq = new PriorityQueue<Stat>();
            pq.Enqueue(new Stat{Num = R, Cost = 0});

            while(pq.Count > 0){
                var stat = pq.Dequeue();
                var num = stat.Num;
                used[num] = true;

                foreach(var edge in adj[num]){
                    var to = edge.To;
                    var cost = stat.Cost +  edge.Cost;

                    if(used[to]) continue;
                    if(cost > dist[to]) continue;
                    dist[to] = cost;
                    pq.Enqueue(new Stat{Num = to, Cost = cost});
                }
            }

