namespace ConsoleApplication1
{
    class Program
    {
        static int INF = Int32.MaxValue;

        static void Dfs(int wt, int pos, int[] dist, Dictionary<int, List<int>> allDist, int V)
        {
            if (wt >= dist[pos]) return;
            dist[pos] = wt;

            if (!allDist.ContainsKey(pos)) return;
            foreach (var nextPos in allDist[pos])
            {
                Dfs(wt + (nextPos & 0xFFFF), nextPos >> 16, dist, allDist, V);
            }
        }

        public static int[] GetDist(int V, int r, Dictionary<int, List<int>> allDist)
        {
            var dist = new int[V];
            for (int i = 0; i < V; i++) dist[i] = INF;
            Dfs(0, r, dist, allDist, V);
            return dist;
        }

        static void Main(string[] args)
        {
            var str = Console.ReadLine().Split();
            var V = Int32.Parse(str[0]);
            var E = Int32.Parse(str[1]);
            var r = Int32.Parse(str[2]);

            var allDist = new Dictionary<int, List<int>>();

            for (int l = 0; l < E; l++)
            {
                str = Console.ReadLine().Split();
                var s = Int32.Parse(str[0]);
                var t = Int32.Parse(str[1]);
                var d = Int32.Parse(str[2]);
                if (!allDist.ContainsKey(s)) allDist.Add(s, new List<int>());
                allDist[s].Add(t << 16 | d);
            }

            var dist = GetDist(V, r, allDist);

            for (int i = 0; i < V; i++)
            {
                Console.WriteLine(dist[i] == INF ? "INF" : string.Format("{0}", dist[i]));
            }
        }
    }
}

