        {
            string[] input = Console.ReadLine().Split(' ');
            int V = int.Parse(input[0]);
            int E = int.Parse(input[1]);
            int r = int.Parse(input[2]);

            Dictionary<int, List<Edge>> nodeList = new Dictionary<int, List<Edge>>();
            for (int i = 0; i < V; i++) nodeList.Add(i, new List<Edge>());

            int s, t, d;
            for (int i = 0; i < E; i++)
            {
                input = Console.ReadLine().Split(' ');
                s = int.Parse(input[0]);
                t = int.Parse(input[1]);
                d = int.Parse(input[2]);

                nodeList[s].Add(new Edge(t, d));
            }

            Dijkstra(nodeList, r);
        }

        static void Dijkstra(Dictionary<int, List<Edge>> NL, int start)
        {
            int len = NL.Count;

            PriorityQueue<Edge> pq = new PriorityQueue<Edge>();
            Nullable<int>[] dp = new Nullable<int>[len];

            dp[start] = 0;
            pq.Enqueue(new Edge(start, 0));

            while (pq.Count() > 0)
            {
                Edge edge = pq.Dequeue();
                int cur = edge.to;

                if (dp[cur] < -edge.cost) continue;

                int outDegree = NL[cur].Count;

                for (int j = 0; j < outDegree; j++)
                {
                    int next = NL[cur][j].to;

                    if (dp[next] == null || dp[next] > dp[cur] + NL[cur][j].cost)
                    {
                        dp[next] = dp[cur] + NL[cur][j].cost;
                        pq.Enqueue(new Edge(next, (int)-dp[next]));
                    }
                }
            }

            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < len; i++)
            {
                sb.AppendLine(dp[i] == null ? "INF" : dp[i].ToString());
            }
            Console.Write(sb);
        }
    }

    class PriorityQueue<T> where T : IComparable
    {
        List<T> heap;
        int size;

        public PriorityQueue()
        {
            heap = new List<T>();
        }

        public void Enqueue(T x)
        {
            heap.Add(x);
            int i = size++;

            while (i > 0)
            {
                int p = (i - 1) / 2;

                if (Compare(heap[p], x) <= 0) break;

                heap[i] = heap[p];
                i = p;
            }
            heap[i] = x;
        }

        public T Dequeue()
        {
            T ret = heap[0];
            T x = heap[--size];

            int i = 0;
            while (i * 2 + 1 < size)
            {
                int a = i * 2 + 1;
                int b = i * 2 + 2;

                if (b < size && Compare(heap[b], heap[a]) < 0)
                    a = b;
                if (Compare(heap[a], x) >= 0)
                    break;

                heap[i] = heap[a];
                i = a;
            }
            heap[i] = x;
            heap.RemoveAt(size);
            return ret;
        }

        public int Count()
        {
            return size;
        }

        private int Compare(T x, T y)
        {
            return y.CompareTo(x);
        }
    }
}

