namespace ConsoleApplication1
{
    class Program
    {
        static int INF = Int32.MaxValue;

        static void Dfs(int wt, int pos, int[] dist, Dictionary<int, int> allDist, int V)
        {
            if (wt >= dist[pos]) return;
            dist[pos] = wt;

            for (int i = 0; i < V; i++)
            {
                if (pos == i) continue;
                var key = pos << 16 | i;
                if (!allDist.ContainsKey(key)) continue;
                Dfs(wt + allDist[key], i, dist, allDist, V);
            }
        }

        public static int[] GetDist(int V, int r, Dictionary<int, int> allDist)
        {
            var dist = new int[V];
            for (int i = 0; i < V; i++) dist[i] = INF;
            Dfs(0, r, dist, allDist, V);
            return dist;
        }

        static void Main(string[] args)
        {
            var str = Console.ReadLine();
            var V = Int32.Parse(str.Split()[0]);
            var E = Int32.Parse(str.Split()[1]);
            var r = Int32.Parse(str.Split()[2]);
            var allDist = new Dictionary<int, int>();

            for (int l = 0; l < E; l++)
            {
                str = Console.ReadLine();
                var s = Int32.Parse(str.Split()[0]);
                var t = Int32.Parse(str.Split()[1]);
                var d = Int32.Parse(str.Split()[2]);
                var key = s << 16 | t;
                if (!allDist.ContainsKey(key)) allDist.Add(key, d);
                else allDist[key] = Math.Min(allDist[key], d);
            }

            var dist = GetDist(V, r, allDist);

            for (int i = 0; i < V; i++)
            {
                Console.WriteLine(dist[i] == INF ? "INF" : string.Format("{0}", dist[i]));
            }
        }
    }
