class Program {
    static string ReadLine() { return Console.ReadLine(); }
    static int ReadInt() { return int.Parse(ReadLine()); }
    static int[] ReadInts() { return ReadLine().Split().Select(int.Parse).ToArray(); }
    static string[] ReadStrings() { return ReadLine().Split(); }

    static void Calc(int n, int r, Dictionary<int, List<Tuple<int, int>>> adj) {

        var dist = new int[n];
        for (int i = 0; i < dist.Length; i++) dist[i] = -1;
        var used = new int[n];
        var q = new PriorityQueue<D>();
        q.Enqueue(new D { node = r, cost = 0 });
        while (q.Count > 0) {
            D d = q.Dequeue();

            if (used[d.node]++ > 0) continue;
            dist[d.node] = d.cost;

            foreach (var t in adj[d.node]) {
                q.Enqueue(new D { node = t.Item1, cost = d.cost + t.Item2 });
            }
        }

        foreach (int d in dist) {
            if (d == -1) { // no path
                Console.WriteLine("INF");
            }
            else {
                Console.WriteLine(d);
            }
        }
    }

    static void Main() {
        var nmr = ReadInts();
        int n = nmr[0], m = nmr[1], r = nmr[2];

        var adj = new Dictionary<int, List<Tuple<int, int>>>();
        for (int i = 0; i < m; i++) {
            var abc = ReadInts();
            int a = abc[0];
            int b = abc[1];
            int c = abc[2];
            if (!adj.ContainsKey(a)) adj[a] = new List<Tuple<int, int>>();

            adj[a].Add(Tuple.Create(b, c));
        }

        Calc(n, r, adj);
    }
}

