        public static void dijkstra(List<Node> nodes, Node firstNode)
        {
            var node = firstNode;
            node.cost = 0;
            //node.groupId = 1;

            while (true)
            {
                //Complete Condition
                var unSelectedNodes = nodes.Where(n => n.groupId != 1);

                var nextNode = unSelectedNodes.OrderBy(n => n.cost).FirstOrDefault();
                if (nextNode == null)
                {
                    break;
                }

                nextNode.groupId = 1;

                var edges = nextNode.edges
                    .Where(n => n.fromId == nextNode.id && unSelectedNodes.Select(m => m.id).Contains(n.toId));

                if (edges == null)
                {
                    break;
                }

                foreach (var e in edges)
                {
                    var fromNode = (Node)nodes.Where(n => n.id == e.fromId).FirstOrDefault();
                    var toNode = (Node)nodes.Where(n => n.id == e.toId).FirstOrDefault();
                    toNode.cost = Math.Min(toNode.cost, e.cost + fromNode.cost);
                    toNode.groupId = 2;
                }
            }

            #region output

            foreach (var n in nodes)
            {
                Console.WriteLine(n.cost == int.MaxValue ? "INF" : n.cost.ToString());
            }

            #endregion output
        }

