static long e = long.Parse(inputvv[1]);
static long startV = long.Parse(inputvv[2]);
static List<long[]>[] nextList = new List<long[]>[n];//頂点番号ごとの隣接リスト。距離、隣接頂点番号
static long[] colors = new long[n];//最短距離未確定の頂点が0、確定で2
static long[] distances = new long[n];//各頂点への最短距離
static long[] distanceMemos = new long[2];//キューから捨てた最短距離と頂点番号

	static void Main()
	{
    for(long i = 0; i < n; i++)
    {
      nextList[i] = new List<long[]>();//リストの宣言が必要
    }

    for(long j = 0; j < e; j++)
    {
      long[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);
      long[] nextMemo = new long[2];
      nextMemo[1] = nums[1];//隣接頂点番号
      nextMemo[0] = nums[2];//距離
      nextList[nums[0]].Add(nextMemo);//隣接リストの作成
    }

    Dijkstra();
	}

  static void Dijkstra()//O((|頂点数|+|辺数|)log頂点数)で各頂点への最短距離を求める
  {
    List<long[]> distanceList = new List<long[]>();//優先度付きキュー
    for(long i = 0; i < n; i++)
    {
      distances[i] = long.MaxValue;//最短距離を無限とおく
    }

    long[] newDistance = new long[2];

    //スタート地点を決める
    newDistance[1] = startV;//スタート地点番号
    distances[startV] = 0;
    colors[startV] = 1;

    newDistance[0] = 0;//スタートからスタートまでの距離0
    distanceList.Add(newDistance);

    while(distanceList.Count() != 0)
    {
      distanceList = PopHeap(distanceList);
      long minVertex = distanceMemos[1];//最短頂点の番号
      colors[minVertex] = 2;
      if(distances[minVertex] < distanceMemos[0]) continue;//最小値が最短でないなら無視

      for(long i = 0; i < nextList[minVertex].Count(); i++)
      {
        long v = nextList[minVertex][(int)i][1];
        if(colors[v] == 2) continue;
        if(distances[v] > distances[minVertex] + nextList[minVertex][(int)i][0])
        {
          distances[v] = distances[minVertex] + nextList[minVertex][(int)i][0];
          long[] newDistanceSub = new long[2];
          newDistanceSub[0] = distances[v];
          newDistanceSub[1] = v;
          distanceList = PushHeap(distanceList, newDistanceSub);
          colors[v] = 1;
        }
      }
    }

    for(long i = 0; i < n; i++)
    {
      Console.WriteLine((distances[i] == long.MaxValue? "INF" : distances[i].ToString()));
        //全頂点について最短距離の出力。到達不可能な頂点は-1を出力。
    }

  }

  //引数は、昇順にソート済みのリスト
  static List<long[]> PushHeap(List<long[]> nums, long[] addNums)//現在のヒープnumsにaddNumを追加
  {
    int n = nums.Count;
    nums.Add(addNums);

    while (n > 0)
    {
      int i = (n-1)/2;
      if (nums[n][0] < nums[i][0])//親のほうが大きいなら入れ替え。
      {
        long tmp = nums[n][0];
        long tmpSub = nums[n][1];
        nums[n][0] = nums[i][0];
        nums[n][1] = nums[i][1];
        nums[i][0] = tmp;
        nums[i][1] = tmpSub;
      }
      n = i;
    }
    return nums;
  }

  static List<long[]> PopHeap(List<long[]> nums)//ヒープnumsからポップ
  {
    int n = nums.Count - 1;
    distanceMemos[0] = nums[0][0];//捨てる値の保存
    distanceMemos[1] = nums[0][1];
    nums[0][0] = nums[n][0];//最小値である根を削除してリストの最後を持ってくる
    nums[0][1] = nums[n][1];
    nums.RemoveAt(n);

    for (int i = 0, j; (j = 2*i+1) < n; )
    {
      if ((j != n-1) && (nums[j][0] > nums[j+1][0]))// ２つの子のうち、値の小さい方を選ぶ
        j++;
      if (nums[i][0] > nums[j][0])//子が親より小さいなら入れ替え
      {
        long tmp = nums[j][0];
        long tmpSub = nums[j][1];
        nums[j][0] = nums[i][0];
        nums[j][1] = nums[i][1];
        nums[i][0] = tmp;
        nums[i][1] = tmpSub;
      }
      i = j;
    }
    return nums;
  }

}

using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;

namespace AizuOnline
{
    internal class Program
    {
        private static void Main(string[] args)
        {
            var x = Console.ReadLine().Split(' ');
            var nodeNum = Convert.ToInt32(x[0]);
            var edgeNum = Convert.ToInt32(x[1]);
            var firstNodeId = Convert.ToInt32(x[2]);

            var nodes = createDirectionNodesByList2(nodeNum, edgeNum);
            var firstNode = nodes.Where(n => n.id == firstNodeId).FirstOrDefault();

            dijkstra(nodes, firstNode);

            Console.ReadLine();
        }

        public static List<Node> createDirectionNodesByList2(int nodeNum, int edgeNum)
        {
            var nodes = new List<Node>();

            for (int i = 0; i < nodeNum; i++)
            {
                var node = new Node()
                {
                    id = i
                };
                nodes.Add(node);
            }

            for (int i = 0; i < edgeNum; i++)
            {
                try
                {
                    var p = Console.ReadLine().Split(' ');
                    var fromId = Convert.ToInt32(p[0]);
                    var toId = Convert.ToInt32(p[1]);

                    var node = nodes.Where(n => n.id == fromId).FirstOrDefault();

                    node.edges.Add(new Edge()
                    {
                        fromId = fromId,
                        toId = toId,
                        cost = Convert.ToInt32(p[2]),
                    });
                }
                catch (Exception e)
                {
                    Console.WriteLine(e.Message);
                }
            }

            return nodes;
        }

        public static void dijkstra(List<Node> nodes, Node firstNode)
        {
            var node = firstNode;
            node.cost = 0;
            var sw = new Stopwatch();
            sw.Start();
            while (true)
            {
                var mincost = int.MaxValue;
                Node nextNode = null;
                foreach (var n in nodes)
                {
                    if (n.groupId != 1 && n.cost < mincost)
                    {
                        mincost = n.cost;
                        nextNode = n;
                    }
                }
                if (mincost == int.MaxValue)
                {
                    break;
                }
                if (nextNode != null)
                {
                    nextNode.groupId = 1;
                }

                foreach (var n in nodes)
                {
                    if (n.groupId != 1 && nextNode.edges.Select(m => m.toId).Contains(n.id))
                    {
                        var edge = nextNode.edges.Where(m => m.toId == n.id).FirstOrDefault();
                        n.cost = Math.Min(n.cost, edge.cost + nextNode.cost);
                        n.groupId = 2;
                    }
                }
            }

            Console.WriteLine(sw.Elapsed);

            #region output

            foreach (var n in nodes)
            {
                Console.WriteLine(n.cost == int.MaxValue ? "INF" : n.cost.ToString());
            }

            #endregion output
        }

        public class Node
        {
            public int id;
            public bool isPassed = false;
            public int groupId;
            public int cost = int.MaxValue;
            public List<Edge> edges = new List<Edge>();
        }

        public class Edge
        {
            public int id = int.MinValue;
            public int fromId;
            public int toId;
            public int cost;
            public bool isPassed = false;
        }
    }
