                    id = i
                };
                nodes.Add(node);
            }

            for (int i = 0; i < edgeNum; i++)
            {
                try
                {
                    var p = Console.ReadLine().Split(' ');
                    var fromId = Convert.ToInt32(p[0]);
                    var toId = Convert.ToInt32(p[1]);

                    var node = nodes.Where(n => n.id == fromId).FirstOrDefault();

                    node.edges.Add(new Edge()
                    {
                        fromId = fromId,
                        toId = toId,
                        cost = Convert.ToInt32(p[2]),
                    });
                }
                catch (Exception e)
                {
                    Console.WriteLine(e.Message);
                }
            }

            return nodes;
        }

        public static void dijkstra(List<Node> nodes, Node firstNode)
        {
            var node = firstNode;
            node.cost = 0;
            var sw = new Stopwatch();
            sw.Start();
            while (true)
            {
                var mincost = int.MaxValue;
                Node nextNode = null;
                foreach (var n in nodes)
                {
                    if (n.groupId != 1 && n.cost < mincost)
                    {
                        mincost = n.cost;
                        nextNode = n;
                    }
                }
                if (mincost == int.MaxValue)
                {
                    break;
                }
                if (nextNode != null)
                {
                    nextNode.groupId = 1;
                }

                foreach (var n in nodes)
                {
                    if (n.groupId != 1 && nextNode.edges.Select(m => m.toId).Contains(n.id))
                    {
                        var edge = nextNode.edges.Where(m => m.toId == n.id).FirstOrDefault();
                        n.cost = Math.Min(n.cost, edge.cost + nextNode.cost);
                        n.groupId = 2;
                    }
                }
            }

            //Console.WriteLine(sw.Elapsed);

            #region output

            foreach (var n in nodes)
            {
                Console.WriteLine(n.cost == int.MaxValue ? "INF" : n.cost.ToString());
            }

            #endregion output
        }

        public class Node
        {
            public int id;
            public bool isPassed = false;
            public int groupId;
            public int cost = int.MaxValue;
            public List<Edge> edges = new List<Edge>();
        }

        public class Edge
        {
            public int id = int.MinValue;
            public int fromId;
            public int toId;
            public int cost;
            public bool isPassed = false;
        }
    }
