namespace ConsoleApplication1
{
    class Edge : IComparable
    {
        internal int to;
        internal int cost;

        public Edge(int to, int cost)
        {
            this.to = to;
            this.cost = cost;
        }

        public int CompareTo(object obj)
        {
            Edge temp = obj as Edge;
            return cost - temp.cost;
        }
    }

    class Program
    {
        static void Main(string[] args)
        {
            string[] input = Console.ReadLine().Split(' ');
            int V = int.Parse(input[0]);
            int E = int.Parse(input[1]);
            int r = int.Parse(input[2]);

            Dictionary<int, List<Edge>> nodeList = new Dictionary<int, List<Edge>>();
            for (int i = 0; i < V; i++) nodeList.Add(i, new List<Edge>());

            int s, t, d;
            for (int i = 0; i < E; i++)
            {
                input = Console.ReadLine().Split(' ');
                s = int.Parse(input[0]);
                t = int.Parse(input[1]);
                d = int.Parse(input[2]);

                nodeList[s].Add(new Edge(t, d));
            }

            Dijkstra(nodeList, r);
        }

        static void Dijkstra(Dictionary<int, List<Edge>> NL, int start)
        {
            int len = NL.Count, INFTY = int.MaxValue;

            SortedSet<Edge> SS = new SortedSet<Edge>();

            int[] dp = Enumerable.Repeat(INFTY, len).ToArray();
            bool[] isVisit = new bool[len];

            dp[start] = 0;
            SS.Add(new Edge(start, 0));

            while (SS.Count > 0)
            {
                Edge edge = SS.First();
                SS.Remove(edge);
                int cur = edge.to;
                isVisit[cur] = true;

                if (dp[cur] < edge.cost) continue;

                int outDegree = NL[cur].Count;

                for (int j = 0; j < outDegree; j++)
                {
                    int next = NL[cur][j].to;

                    if (isVisit[next] == true) continue;

                    if (dp[next] > dp[cur] + NL[cur][j].cost)
                    {
                        dp[next] = dp[cur] + NL[cur][j].cost;
                        SS.Add(new Edge(next, dp[next]));
                    }
                }
            }

            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < len; i++)
            {
                sb.AppendLine(dp[i] == INFTY ? "INF" : dp[i].ToString());
            }
            Console.Write(sb);
        }
    }
}

using System;
using System.Linq;//リストの使用
using System.Collections.Generic;
using System.Text;//テキストの高速出力に必要
class Program
{
static long[] distanceMemos = new long[2];//キューから捨てた最短距離と頂点番号

  static void Main()
  {
    string[] inputvv = Console.ReadLine().Split(' ');
    int n = int.Parse(inputvv[0]);
    int e = int.Parse(inputvv[1]);
    int r = int.Parse(inputvv[2]);
    long[,] edges = new long[e,3];
    long[] answers = new long[n];

    for(long i = 0; i < e; i++)
    {
      long[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);
      edges[i,0] = nums[0];
      edges[i,1] = nums[1];
      edges[i,2] = nums[2];
    }

    answers = Dijkstra(n,e,r,edges);
    for(long i = 0; i < n; i++)
    {
      Console.WriteLine((answers[i] == -1? "INF" : answers[i].ToString()));
    }
  }

  static long[] Dijkstra(int vertexCount, int edgeCount, int startV, long[,] edges)
  {//ダイクストラ法により、O((|頂点数|+|辺数|)log頂点数)で各頂点への最短距離を求める
  //引数は頂点数、辺数、開始頂点(0-index)、辺の始点と終点と距離
  //返り値は各頂点までの最短距離、ただし到達できない場合は-1

    int n = vertexCount;
    List<long[]>[] nextList = new List<long[]>[n];//頂点番号ごとの隣接リスト。距離、隣接頂点番号
    for(long i = 0; i < n; i++)
    {
      nextList[i] = new List<long[]>();//リストの宣言が必要
    }
    long[] colors = new long[n];//最短距離未確定の頂点が0、確定で2
    long[] distances = new long[n];//各頂点への最短距離

    for(long i = 0; i < edgeCount; i++)
    {
      long[] nextMemo = new long[2];
      nextMemo[1] = edges[i,1];//隣接頂点番号
      nextMemo[0] = edges[i,2];//距離
      nextList[edges[i,0]].Add(nextMemo);//隣接リストの作成
    }

    List<long[]> distanceList = new List<long[]>();//優先度付きキュー
    for(long i = 0; i < n; i++)
    {
      distances[i] = long.MaxValue;//最短距離を無限とおく
    }

    long[] newDistance = new long[2];

    //スタート地点を決める
    newDistance[1] = startV;//スタート地点番号
    distances[startV] = 0;
    colors[startV] = 1;

    newDistance[0] = 0;//スタートからスタートまでの距離0
    distanceList.Add(newDistance);

    while(distanceList.Count() != 0)
    {
      distanceList = PopHeap(distanceList);
      long minVertex = distanceMemos[1];//最短頂点の番号
      colors[minVertex] = 2;
      if(distances[minVertex] < distanceMemos[0]) continue;//最小値が最短でないなら無視

      for(long i = 0; i < nextList[minVertex].Count(); i++)
      {
        long v = nextList[minVertex][(int)i][1];
        if(colors[v] == 2) continue;
        if(distances[v] > distances[minVertex] + nextList[minVertex][(int)i][0])
        {
          distances[v] = distances[minVertex] + nextList[minVertex][(int)i][0];
          long[] newDistanceSub = new long[2];
          newDistanceSub[0] = distances[v];
          newDistanceSub[1] = v;
          distanceList = PushHeap(distanceList, newDistanceSub);
          colors[v] = 1;
        }
      }
    }

    for(long i = 0; i < n; i++)
    {
      if(distances[i] == long.MaxValue) distances[i] = -1;
        //全頂点について最短距離の出力。到達不可能な頂点は-1を出力。
    }
    return distances;
  }

  //引数は、昇順にソート済みのリスト
  static List<long[]> PushHeap(List<long[]> nums, long[] addNums)//現在のヒープnumsにaddNumを追加
  {
    int n = nums.Count;
    nums.Add(addNums);

    while (n > 0)
    {
      int i = (n-1)/2;
      if (nums[n][0] < nums[i][0])//親のほうが大きいなら入れ替え。
      {
        long tmp = nums[n][0];
        long tmpSub = nums[n][1];
        nums[n][0] = nums[i][0];
        nums[n][1] = nums[i][1];
        nums[i][0] = tmp;
        nums[i][1] = tmpSub;
      }
      n = i;
    }
    return nums;
  }

  static List<long[]> PopHeap(List<long[]> nums)//ヒープnumsからポップ
  {
    int n = nums.Count - 1;
    distanceMemos[0] = nums[0][0];//捨てる値の保存
    distanceMemos[1] = nums[0][1];
    nums[0][0] = nums[n][0];//最小値である根を削除してリストの最後を持ってくる
    nums[0][1] = nums[n][1];
    nums.RemoveAt(n);

    for (int i = 0, j; (j = 2*i+1) < n; )
    {
      if ((j != n-1) && (nums[j][0] > nums[j+1][0]))// ２つの子のうち、値の小さい方を選ぶ
        j++;
      if (nums[i][0] > nums[j][0])//子が親より小さいなら入れ替え
      {
        long tmp = nums[j][0];
        long tmpSub = nums[j][1];
        nums[j][0] = nums[i][0];
        nums[j][1] = nums[i][1];
        nums[i][0] = tmp;
        nums[i][1] = tmpSub;
      }
      i = j;
    }
    return nums;
  }

}

