    {
        string[] line = Console.ReadLine().Trim().Split(' ');
        var n = int.Parse(line[0]);
        var pq = new PriorityQueue<Node>(n+5000, 0);
        var e = int.Parse(line[1]);
        var r = int.Parse(line[2]);
        var a = new int[n, n];
        for (int i = 0; i < n; i++)
        {
            for (int j = 0; j < n; j++)
                if (i == j) a[i, j] = 0;
                else a[i, j] = -1;
        }
        for (int i = 0; i < e; i++)
        {
            string[] line2 = Console.ReadLine().Trim().Split(' ');
            var s = int.Parse(line2[0]);
            var t = int.Parse(line2[1]);
            var d = int.Parse(line2[2]);
            a[s, t] = d;
        }
        var mind = new int[n];
        for (int i = 0; i < n; i++) mind[i] = 9999999;
        goDijk(pq, a, r, n ,mind);
        foreach (var x in mind)
            if (x == 9999999) Console.WriteLine("INF");
            else Console.WriteLine(x);
    }
    public static void goDijk(PriorityQueue<Node> pq, int[,] a, int r, int n ,int[] mind)
    {
        pq.Push(new Node { id = r, d = 0 });
        while (pq.Count() > 0)
        {
            var targ = pq.Pop();
            var nowd = targ.d;
            var nowid = targ.id;
            if (mind[nowid] < nowd) continue;
            mind[nowid] = nowd;
            for (int i = 0; i < n; i++)
            {
                if (a[nowid, i] != -1 && (nowd + a[nowid, i] < mind[i]))
                    pq.Push(new Node { id = i, d = nowd + a[nowid, i] });
            }
        }




    }
