        {
            return cost - ((Edge)obj).cost;
        }
    }


    void solve()
    {
        int V = cin.nextint;
        int E = cin.nextint;
        int r = cin.nextint;

        var G = Enumerable.Range(0, V).Select(i => new List<Edge>()).ToArray();
