                E = entry.Count;

                GraphMatrix = new int?[V, V];

                for(var i = 0; i < V; i += 1)
                {
                    for(var j = 0; j < V; j += 1)
                    {
                        GraphMatrix[i, j] = null;
                    }
                }

                foreach (var n in entry)
                {
                    var s = n.node1;
                    var e = n.node2;
                    var d = n.cost;
                    GraphMatrix[s, e] = d;
                }

                /*
                for (var i = 0; i < V; i += 1)
                {
                    for (var j = 0; j < V; j += 1)
                    {
                        var message = (GraphMatrix[i, j].HasValue) ? GraphMatrix[i, j].ToString() : "null";
                        Console.Write("{0} : ", message);
                    }
                    Console.WriteLine();
                }
                */
            }

            public int?[] getLeastestCost(int start)
            {
                var open = new HashSet<int>();
                var close = new HashSet<int>();
                var distanceArray = new int?[V];

                for (var i = 0; i < distanceArray.Length; i += 1)
                {
                    distanceArray[i] = null;
                }

                open.Add(start);
                distanceArray[start] = 0;

                while (open.Count != 0)
                {
                    var target = 0;
                    var minDistance = int.MaxValue;
                    foreach(var i in open)
                    {
                        if (distanceArray[i] < minDistance)
                        {
                            minDistance = distanceArray[i].Value;
                            target = i;
                        }
                    }

                    for (var j = 0; j < V; j +=1 )
                    {
                        if(GraphMatrix[target, j].HasValue)
                        {
                            if(!close.Contains(j))
                            {
                                open.Add(j);
                                var t = GraphMatrix[target, j].Value;
                                if (distanceArray[j].HasValue)
                                {
                                    if(distanceArray[j].Value > distanceArray[target] + t)
                                    {
                                        distanceArray[j] = distanceArray[target] + t;
                                    } 
                                }
                                else
                                {
                                    distanceArray[j] = distanceArray[target] + t;
                                }
                            }
                        }
                    }
                    open.Remove(target);
                    close.Add(target);
                }
                return distanceArray;
            }
        }

        class Entry
        {
            public int node1;
            public int node2;
            public int cost;

            public Entry(int _node1, int _node2, int _cost)
            {
                node1 = _node1;
                node2 = _node2;
                cost = _cost;
            }
        }
    }
