    internal class Program
    {
        private static void Main(string[] args)
        {
            var x = Console.ReadLine().Split(' ');
            var nodeNum = Convert.ToInt32(x[0]);
            var edgeNum = Convert.ToInt32(x[1]);
            var firstNodeId = Convert.ToInt32(x[2]);

            var nodes = NodeCreator.createDirectionNodesByList2(nodeNum, edgeNum);
            var firstNode = nodes.Where(n => n.id == firstNodeId).FirstOrDefault();

            dijkstra(nodes, firstNode);
        }

        public static void dijkstra(List<Node> nodes, Node firstNode)
        {
            var node = firstNode;
            node.cost = 0;
            node.groupId = 1;

            while (true)
            {
                var selectedNodes = nodes.Where(n => n.groupId == 1);

                if (selectedNodes.Count() == nodes.Count)
                {
                    break;
                }

                var edges = selectedNodes
                    .SelectMany(n => n.edges).Where(n => !selectedNodes.Select(m => m.id).Contains(n.toId));

                foreach (var e in edges)
                {
                    var fromNode = (Node)nodes.Where(n => n.id == e.fromId).FirstOrDefault();
                    var toNode = (Node)nodes.Where(n => n.id == e.toId).FirstOrDefault();
                    toNode.cost = Math.Min(toNode.cost, e.cost + fromNode.cost);
                }

                var selectedEdges = selectedNodes
                    .SelectMany(n => n.edges).Where(n => !selectedNodes.Select(m => m.id).Contains(n.toId));
                if (selectedEdges.Count() != 0)
                {
                    var edge = selectedEdges.OrderBy(n => n.cost).First();
                    var nextNode = nodes.Where(n => edge.toId == n.id).FirstOrDefault();
                    nextNode.groupId = 1;
                }
                else
                {
                    break;
                }
            }

            #region output

            foreach (var n in nodes)
            {
                if (n.groupId == 1)
                {
                    Console.WriteLine(n.cost);
                }
                else
                {
                    Console.WriteLine("INF");
                }

                //Console.WriteLine(n.id + " " + n.cost);
            }

            #endregion output
        }
    }
