    class Program
    {
        static int INF = Int32.MaxValue;

        public static int[] GetDist(int V, int r, Dictionary<int, int> allDist)
        {
            var dist = new int[V];
            for (int i = 0; i < V; i++) dist[i] = INF;
            dist[r] = 0;

            //bfs
            var que = new Queue<int>();
            que.Enqueue(r);

            while (que.Count() > 0)
            {
                var pos = que.Dequeue();
                for (int i = 0; i < V; i++)
                {
                    if (i == pos) continue;
                    var key = pos << 16 | i;
                    if (!allDist.ContainsKey(key)) continue;
                    if (dist[pos] + allDist[key] > dist[i]) continue;
                    dist[i] = dist[pos] + allDist[key];
                    que.Enqueue(i);
                }
            }
            return dist;
        }

        static void Main(string[] args)
        {
            var str = Console.ReadLine();
            var V = Int32.Parse(str.Split()[0]);
            var E = Int32.Parse(str.Split()[1]);
