    public static int[] ShortestDistances;

    public static void InitializeDijkstra(int e,int v, List<Edge> es)
    {
        Edges = new List<DjkEdge>[e];
        for (int i = 0; i < e; i++)
        {
            Edges[i] = new List<DjkEdge>();
        }
        ShortestDistances = new int[v];
