namespace ConsoleApplication1
{
    class Program
    {
        static int INF = Int32.MaxValue;

        static void Dfs(int wt, int pos, int[] dist, Dictionary<int, Dictionary<int, int>> allDist, int V)
        {
            if (wt >= dist[pos]) return;
            dist[pos] = wt;

            if (!allDist.ContainsKey(pos)) return;
            foreach (var nextPos in allDist[pos])
            {
                Dfs(wt + nextPos.Value, nextPos.Key, dist, allDist, V);
            }
        }

