                throw new IndexOutOfRangeException("????´????0????????\??????????´?????????????????????????????????????????????????");
            int n = count - 1;
            int returnItem = (int)array[0];
            array[0] = array[n];
            array[n] = 0;
            count--;
            for (int i = 0, j; (j = 2 * i + 1) < n; )
