public class Hello
{
    public static void Main()
    {
        string[] line = Console.ReadLine().Trim().Split(' ');
        var n = int.Parse(line[0]);
        var e = int.Parse(line[1]);
        var r = int.Parse(line[2]);
        var a = new int[n, n];
        var dict = new Dictionary<int, Node>();
        for (int i = 0; i < n; i++)
        {
            dict[i] = new Node() { d = 9999999 };
            for (int j = 0; j < n; j++)
                if (i == j) a[i, j] = 0;
                else a[i, j] = -1;
        }
        for (int i = 0; i < e; i++)
        {
            string[] line2 = Console.ReadLine().Trim().Split(' ');
            var s = int.Parse(line2[0]);
            var t = int.Parse(line2[1]);
            var d = int.Parse(line2[2]);
            a[s, t] = d;
        }
        goDijk(dict, a, r, n);
        display(dict);
    }
    public static void display (Dictionary<int, Node> dict)
    {
        var ret = dict.OrderBy(x => x.Key);
        foreach (var x in ret)
            if (x.Value.d == 9999999) Console.WriteLine("INF");
            else Console.WriteLine(x.Value.d);
    }
    public static void goDijk(Dictionary<int, Node> dict, int[,] a, int r, int n)
    {
        dict[r].d = 0;
        while (dict.Count(x => x.Value.fix == false) > 0)
        {
            var targ = dict.Where(x => x.Value.fix == false).OrderBy(x => x.Value.d).First().Key;
            dict[targ].fix = true;
            var nowfix = dict[targ].d;
            for (int i = 0; i < n; i++)
            {
                if (a[targ, i] != -1  && (nowfix + a[targ, i]) < dict[i].d)
                    dict[i].d = nowfix + a[targ, i];
            }
        }
    }
}

