    class Program
    {
        static int INF = Int32.MaxValue;

        public static int[] GetDist(int V, int r, int[,] allDist)
        {
            var dist = new int[V];
            for (int i = 0; i < V; i++) dist[i] = INF;
            dist[r] = 0;

            //bfs
            var que = new Queue<int>();
            que.Enqueue(r);

            while (que.Count() > 0)
            {
                var pos = que.Dequeue();
                for (int i = 0; i < V; i++)
                {
                    if (i == pos) continue;
                    if (allDist[pos, i] == INF) continue;
                    dist[i] = Math.Min(dist[i], dist[pos] + allDist[pos, i]);
                    que.Enqueue(i);
                }
            }
            return dist;
        }

        static void Main(string[] args)
        {
            var str = Console.ReadLine();
            var V = Int32.Parse(str.Split()[0]);
            var E = Int32.Parse(str.Split()[1]);
            var r = Int32.Parse(str.Split()[2]);
            var allDist = new int[V, V];
            for (int i = 0; i < V; i++)
            {
                for (int j = 0; j < V; j++)
                {
                    allDist[i, j] = INF;
                    allDist[j, i] = INF;
                    if (i == j) allDist[i, j] = 0;
                }
            }

            for (int l = 0; l < E; l++)
            {
                str = Console.ReadLine();
                var s = Int32.Parse(str.Split()[0]);
                var t = Int32.Parse(str.Split()[1]);
                var d = Int32.Parse(str.Split()[2]);
                allDist[s, t] = d;
            }

            var dist = GetDist(V, r, allDist);

            for (int i = 0; i < V; i++)
            {
                Console.WriteLine(dist[i] == INF ? "INF" : string.Format("{0}", dist[i]));
            }
        }
    }
}

