using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

namespace ConsoleApplication1
{
    class Program
    {
        /// <summary>
        /// find the shortest path from start to all destination
        /// works for directed/nondirected graph
        /// </summary>
        public class BellmanFord
        {
            public List<edge> Edge = new List<edge>();
            public int V;   // number of vertex

            public class edge
            {
                public int from, to, cost;
                public edge(int _from, int _to, int _cost)
                {
                    from = _from;
                    to = _to;
                    cost = _cost;
                }
            }

            private void generateV()
            {
                foreach (var e in Edge)
                {
                    V = Math.Max(V, e.from);
                    V = Math.Max(V, e.to);
                }
                V++;
            }

            /// <summary>
            ///  return shortestPath[V] represents distance from startIndex
            /// </summary>
            public int[] GetShortestPath(int startIndex)
            {
                if (V == 0 && Edge.Count > 0) generateV();

                int[] shortestPath = new int[V];
                var INF = Int32.MaxValue;

                for (int i = 0; i < V; i++) shortestPath[i] = INF;
                if (startIndex >= shortestPath.Length || startIndex < 0) return new int[0];
                shortestPath[startIndex] = 0;
                while (true)
                {
                    bool update = false;
                    foreach (edge e in Edge)
                    {
                        if (shortestPath[e.from] != INF && shortestPath[e.to] > shortestPath[e.from] + e.cost)
                        {
                            shortestPath[e.to] = shortestPath[e.from] + e.cost;
                            update = true;
                        }
                    }
                    if (!update) break;
                }

                return shortestPath;
            }

            /// <summary>
            ///  return true if it has negative close loop
            /// </summary>
            public bool HasNegativeLoop()
            {
                int[] d = new int[V];
                for (int i = 0; i < V; i++)
                {
                    foreach (edge e in Edge)
                    {
                        if (d[e.to] > d[e.from] + e.cost)
                        {
                            d[e.to] = d[e.from] + e.cost;
                            if (i == V - 1) return true;
                        }
                    }
                }
                return false;
            }
        }

        static void Main(string[] args)
        {
            var str = Console.ReadLine().Split();
            var V = Int32.Parse(str[0]);
            var E = Int32.Parse(str[1]);
            var r = Int32.Parse(str[2]);

            var bellmanFord = new BellmanFord();

            for (int l = 0; l < E; l++)
            {
                str = Console.ReadLine().Split();
                var s = Int32.Parse(str[0]);
                var t = Int32.Parse(str[1]);
                var d = Int32.Parse(str[2]);
                bellmanFord.Edge.Add(new BellmanFord.edge(s, t, d));
            }

            var dist = bellmanFord.GetShortestPath(r);

            for (int i = 0; i < V; i++)
            {
                Console.WriteLine(i >= dist.Length ? "0" : dist[i] == Int32.MaxValue ? "INF" : string.Format("{0}", dist[i]));
            }
        }
    }
}

