namespace ConsoleApplication1
{
    class Edge : IComparable
    {
        internal int to;
        internal int cost;

        public Edge(int to, int cost)
        {
            this.to = to;
            this.cost = cost;
        }

        public int CompareTo(object obj)
        {
            Edge temp = obj as Edge;
            return cost - temp.cost;
        }
    }

    class Program
    {
        static void Main(string[] args)
        {
            string[] input = Console.ReadLine().Split(' ');
            int V = int.Parse(input[0]);
            int E = int.Parse(input[1]);
            int r = int.Parse(input[2]);

            Dictionary<int, List<Edge>> nodeList = new Dictionary<int, List<Edge>>();
            for (int i = 0; i < V; i++) nodeList.Add(i, new List<Edge>());

            int s, t, d;
            for (int i = 0; i < E; i++)
            {
                input = Console.ReadLine().Split(' ');
                s = int.Parse(input[0]);
                t = int.Parse(input[1]);
                d = int.Parse(input[2]);

                nodeList[s].Add(new Edge(t, d));
            }

            Dijkstra(nodeList, r);
        }

        static void Dijkstra(Dictionary<int, List<Edge>> NL, int start)
        {
            int len = NL.Count, INFTY = int.MaxValue;

            PriorityQueue<Edge> pq = new PriorityQueue<Edge>((a, b) => a.cost - b.cost);
            int[] dp = Enumerable.Repeat(INFTY, len).ToArray();
            bool[] isVisit = new bool[len];

            dp[start] = 0;
            pq.Enqueue(new Edge(start, 0));

            while (pq.Count > 0)
            {
                Edge edge = pq.Dequeue();
                int cur = edge.to;
                isVisit[cur] = true;

                if (dp[cur] < edge.cost) continue;

                int outDegree = NL[cur].Count;

                for (int j = 0; j < outDegree; j++)
                {
                    int next = NL[cur][j].to;

                    if (isVisit[next] == true) continue;

                    if (dp[next] > dp[cur] + NL[cur][j].cost)
                    {
                        dp[next] = dp[cur] + NL[cur][j].cost;
                        pq.Enqueue(new Edge(next, dp[next]));
                    }
                }
            }

            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < len; i++)
            {
                sb.AppendLine(dp[i] == INFTY ? "INF" : dp[i].ToString());
            }
            Console.Write(sb);
        }
    }

    public class PriorityQueue<T>
    {
        List<T> list = new List<T>();
        IComparer<T> comp = Comparer<T>.Default;

        class Comparer : IComparer<T>
        {
            Comparison<T> comparison;
            public Comparer(Comparison<T> comparison) { this.comparison = comparison; }
            public int Compare(T x, T y) { return comparison(x, y); }
        }

        public PriorityQueue() { }
        public PriorityQueue(Comparison<T> comp) { this.comp = new Comparer(comp); }

        public void Enqueue(T item)
        {
            int i = list.BinarySearch(item, comp); list.Insert(i < 0 ? ~i : i, item);
        }

        public T Dequeue()
        {
            T r = list[0]; list.RemoveAt(0); return r;
        }

        public T Peek() { return list[0]; }
        public int Count { get { return list.Count; } }
        public T this[int i] { get { return list[i]; } set { list[i] = value; } }
    }
}

