        foreach (var x in ret)
            if (x.Value.d == 9999999) Console.WriteLine("INF");
            else Console.WriteLine(x.Value.d);
    }
    public static void goDijk(Dictionary<int, Node> dict, int[,] a, int r, int n)
    {
        dict[r].d = 0;
        while (dict.Count(x => x.Value.fix == false) > 0)
        {
            var targ = dict.Where(x => x.Value.fix == false).OrderBy(x => x.Value.d).First().Key;
            dict[targ].fix = true;
            var nowfix = dict[targ].d;
            for (int i = 0; i < n; i++)
            {
                if (a[targ, i] != -1 && a[targ, i] != 0 && (nowfix + a[targ, i]) < dict[i].d)
                    dict[i].d = nowfix + a[targ, i];
            }
        }
    }
}

