        public int Number;

        public int CompareTo(ComparablePair other)
        {
            return ShortestDistance.CompareTo(other.ShortestDistance);
        }
    }

    public static int V;
    public static List<DjkEdge>[] Edges;
    public static int[] ShortestDistances;

    public static void InitializeDijkstra(int e,int v, List<Edge> es)
    {
        Edges = new List<DjkEdge>[e];
        for (int i = 0; i < e; i++)
        {
            Edges[i] = new List<DjkEdge>();
        }
        ShortestDistances = new int[v];
        V = v;
        foreach (var item in es)
        {
            Edges[item.From].Add(new DjkEdge() { Cost = item.Cost, To = item.To });
        }
