    public static void SearchShortestDistance(int s)
    {
        var queue = new PriorityQueue<ComparablePair>();
        for (int i = 0; i < V; i++)
        {
            ShortestDistances[i] = INF;
        }
        ShortestDistances[s] = 0;
        queue.Push(new ComparablePair() { Number = s, ShortestDistance = 0 });
        while (queue.Count != 0)
        {
            var p = queue.Pop();
            int v = p.Number;
            if (ShortestDistances[v] < p.ShortestDistance)
            {
                continue;
            }
            for (int i = 0; i < Edges[v].Count(); i++)
            {
                var e = Edges[v][i];
                if (ShortestDistances[e.To] > ShortestDistances[v] + e.Cost)
                {
                    ShortestDistances[e.To] = ShortestDistances[v] + e.Cost;
                    queue.Push(new ComparablePair() { ShortestDistance = ShortestDistances[e.To], Number = e.To });
                }
            }
        }
    }


    class PriorityQueue<T> where T : IComparable<T>
    {
        List<T> buffer;

        public PriorityQueue() { buffer = new List<T>(); }
        public PriorityQueue(int capacity) { buffer = new List<T>(capacity); }

        static void PushHeap(List<T> array, T elem)
        {
            int n = array.Count;
            array.Add(elem);

            while (n != 0)
            {
                int i = (n - 1) / 2;
                if (array[n].CompareTo(array[i]) > 0)
                {
                    T tmp = array[n]; array[n] = array[i]; array[i] = tmp;
                }
                n = i;
            }
        }


        static void PopHeap(List<T> array)
        {
            int n = array.Count - 1;
            array[0] = array[n];
            array.RemoveAt(array.Count - 1);

            for (int i = 0, j; (j = 2 * i + 1) < n;)
            {
                if ((j != n - 1) && (array[j].CompareTo(array[j + 1]) < 0))
                    j++;
                if (array[i].CompareTo(array[j]) < 0)
                {
                    T tmp = array[j]; array[j] = array[i]; array[i] = tmp;
                }
                i = j;
            }
        }


        public void Push(T elem)
        {
            PushHeap(this.buffer, elem);
        }


