func main() {
	var V, E, r int
	fmt.Scanf("%d %d %d", &V, &E, &r)

	edges := make([][]edge, V)
	nodes := make([]*node, V)
	queue := make(PriorityQueue, 0)

	for i := 0; i < E; i++ {
		var s, t int
		var cost int64
