	for i := 0; i < v; i++ {
		if i != r {
			d[i] = inf
		}
	}
	queue := []int{r}
	for len(queue) != 0 {
		nextQueue := []int{}
		for _, node := range queue {
			for _, e := range edgeMap[node] {
				debug(node, d[e.to], d[node], e.cost)
				if d[e.to] > d[node]+e.cost {
					d[e.to] = d[node] + e.cost
					nextQueue = append(nextQueue, e.to)
				}
			}
		}
		debug("nextQueue", nextQueue)
		queue = nextQueue
	}
	for i := 0; i < v; i++ {
		if d[i] != inf {
			fmt.Println(d[i])
		} else {
			fmt.Println("INF")
		}

	}
}

