func solve(scanner *bufio.Scanner, writer *bufio.Writer) {
	n := getNextInt(scanner)
	m := getNextInt(scanner)
	r := getNextInt(scanner)
	ee := make([][]edge, n)
	for i := 0; i < m; i++ {
		u := getNextInt(scanner)
		v := getNextInt(scanner)
		w := getNextInt(scanner)
		appendEdge(u, v, i, w, ee)
	}
	ww := make([]int64, n)
	for i := 0; i < n; i++ {
		ww[i] = math.MaxInt64
	}
	dd := &daikes{}
	heap.Init(dd)
	heap.Push(dd, newDaike(0, r))
	for dd.Len() > 0 {
		p := heap.Pop(dd).(daike)
		if ww[p.i] <= p.w {
			continue
		}
		ww[p.i] = p.w

		for _, e := range ee[p.i] {
			w := p.w + int64(e.w)
			if ww[e.to] <= w {
				continue
			}
			heap.Push(dd, newDaike(w, e.to))
		}
	}
	for i := 0; i < n; i++ {
		if ww[i] == math.MaxInt64 {
			fmt.Fprintln(writer, "INF")
			continue
		}
		fmt.Fprintln(writer, ww[i])
	}
}

