	sc.Split(bufio.ScanWords)
	V, E, r := nextInt(), nextInt(), nextInt()
	g := make(Graph, V)

	for i := 0; i < E; i++ {
		s, t, d := nextInt(), nextInt(), nextInt()
		g.AddEdge(s, t, d)
	}

	dist := g.dijkstra(r)

	for _, d := range dist {
		if d == INF {
			fmt.Println("INF")
		} else {
			fmt.Println(d)
		}
	}
}

