enum INF = (1 << 30);
alias Edge = Tuple!(long, "dst", long, "cost");

long[] dijkstra(in Edge[][] tree, long start) {
  alias PriorityQueue = BinaryHeap;
  alias tie = TypeTuple;

  size_t V = tree.length;
  auto dist = new long[V];
  fill(dist, INF);

  auto queue = new PriorityQueue!(Array!Edge, "a.cost >= b.cost")();

  dist[start] = 0;
  queue.insert(Edge(start, 0));
  while (!queue.empty()) {
    long v;
    long cost;
    tie!(v, cost) = queue.front();
    queue.popFront();

    if (dist[v] < cost) {
      continue;
    }
    foreach (const ref Edge e; tree[v]) {
      if (dist[v] + e.cost < dist[e.dst]) {
        dist[e.dst] = dist[v] + e.cost;
        queue.insert(Edge(e.dst, dist[e.dst]));
      }
    }
  }

  return dist;
}

