def sp_dijkstra(graph, s):
    def push_node(v):
        if v in index:
            index[v][2] = False
        node = [dists[v], v, True]
        heappush(nodes, node)
        index[v] = node

    def pop_node():
        while nodes:
            node = heappop(nodes)
            if node[2]:
                return node[1]
        return None

    def relax(edge):
        s, t, w = edge
        if dists[t] > dists[s] + w:
            dists[t] = dists[s] + w
            srcs[t] = s
            push_node(t)

    nodes = []
    index = {}
    dists = [WEIGHT_MAX] * graph.v
    dists[s] = 0
    srcs = [-1] * graph.v

    v = s
    while v is not None:
        for e in graph.adj(v):
            relax(e)
        v = pop_node()

    return [None if dists[v] == WEIGHT_MAX else dists[v]
            for v in range(graph.v)]


