        d, now = p[0], p[1]

        if dist[now] < d:
            continue

        for e in graph[now]:
            if dist[e[0]] <= d + e[1]:
                continue

            dist[e[0]] = dist[now] + e[1]
            que.put((dist[e[0]], e[0]))

    return dist


