class MinTree:
    class Cell:
        def __init__(self):
            self.value = 99999999999999
            self.right = None
            self.left = None
            self.parent = None

    def __init__(self):
        self.top = self.Cell()
        self.cell = self.Cell()
        self.cell.parent = self.top
        self.top.left = self.cell

    def insert(self, value, cell):
        if(cell.value == 99999999999999):
            cell.value = value
        else:
            cell = self.find(cell)
            if(cell.left == None):
                cell.left = self.Cell()
                cell.left.parent = cell
                cell.left.value = value
                while(True):
                    if(cell.value > cell.left.value):
                        if(cell.parent.right == cell):
                            cell.parent.right = cell.left
                        else:
                            cell.parent.left = cell.left
                        cell,cell.left = self.replace(cell,cell.left)
                    else:
                        break
            elif(cell.right == None):
                cell.right = self.Cell()
                cell.right.parent = cell
                cell.right.value = value
                while(True):
                    if(cell.value > cell.right.value):
                        if(cell.parent.right == cell):
                            cell.parent.right = cell.right
                        else:
                            cell.parent.left = cell.right
                        cell,cell.right = self.replace(cell,cell.right)
                    else:
                        break

    def replace(self,cell1,cell2):
        swap = self.Cell()
        swap.value = cell1.value
        swap.left = cell1.left
        swap.right = cell1.right
        swap.parent = cell1.parent
        cell1.value = cell2.value
        cell1.left = cell2.left
        cell1.right = cell2.right
        cell1.parent = cell2.parent
        cell2.value = swap.value
        cell2.left = swap.left
        cell2.right = swap.right
        cell2.parent = swap.parent

        return cell1,cell2

    def printTree(self,cell):
        if(cell.left != None):
            self.printTree(cell.left)
        print(cell.value)
        if(cell.right != None):
            self.printTree(cell.right)

    def find(self,cell):
        if(cell.left == None):
            return cell
        else:
            return self.find(cell.left)

        if(cell.right == None):
            return cell
        else:
            return self.find(cell.right)



