def dijkstra(N, Adj, s):
    d = [inf] * N
    p = [-1] * N
    fixed = [False] * N
    d[s] = 0
    p[s] = s
    pq = [(0, s)]

    for i in range(N - 1):
        while pq:
            di, v = heappop(pq)

            if not fixed[v] and di == d[v]:
                break

        fixed[v] = True

        for u, c in Adj[v]:
            if d[v] + c < d[u]:
                d[u] = d[v] + c
                p[u] = v
                heappush(pq, (d[u], u))

    return d

