class Dijkstra:
    def __init__(self, node_size, inf):
        self.node_size = node_size
        self.inf = inf
        self.edges = [[] for _ in range(node_size)]
        self.dist = [inf for _ in range(node_size)]

    def add_edge(self, start, end, cost):
        self.edges[start].append((end, cost))

    def solve(self, init_node):
        self.dist[init_node] = 0
        init_dist = 0
        heap = []
        hq.heapify(heap)
        hq.heappush(heap, (init_node, init_dist))

        while heap:
            cur_node, cur_dist = hq.heappop(heap)
            for next_node, cost in self.edges[cur_node]:
                if cost + cur_dist < self.dist[next_node]:
                    self.dist[next_node] = cost + cur_dist
                    hq.heappush(heap, (next_node, cost + cur_dist))
        return self.dist

