def solve(V, E, R, G):
    dists = [-1] * V
    q = []
    heapq.heappush(q, (0, R))
    while q:
        d, i = heapq.heappop(q)
        if dists[i] != -1:
            continue
        dists[i] = d
        for j, e in G[i].items():
            if dists[j] == -1:
                heapq.heappush(q, (d + e, j))
    return ['INF' if d == -1 else d for d in dists]


