class Node():
    def __init__(self, id, w):
        self.id = id
        self.weight = w

    def __str__(self):
        return "id: {}\t weight:{}".format(self.id, self.weight)

    def __lt__(self, other):
        return self.weight < other.weight

class WeightDirectedGraph():    
    def __init__(self, V):
        self.G = {i: [] for i in range(V)}
        self.V = V
        self.INF = 10**10

    def append(self, a, b, w):
        self.G[a].append(Node(b, w))

    def dijkstra(self, s):
        # distance from s
        D = [self.INF] * self.V
        D[s] = 0

        # node with minimum distance
        H = []
        heapq.heappush(H, Node(s, D[s]))

        while len(H) > 0:
            u = heapq.heappop(H)
            if D[u.id] >= u.weight:
                # update distance
                for v in self.G[u.id]:
                    w = u.weight + v.weight
                    if D[v.id] > w:
                        D[v.id] = w
                        heapq.heappush(H, Node(v.id, D[v.id]))
        return D


