inf = float('inf')

def inf_matrix(n):
    return [[inf for i in range(n)] for j in range(n)]

def sssp(r, w):
    V = len(w)
    result = inf_matrix(V)
    rest = list(range(V))
    rest.remove(r)
    var = [r]
    result[r][r] = 0

    while len(rest) > 0:
        costs = []
        for v in var:
            for res in rest:
                costs.append((result[r][v] + w[v][res], res))
        min_w, min_r = min(costs)
        if min_w == inf:
            break
        rest.remove(min_r)
        var.append(min_r)
        result[r][min_r] = min_w

    return result


