inf = float('inf')

def inf_matrix(n):
    return [[inf for i in range(n)] for j in range(n)]

def dijkstra(r, w):
    V = len(w)
    result = [inf] * V
    used = [False] * V
    q = []
    heappush(q, (0, r))

    while len(q) > 0:
        min_w, min_next = heappop(q)
        if used[min_next]:
            continue
        used[min_next] = True
        result[min_next] = min_w
        for nxt, weight in enumerate(w[min_next]):
            if result[nxt] <= min_w + weight:
                continue
            heappush(q, (min_w + weight, nxt))

    return result


