from heapq import heappush, heappop, heapify

def dijkstra(V, E, edge, r=0):
    dist = [float('inf')] * V
    dist[r] = 0
    visited = [False] * V
    visited[r] = True

    q = edge[r]
    heapify(q)
    count = V-1

    while count and q:
        c, v = heappop(q)

        if visited[v]: continue

        count -= 1
        visited[v] = True
        dist[v] = c

        for cc, u in edge[v]:
            if not visited[u]: heappush(q, (c+cc, u))

    return dist

