        AdjListGraph {
            adj_list: vec![std::vec::Vec::<Edge>::new(); n],
        }
    }

    fn add_edge(&mut self, e: Edge) {
        self.adj_list[e.from].push(e);
    }

    fn edges(&self, v: usize) -> &std::vec::Vec<Edge> {
        &self.adj_list[v]
    }

