        self.adj_list.len()
    }
}

#[allow(dead_code)]
fn dijkstra(g: &AdjListGraph, s: usize) -> std::vec::Vec<i32> {
    let mut d = vec![INF; g.node_size()];
    d[s] = 0;
    let mut que: BinaryHeap<(i32, usize)> = BinaryHeap::new();
    que.push((0, s));
    while !que.is_empty() {
        let (cur_d, v) = que.pop().unwrap();
        if d[v] < -cur_d {
            continue;
        }
        for ref e in g.edges(v) {
            if d[e.to] > -cur_d + e.weight {
                d[e.to] = -cur_d + e.weight;
                que.push((-d[e.to], e.to));
            }
        }
    }
    d
}

