use std::collections::vec_deque::*;
use std::cmp::max;

pub fn scaling_dijkstra_s3p<'a,V,E,G,F>(g: &'a G, s: Vite,fp: F) -> Vec<Option<usize>>
where V: Vertex ,E: Edge,G: Graph<'a,V,E>, F: Fn(&E) -> usize {
    let n = g.v_size();
    let mut mv = usize::zero();
    for i in 0..n {
        for e in g.delta(&Vite(i)) {
            mv = max(mv, fp(g.edge(e)));
        }
    }
    let mut cnt = 0usize;
    while mv > usize::zero() {
        mv = mv >> 1;
        cnt += 1;
    }

    let mut dist = vec![Some(usize::zero()); n];

    for k in (0..cnt+1).rev() {
        for i in 0..n {
            dist[i] = match dist[i] {
                Some(d) => Some(d * 2),
                None => None
            }
        }
        let mut temp = vec![None; n];
        temp[s.0] = Some(usize::zero());

        let mut vec : Vec<VecDeque<Vite>> = vec![VecDeque::<Vite>::new();n + 10];
        vec[0].push_back(s);

        for d in 0..vec.len() {
            while let Some(v) = vec[d].pop_front() {
                if temp[v.0].unwrap() < d { continue; }
                for ei in g.delta(&v) {
                    let e = g.edge(ei);
                    let to = to(v, e);
                    if dist[to.0] == None { continue; }
                    let c = (fp(e) >> k) + dist[v.0].unwrap() - dist[to.0].unwrap();
                    if d + c >= vec.len() { continue; }
                    if temp[to.0] == None {
                        temp[to.0] = Some(d + c);
                        vec[d + c].push_back(to);
                    }
                    else if temp[to.0].unwrap() > d + c {
                        temp[to.0] = Some(d + c);
                        vec[d + c].push_back(to);
                    }
                }
            }
        }

        for i in 0..n {
            dist[i] = if let (Some(d) , Some(t)) = (dist[i] , temp[i]) {
                Some(d + t)
            }
            else {
                None
            }
        }
    }
    dist
}

fn main() {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    let v:Vec<usize> = s.trim().split_whitespace()
        .map(|e|e.parse().unwrap()).collect();
    let (n,m,r) = (v[0] , v[1] , v[2]);
    let mut g = DirectedGraph::<usize, (usize,usize,usize)>::new(n);
    for _ in 0..m{
        let mut t = String::new();
        std::io::stdin().read_line(&mut t).unwrap();
        let x:Vec<usize> = t.trim().split_whitespace()
            .map(|e|e.parse().unwrap()).collect();
        let (v,u,d) = (x[0],x[1],x[2]);
        g.add_edge((v,u,d));
    }
    let res = scaling_dijkstra_s3p(&g, Vite(r), |w| w.2);
    for d in res {
        match d {
            Some(i) => println!("{}" , i),
            None => println!("INF")
        }
    }
}

