}

#[derive(PartialEq, Eq, Clone, Copy)]
struct DijkstraState(usize, Weight);

impl Ord for DijkstraState {
    fn cmp(&self, other: &DijkstraState) -> Ordering {
        other.1.cmp(&self.1)
    }
}

impl PartialOrd for DijkstraState {
    fn partial_cmp(&self, other: &DijkstraState) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

pub fn dijkstra(graph: &Graph, src: usize) -> Vec<Option<Weight>> {
    let inf = Weight::max_value() / 2;
    let n = graph.len();
    let mut heap = BinaryHeap::<DijkstraState>::with_capacity(n);
    heap.push(DijkstraState(src, 0));
    let mut dist = vec![inf; n];
    dist[src] = 0;
    while let Some(DijkstraState(v, d)) = heap.pop() {
        if dist[v] == d {
            for e in graph[v].iter() {
                if dist[e.dst] > d + e.weight {
                    dist[e.dst] = d + e.weight;
                    heap.push(DijkstraState(e.dst, dist[e.dst]));
                }
            }
        }
    }
    dist.iter().map(|&d| if d != inf { Some(d) } else { None }).collect()
}

pub fn dijkstra_to(graph: &Graph, src: usize, dst: usize) -> Option<Weight> {
    let inf = Weight::max_value() / 2;
    if src == dst {
        Some(0)
    } else {
        let mut heap = BinaryHeap::new();
        heap.push(DijkstraState(src, 0));
        let mut dist = vec![inf; graph.len()];
        dist[src] = 0;
        let mut res = None;
        while let Some(DijkstraState(v, d)) = heap.pop() {
            if v == dst {
                res = Some(d);
                break;
            }
            if dist[v] == d {
                for e in graph[v].iter() {
                    if dist[e.dst] > d + e.weight {
                        dist[e.dst] = d + e.weight;
                        heap.push(DijkstraState(e.dst, dist[e.dst]));
                    }
                }
            }
        }
        res
    }
}

pub fn bidirectional_dijkstra(graph: &Graph, src: usize, dst: usize) -> Option<Weight> {
    if src == dst {
        Some(0)
    } else {
        let inf: Weight = Weight::max_value() / 2;

        let n = graph.len();
        let mut heaps = BinaryHeap::with_capacity(n);
        let mut heapd = BinaryHeap::with_capacity(n);
        heaps.push(DijkstraState(src, 0));
        heapd.push(DijkstraState(dst, 0));
        let mut dists = vec![inf; n];
        let mut distd = vec![inf; n];
        dists[src] = 0;
        distd[dst] = 0;

        let mut mu = inf;

        while let Some((DijkstraState(v, d), heap, dist, dist_)) = {
            let ds = heaps.peek().unwrap_or(&DijkstraState(0, inf)).1;
            let dd = heapd.peek().unwrap_or(&DijkstraState(0, inf)).1;
            if ds + dd >= mu {
                None
            } else if ds <= dd {
                heaps.pop().map(|x| (x, &mut heaps, &mut dists, &mut distd)) 
            } else {
                heapd.pop().map(|x| (x, &mut heapd, &mut distd, &mut dists)) 
            }
        } {
            if dist[v] == d {
                for e in graph[v].iter() {
                    if dist[e.dst] > d + e.weight {
                        dist[e.dst] = d + e.weight;
                        heap.push(DijkstraState(e.dst, dist[e.dst]));
                        mu = min(mu, dist[e.dst] + dist_[e.dst]);
                    }
                }
            }
        }

        if mu != inf {
            Some(mu)
        } else {
            None
        }
    }
}

pub fn directed_bidirectional_dijkstra(graph: &Graph, src: usize, dst: usize) -> Option<Weight> {
    if src == dst {
        Some(0)
    } else {
        let inf: Weight = Weight::max_value() / 2;

        let n = graph.len();

        let mut rev_graph = vec![vec![]; n];
        for es in graph.iter() {
            for e in es.iter() {
                add_weighted_arc(&mut rev_graph, e.dst, e.src, e.weight);
            }
        }
        let mut heaps = BinaryHeap::with_capacity(n);
        let mut heapd = BinaryHeap::with_capacity(n);
        heaps.push(DijkstraState(src, 0));
        heapd.push(DijkstraState(dst, 0));
        let mut dists = vec![inf; n];
        let mut distd = vec![inf; n];
        dists[src] = 0;
        distd[dst] = 0;

        let mut mu = inf;

        while let Some((DijkstraState(v, d), heap, dist, dist_, grp)) = {
            let ds = heaps.peek().unwrap_or(&DijkstraState(0, inf)).1;
            let dd = heapd.peek().unwrap_or(&DijkstraState(0, inf)).1;
            if ds + dd >= mu {
                None
            } else if ds <= dd {
                heaps.pop().map(|x| (x, &mut heaps, &mut dists, &mut distd, graph)) 
            } else {
                heapd.pop().map(|x| (x, &mut heapd, &mut distd, &mut dists, &rev_graph)) 
            }
        } {
            if dist[v] == d {
                for e in grp[v].iter() {
                    if dist[e.dst] > d + e.weight {
                        dist[e.dst] = d + e.weight;
                        heap.push(DijkstraState(e.dst, dist[e.dst]));
                        mu = min(mu, dist[e.dst] + dist_[e.dst]);
                    }
                }
            }
        }

        if mu != inf {
            Some(mu)
        } else {
            None
        }
    }
}

