#[derive(Clone, Debug)]
pub struct WeightedGraph<T> {
    graph: Vec<Vec<(usize, T)>>,
}
impl<T: Clone> WeightedGraph<T> {
    pub fn new(n: usize) -> WeightedGraph<T> {
        WeightedGraph {
            graph: vec![vec![]; n],
        }
    }
    pub fn add_edge(&mut self, u: usize, v: usize, c: T) {
        self.graph[u].push((v, c))
    }
}
#[derive(Eq, PartialEq, Clone, Debug)]
pub struct Rev<T>(pub T);
impl<T: PartialOrd> PartialOrd for Rev<T> {
    fn partial_cmp(&self, other: &Rev<T>) -> Option<std::cmp::Ordering> {
        other.0.partial_cmp(&self.0)
    }
}
impl<T: Ord> Ord for Rev<T> {
    fn cmp(&self, other: &Rev<T>) -> std::cmp::Ordering {
        other.0.cmp(&self.0)
    }
}
impl WeightedGraph<usize> {
    pub fn dijkstra(&self, s: usize) -> Vec<usize> {
        use std::collections::BinaryHeap;
        const INF: usize = std::usize::MAX;
        let mut cost = vec![INF; self.graph.len()];
        let mut heap = BinaryHeap::new();
        cost[s] = 0;
        heap.push((Rev(0), s));
        while let Some((d, u)) = heap.pop() {
            let d = d.0;
            for &(v, c) in self.graph[u].iter() {
                if cost[v] > d + c {
                    cost[v] = d + c;
                    heap.push((Rev(d + c), v));
                }
            }
        }
        cost
    }
}
fn main() {
    input! { n, m, r, edges: [(usize, usize, usize); m] };
    let mut g = WeightedGraph::new(n);
    for &(s, t, d) in &edges {
        g.add_edge(s, t, d);
    }
    let cost = g.dijkstra(r);
    for i in 0..n {
        if cost[i] == std::usize::MAX {
            println!("INF");
        } else {
            println!("{}", cost[i]);
        }
    }
}

