        use std::collections::{BinaryHeap, HashMap};
        pub fn shortest_path(g: &Graph, s: usize)
         -> (HashMap<usize, Weight>, HashMap<usize, usize>) {
            let mut dist = HashMap::new();
            let mut prev = HashMap::new();
            let mut queue = BinaryHeap::new();
            dist.insert(s, 0);
            queue.push(State{cost: 0, pos: s, last_pos: s,});
            while let Some(State { cost, pos, last_pos }) = queue.pop() {
                if prev.contains_key(&pos) { continue ; }
                prev.insert(pos, last_pos);
                for e in &g[pos] {
                    let npos = e.dst;
                    let ncost = cost + e.weight;
                    if dist.get(&npos).unwrap_or(&Weight::max_value()) >
                           &ncost {
                        dist.insert(npos, ncost);
                        queue.push(State{cost: ncost,
                                         pos: npos,
                                         last_pos: pos,});
                    }
                }
            }
            (dist, prev)
        }
        pub fn build_path(prev: &HashMap<usize, usize>, t: usize)
         -> Option<Vec<usize>> {
            let mut path = Vec::new();
            let mut u = t;
            loop  {
                path.push(u);
                match prev.get(&u) {
                    Some(&next) if u == next => { break ; }
                    Some(&next) => { u = next; }
                    None => { return None; }
                };
            }
            path.reverse();
            Some(path)
        }
        #[derive(Copy, Clone, Eq, PartialEq)]
        struct State {
            cost: Weight,
            pos: usize,
            last_pos: usize,
        }
        impl Ord for State {
            fn cmp(&self, other: &State) -> Ordering {
                other.cost.cmp(&self.cost).then_with(||
                                                         self.pos.cmp(&other.pos)).then_with(||
                                                                                                 self.last_pos.cmp(&other.last_pos))
            }
        }
        impl PartialOrd for State {
            fn partial_cmp(&self, other: &State) -> Option<Ordering> {
                Some(self.cmp(other))
            }
        }
