#[derive(PartialEq, Eq, Clone, Copy)]
struct DijkstraState(usize, Weight);

impl Ord for DijkstraState {
    fn cmp(&self, other: &DijkstraState) -> Ordering {
        // other.1.cmp(&self.1).then_with(|| self.0.cmp(&other.0))
        let c = other.1.cmp(&self.1);
        if c != Ordering::Equal {
            c
        } else {
            self.0.cmp(&other.0)
        }
    }
}

impl PartialOrd for DijkstraState {
    fn partial_cmp(&self, other: &DijkstraState) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

pub fn dijkstra(graph: &Graph, src: usize) -> Vec<Option<Weight>> {
    let INF = Weight::max_value();
    let mut heap = BinaryHeap::<DijkstraState>::new();
    heap.push(DijkstraState(src, 0));
    let mut dist = vec![INF; graph.len()];
    dist[src] = 0;
    while let Some(DijkstraState(v, d)) = heap.pop() {
        if dist[v] == d {
            for e in graph[v].iter() {
                if dist[e.dst] > d + e.weight {
                    dist[e.dst] = d + e.weight;
                    heap.push(DijkstraState(e.dst, dist[e.dst]));
                }
            }
        }
    }
    dist.iter().map(|&d| if d != INF { Some(d) } else { None }).collect()
}

pub fn dijkstra_to(graph: &Graph, src: usize, dst: usize) -> Option<Weight> {
    if src == dst {
        Some(0)
    } else {
        let mut heap = BinaryHeap::new();
        heap.push(DijkstraState(src, 0));
        let mut dist = vec![Weight::max_value(); graph.len()];
        dist[src] = 0;
        let mut res = None;
        while let Some(DijkstraState(v, d)) = heap.pop() {
            if v == dst {
                res = Some(d);
                break;
            }
            if dist[v] == d {
                for e in graph[v].iter() {
                    if dist[e.dst] > d + e.weight {
                        dist[e.dst] = d + e.weight;
                        heap.push(DijkstraState(e.dst, dist[e.dst]));
                    }
                }
            }
        }
        res
    }
}

pub fn bidirectional_dijkstra(graph: &Graph, src: usize, dst: usize) -> Option<Weight> {
    if src == dst {
        Some(0)
    } else {
        let INF: Weight = Weight::max_value();
        let n = graph.len();
        let mut heaps = [BinaryHeap::new(), BinaryHeap::new()];
        heaps[0].push(DijkstraState(src, 0));
        heaps[1].push(DijkstraState(dst, 0));
        let mut dists = [vec![INF; n], vec![INF; n]];
        dists[0][src] = 0;
        dists[1][src] = 0;

        let mut mu = INF;

        while !heaps[0].is_empty() && !heaps[1].is_empty() {
            let k = {
                let tops = [heaps[0].peek().unwrap(), heaps[1].peek().unwrap()];
                if tops[0].1 + tops[1].1 >= mu {
                    break;
                }
                if tops[0].1 <= tops[1].1 {
                    0
                } else {
                    1
                }
            };

            let DijkstraState(v, d) = heaps[k].pop().unwrap();
            if dists[k][v] == d {
                for e in graph[v].iter() {
                    if dists[k][e.dst] > d + e.weight {
                        dists[k][e.dst] = d + e.weight;
                        heaps[k].push(DijkstraState(e.dst, dists[k][e.dst]));
                        mu = min(mu, dists[k][e.src] + e.weight + dists[k][1 - k]); 
                    }
                }
            }
        }

        if mu != INF {
            Some(mu)
        } else {
            None
        }
    }
}

