pub struct Edge {
    cost: u64,
    from: usize,
    to: usize,
}

pub fn dijkstra(graph: &Vec<Vec<Edge>>, s: &usize) -> Vec<u64> {
    use std::collections::BinaryHeap;
    let inf = 1e18 as u64;
    let mut dp = vec![inf; graph.len()];
    let mut used = vec![false; graph.len()];
    let mut que: BinaryHeap<Rev<(u64, usize)>> = BinaryHeap::new();
    que.push(Rev((0, *s)));

    while que.len() > 0 {
        let Rev((now_cost, now_v)) = que.pop().unwrap();
        if used[now_v] {
            continue;
        }
        used[now_v] = true;
        dp[now_v] = now_cost;
        for e in graph[now_v].iter() {
            if e.cost + now_cost > dp[e.to] {
                continue;
            }
            que.push(Rev((e.cost + now_cost, e.to)));
        }
    }

    return dp;
}

fn main() {
    let (v, e, r): (usize, usize, usize) = (read(), read(), read());
