        graph[s].push(Edge {
            cost: d,
            from: s,
            to: t,
        });
    }

    let dist = dijkstra(&graph, &r);
    for d in dist.iter() {
        if *d == 1e18 as u64 {
            println!("{}", "INF");
        } else {
            println!("{}", *d);
        }
    }
}

