        Some(self.cmp(other))
    }
}

impl std::cmp::Ord for Score {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        match self.score.cmp(&other.score) {
            std::cmp::Ordering::Equal => std::cmp::Ordering::Equal,
            std::cmp::Ordering::Less => std::cmp::Ordering::Greater,
            std::cmp::Ordering::Greater => std::cmp::Ordering::Less,
        }
    }
}

fn solve(graph: Vec<Vec<(usize, i64)>>, start: usize) {
    let size = graph.len();
    let mut shortest: Vec<_> = vec![std::i64::MAX; size];
    shortest[start] = 0;
    let mut from: Vec<_> = vec![size + 1; size];
    let mut min_heap: BinaryHeap<Score> = BinaryHeap::from(vec![Score::new(0, start)]);
    from[start] = start;
    while let Some(Score { score, node }) = min_heap.pop() {
        for &(to, weight) in &graph[node] {
            let alternative_path = score + weight;
            if alternative_path < shortest[to] {
                shortest[to] = alternative_path;
                from[to] = node;
                min_heap.push(Score::new(alternative_path, to));
            }
        }
    }
    for s in shortest {
        if s == std::i64::MAX {
            println!("INF");
        } else {
            println!("{}", s);
        }
    }
}

