fn shortest_path(adjl: &Vec<Vec<Edge>>, start: usize) -> Vec<usize> {
    let mut dist = vec![INF; adjl.len()];
    let mut que: BinaryHeap<(Reverse<usize>, usize)> = BinaryHeap::new();
    que.push((Reverse(0), start));
    while let Some((Reverse(c), node)) = que.pop() {
        if dist[node] < c {
            continue;
        }
        dist[node] = c;
        for next in &adjl[node] {
            if c + next.cost < dist[next.node] {
                que.push((Reverse(c + next.cost), next.node));
            }
        }
    }
    dist
}

