use std::io::Write;

#[derive(Copy, Clone, Eq, PartialEq)]
struct State {
    v: usize,
    d: u32,
}

use std::cmp::Ordering;

impl Ord for State {
    fn cmp(&self, other: &State) -> Ordering {
        other.d.cmp(&self.d)
    }
}

impl PartialOrd for State {
    fn partial_cmp(&self, other: &State) -> Option<Ordering> {
        Some(self.cmp(&other))
    }
}

fn run() {
    let out = std::io::stdout();
    let mut out = std::io::BufWriter::new(out.lock());
    input! {
        n: usize,
        edge: usize,
        src: usize,
        e: [(usize, usize, u32); edge],
    }
    let mut g = vec![vec![]; n];
    for (s, t, d) in e {
        g[s].push((t, d));
    }
    let inf = (n * 10000 + 1) as u32;
    let mut dp = vec![inf; n];
    dp[src] = 0;
    let mut h = std::collections::BinaryHeap::new();
    h.push(State{v: src, d: 0});
    while let Some(State{v, d}) = h.pop() {
        if dp[v] < d {
            continue;
        }
        for e in g[v].iter() {
            let (u, c) = *e;
            if dp[u] > d + c {
                dp[u] = d + c;
                h.push(State{v: u, d: dp[u]});
            }
        }
    }
    for d in dp.iter() {
        if *d == inf {
            writeln!(out, "INF").unwrap();
        } else {
            writeln!(out, "{}", *d).unwrap();
        }
    }
}

