        start: r,
    };

    for &(s,t,d) in std.iter() {
        dj.edges[s].push((t, d));
    }

    let distance = dj.get_shortest_path();
    for (_, d) in distance.iter().enumerate() {
        if *d == std::i64::MAX {
            println!("INF");
        }
        else {
            println!("{}", d);
        }
    }
}

