use std::f64;

use std::collections::BinaryHeap;

#[derive(Debug, Clone, Copy)]
struct Edge {
    to: usize,
    cost: i64
}

// 単一始点最短路問題 O(ElogV)
fn dijkstra(s: usize, G: Vec<Vec<Edge>>, V: usize) -> Vec<i64> {
    // 最も小さい距離のものを高速に取り出す優先度付きキュー
    let mut que = BinaryHeap::new();

    let mut d = vec![std::i64::MAX; V];
    d[s] = 0;
    que.push((0,s));

    while !que.is_empty() {
        // 最も距離の小さいものを取り出す
        let p = que.pop().unwrap();
        let v = p.1;
        // これまでの頂点vへのコストより距離が大きいならスキップ
        if d[v] < p.0 { continue; }
        // 頂点vと隣接している頂点を調べる
        for i in 0..G[v].len() {
            let e = &G[v][i];
            // この時点での頂点e.toへの最短経路より頂点vを経由して頂点e.toに行く経路の方が短いとき、最短経路を更新する
            if d[e.to] > d[v] + e.cost {
                d[e.to] = d[v] + e.cost;
                que.push((-d[e.to], e.to));
            }
        }
    }

    d
}

fn main() {
    input!{V:usize, E:usize, r:usize, p:[(usize,usize,i64);E]};
    let mut G = vec![vec![]; V];

    for (s,t,d) in p {
        G[s].push(Edge{to:t,cost:d});
    }

    let d = dijkstra(r, G, V);

    for i in 0..V {
        if d[i] == std::i64::MAX {
            println!("INF");
        } else {
            println!("{}",d[i]);
        }
    }

}

