    fn dijkstra_heap(n: usize, g: &[Vec<Edge>], s: usize) -> Vec<i64> {
        let INF = 2_000_000_001;
        let mut queue = std::collections::BinaryHeap::new();
        let mut d = vec![INF; n];

        d[s] = 0;
        queue.push((0, s));

        while let Some((cost, v)) = queue.pop() {
            let cost = -cost;
            if d[v] < cost {
                continue;
            }
            for e in &g[v] {
                let new_cost = cost + e.cost;
                if d[e.to] > new_cost {
                    d[e.to] = new_cost;
                    queue.push((-1 * new_cost, e.to));
                }
            }
        }

        d
    }
