const MAX: isize = 2147483647;

fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();

    token.parse().ok().expect("failed to parse token")
}

fn dijkstra(s: usize, n: usize, g: &Vec<Vec<(usize, isize)>>) -> Vec<isize> {
    let mut d: Vec<isize> = vec![MAX; n];
    d[s] = 0;
    let mut pq = std::collections::BinaryHeap::<(isize, usize)>::new();
    pq.push((d[s]*(-1), s));

    while !pq.is_empty() {
        let (mut tmpd, now): (isize, usize) = pq.pop().unwrap();
        if d[now] < tmpd {continue;}
        for &(to, cost) in &g[now] {
            if d[to] > d[now] + cost {
                d[to] = d[now] + cost;
                pq.push((d[to]*(-1), to));
            }
        }
    }
    d
}


