#[derive(Copy, Clone, Eq, PartialEq)]
struct State {
    cost: usize,
    position: usize,
    pre_node: usize,
}

impl Ord for State {
    // Orderingは2つの値の比較結果(<. =, >)で、次の列挙体で定義されている
    /*
    pub enum Ordering {
        Less,
        Equal,
        Greater,
    }
    */
    fn cmp(&self, other: &State) -> Ordering {
        other
            .cost
            .cmp(&self.cost)
            .then_with(|| self.position.cmp(&other.position))
    }
}

impl PartialOrd for State {
    fn partial_cmp(&self, other: &State) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

#[derive(Clone)]
struct Edge {
    node: usize,
    cost: usize,
}

fn dijkstra(adj_list: &Vec<Vec<Edge>>, start: usize) -> Option<(usize, Vec<usize>)> {
    /*
    最短経路とその経路だけ知りたければmemoをtrueに
    各地点までの最短経路数を知りたければfalseにする
    */
    let mut dist: Vec<_> = vec![usize::MAX; adj_list.len()];
    let mut pre_nodes: Vec<_> = (0..adj_list.len()).map(|i| i).collect();
    let mut heap = BinaryHeap::new();

    dist[start] = 0;
    heap.push(State {
        cost: 0,
        position: start,
        pre_node: 0,
    });

    while let Some(State {
        cost,
        position,
        pre_node,
    }) = heap.pop()
    {
        if cost > dist[position] {
            continue;
        }
        pre_nodes[position] = pre_node;

        for edge in &adj_list[position] {
            let next = State {
                cost: cost + edge.cost,
                position: edge.node,
                pre_node: position,
            };
            if next.cost < dist[next.position] {
                heap.push(next);
                dist[next.position] = next.cost;
            }
        }
    }
    return Some((0, dist));
}

