    cost: i32,
}

fn dijkstra(graph: &Vec<Vec<Edge>>, start: usize) -> Vec<i32> {
    let n = graph.len();
    let mut distance: Vec<i32> = vec![1_000_000_000; n];
    let mut visited: Vec<bool> = vec![false; n];
    let mut heap: BinaryHeap<Rev<(i32, usize)>> = BinaryHeap::new();
    heap.push(Rev((0, start))); //(cost, from)

    while !heap.is_empty() {
        let Rev((cost, from)) = heap.pop().unwrap();
        if visited[from] == true {
            continue;
        }
        visited[from] = true;
        distance[from] = cost;

        for e in &graph[from] {
            if distance[e.to] <= cost + e.cost {
                continue;
            }

            heap.push(Rev((cost + e.cost, e.to)));
        }
    }

    return distance;
}

fn main() {
    let (v, e, r): (usize, usize, usize) = (read(), read(), read());
    let mut graph: Vec<Vec<Edge>> = vec![Vec::new(); v];

    for _ in 0..e {
        let (s, t, d): (usize, usize, i32) = (read(), read(), read());
        graph[s].push(Edge { to: t, cost: d });
    }

    for ans in dijkstra(&graph, r) {
        if ans == 1_000_000_000 {
            println!("INF");
        } else {
            println!("{}", ans);
        }
    }
}

use std::collections::BinaryHeap;
use std::cmp::*;

// use graph::graph::*;

pub type Weight = i32;

#[derive(Clone, Hash, Debug, Default)]
pub struct Edge {
    pub src: usize,
    pub dst: usize,
    pub weight: Weight,
}

impl Edge {
    fn new(src: usize, dst: usize, weight: Weight) -> Edge {
        Edge {
            src: src,
            dst: dst,
            weight: weight
        }
    }
}

pub type Edges = Vec<Edge>;
pub type Graph = Vec<Edges>;

pub fn add_weighted_arc(graph: &mut Graph, src: usize, dst: usize, weight: Weight) {
    graph[src].push(Edge::new(src, dst, weight));
}

pub fn add_weighted_edge(graph: &mut Graph, src: usize, dst: usize, weight: Weight) {
    add_weighted_arc(graph, src, dst, weight);
    add_weighted_arc(graph, dst, src, weight);
}

pub fn add_arc(graph: &mut Graph, src: usize, dst: usize) {
    add_weighted_arc(graph, src, dst, 1);
}

pub fn add_edge(graph: &mut Graph, src: usize, dst: usize) {
    add_weighted_edge(graph, src, dst, 1);
}

#[derive(PartialEq, Eq, Clone, Copy)]
struct DijkstraState(usize, Weight);

impl Ord for DijkstraState {
    fn cmp(&self, other: &DijkstraState) -> Ordering {
        other.1.cmp(&self.1)
    }
}

impl PartialOrd for DijkstraState {
    fn partial_cmp(&self, other: &DijkstraState) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

pub fn dijkstra(graph: &Graph, src: usize) -> Vec<Option<Weight>> {
    let inf = Weight::max_value() / 2;
    let n = graph.len();
    let mut heap = BinaryHeap::<DijkstraState>::with_capacity(n);
    heap.push(DijkstraState(src, 0));
    let mut dist = vec![inf; n];
    dist[src] = 0;
    while let Some(DijkstraState(v, d)) = heap.pop() {
        if dist[v] == d {
            for e in graph[v].iter() {
                if dist[e.dst] > d + e.weight {
                    dist[e.dst] = d + e.weight;
                    heap.push(DijkstraState(e.dst, dist[e.dst]));
                }
            }
        }
    }
    dist.iter().map(|&d| if d != inf { Some(d) } else { None }).collect()
}

pub fn dijkstra_to(graph: &Graph, src: usize, dst: usize) -> Option<Weight> {
    let inf = Weight::max_value() / 2;
    if src == dst {
        Some(0)
    } else {
        let mut heap = BinaryHeap::new();
        heap.push(DijkstraState(src, 0));
        let mut dist = vec![inf; graph.len()];
        dist[src] = 0;
        let mut res = None;
        while let Some(DijkstraState(v, d)) = heap.pop() {
            if v == dst {
                res = Some(d);
                break;
            }
            if dist[v] == d {
                for e in graph[v].iter() {
                    if dist[e.dst] > d + e.weight {
                        dist[e.dst] = d + e.weight;
                        heap.push(DijkstraState(e.dst, dist[e.dst]));
                    }
                }
            }
        }
        res
    }
}

fn make_reversed(graph: &Graph) -> Graph {
    let n = graph.len();
    let mut reversed = vec![vec![]; n];
    for es in graph.iter() {
        for e in es.iter() {
            add_weighted_arc(&mut reversed, e.dst, e.src, e.weight);
        }
    }
    for es in reversed.iter_mut() {
        es.shrink_to_fit();
    }
    reversed
}

pub fn bidirectional_dijkstra(graph: &Graph, src: usize, dst: usize) -> Option<Weight> {
    bidirectional_dijkstra_impl(graph, graph, src, dst)
}

pub fn directed_bidirectional_dijkstra(graph: &Graph, src: usize, dst: usize) -> Option<Weight> {
    bidirectional_dijkstra_impl(graph, &make_reversed(&graph), src, dst)
}

pub fn bidirectional_dijkstra_impl(graph: &Graph, rev_graph: &Graph, src: usize, dst: usize) -> Option<Weight> {
    if src == dst {
        Some(0)
    } else {
        let inf: Weight = Weight::max_value() / 2;
        let n = graph.len();

        let mut heaps = BinaryHeap::with_capacity(n);
        let mut heapd = BinaryHeap::with_capacity(n);
        heaps.push(DijkstraState(src, 0));
        heapd.push(DijkstraState(dst, 0));
        let mut dists = vec![inf; n];
        let mut distd = vec![inf; n];
        dists[src] = 0;
        distd[dst] = 0;

        let mut mu = inf;

        while let Some((DijkstraState(v, d), heap, dist, dist_, grp)) = {
            let ds = heaps.peek().unwrap_or(&DijkstraState(0, inf)).1;
            let dd = heapd.peek().unwrap_or(&DijkstraState(0, inf)).1;
            if ds + dd >= mu {
                None
            } else if ds <= dd {
                heaps.pop().map(|x| (x, &mut heaps, &mut dists, &mut distd, graph)) 
            } else {
                heapd.pop().map(|x| (x, &mut heapd, &mut distd, &mut dists, rev_graph)) 
            }
        } {
            if dist[v] == d {
                for e in grp[v].iter() {
                    if dist[e.dst] > d + e.weight {
                        dist[e.dst] = d + e.weight;
                        heap.push(DijkstraState(e.dst, dist[e.dst]));
                        mu = min(mu, dist[e.dst] + dist_[e.dst]);
                    }
                }
            }
        }

        if mu != inf {
            Some(mu)
        } else {
            None
        }
    }
}

