    };
}

struct Combination {
    MOD: i64,
    fac: Vec<i64>,
    fac_inv: Vec<i64>,
}

impl Combination {
    pub fn new(n: i64) -> Self {
        let MOD: i64 = 1_000_000_007;
        let mut fac: Vec<i64> = vec![0; n as usize + 1];
        let mut fac_inv: Vec<i64> = vec![0; n as usize + 1];

        let get_inverse = |mut n: i64| -> i64 {
            let (mut res, mut p) = (1, MOD - 2);

            while p != 0 {
                if p & 1 == 1 {
                    res = (res * n) % MOD;
                }
                n = (n * n) % MOD;
                p >>= 1;
            }

            return res;
        };

        fac[0] = 1;

        for i in 1..n + 1 {
            fac[i as usize] = (fac[i as usize - 1] * i) % MOD;
        }

        for i in 0..n + 1 {
            fac_inv[i as usize] = get_inverse(fac[i as usize]);
        }

        Combination {
            MOD: MOD,
            fac: fac,
            fac_inv: fac_inv,
        }
    }

    fn nCr(&self, n: i64, r: i64) -> i64 {
        if n < r {
            return 0;
        }

        let a: i64 = self.fac[n as usize];
        let b: i64 = self.fac_inv[(n - r) as usize];
        let c: i64 = self.fac_inv[r as usize];
        let bc: i64 = (b * c) % self.MOD;

        return (a * bc) % self.MOD;
    }

    fn nPr(&self, n: i64, r: i64) -> i64 {
        if n < r {
            return 0;
        }

        let a: i64 = self.fac[n as usize];
        let b: i64 = self.fac_inv[(n - r) as usize];

        return (a * b) % self.MOD;
    }

    fn nHr(&self, n: i64, r: i64) -> i64 {
        if n == 0 && r == 0 {
            return 1;
        }

        return self.nCr(n + r - 1, r);
    }
}

pub trait SliceExt<T>: Iterator + Sized {
    fn vec(self) -> Vec<Self::Item> {
        self.collect()
    }
}

#[derive(Copy, Clone, Eq, PartialEq)]
struct Edge {
    to: usize,
    cost: i64,
}

fn dijkstra(graph: &Vec<Vec<Edge>>, s: usize) -> Vec<i64> {
        use std::collections::BinaryHeap;
        let mut dist = vec![1e18 as i64; graph.len()];
        let mut heap = BinaryHeap::new();
        dist[s] = 0;
        heap.push((0, s));
        while let Some((cost, v)) = heap.pop() {
            if dist[v] < cost {
                continue;
            }

            for e in &graph[v] {
                if dist[e.to] <= dist[v] + e.cost {
                    continue;
                }
                dist[e.to] = dist[v] + e.cost;
                heap.push((0, e.to));
            }
        }
        return dist;
    }


fn main() {
    input!(V: usize, E: usize, r: usize);
    let mut g = vec![Vec::new(); V];
    for _ in 0..E {
        input!(s: usize, t: usize, d: i64);
        g[s].push(Edge{to: t, cost: d});
    }

    let mut res = dijkstra(&g, r);
    for a in res {
        println!("{}", if a == 1e18 as i64 { "INF".to_string() } else { a.to_string() });
    }
}
